// pdfjs worker
    if (window.pdfjsLib) {
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
    }

// ── Main application ──────────────────────────────────────────────────────
// Set to true locally to enable verbose extraction/reconciliation tracing.
const DEBUG = false;
// ─── Supabase ─────────────────────────────────────────────────────────────────
// Project selection is host-based (see supabase-config.js): the production
// domain uses the production project; localhost and every *.vercel.app preview
// (including the pilot branch) use the isolated pilot project. supabase-config.js
// MUST be loaded before script.js — it publishes window.__MS_SUPABASE.
if (!window.__MS_SUPABASE) {
  throw new Error('[script.js] supabase-config.js must be loaded before script.js (window.__MS_SUPABASE missing)');
}
const SUPABASE_URL      = window.__MS_SUPABASE.url;
const SUPABASE_ANON_KEY = window.__MS_SUPABASE.anonKey;

// Auth email redirects (password reset, signup confirmation) must always point at the
// public production domain — never window.location.origin, which on a Vercel preview/
// branch deployment is protected by Vercel Authentication and would lock users out of
// the recovery/confirmation flow before our app code ever runs. Localhost is exempted
// so the flow is still testable in local dev.
const PUBLIC_APP_URL = /^(localhost|127\.0\.0\.1)/.test(window.location.hostname)
  ? window.location.origin
  : 'https://mainstreetcam.com';

// Where an auth email must DROP THE USER: the application, not the website.
// PUBLIC_APP_URL on its own used to be the app. It is not any more — the
// marketing page took the root, so https://mainstreetcam.com now 307s to /home,
// which loads neither supabase-config.js nor script.js. The #access_token
// fragment Supabase appends to the confirmation redirect would be carried there
// by the browser and read by nothing at all, leaving a user who had just
// confirmed their email sitting on marketing, still signed out.
//
// /app is a REWRITE rather than a redirect, so the fragment survives in the
// address bar for supabase-js (detectSessionInUrl) to pick up. Locally the app
// is still served from the root, so localhost keeps using the origin.
const APP_ENTRY_URL = /^(localhost|127\.0\.0\.1)/.test(window.location.hostname)
  ? window.location.origin
  : PUBLIC_APP_URL + '/app';


const { createClient: _sbCreateClient } = window.supabase;
const db = _sbCreateClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
  auth: {
    persistSession:     true,
    autoRefreshToken:   true,
    detectSessionInUrl: true,
    storage:            window.localStorage,
  },
});

// 🚑 Emergency fallback — never leave the screen blank
setTimeout(() => {
  const login = document.getElementById('loginScreen');
  const app   = document.getElementById('appContent');
  if (login && app && login.style.display === 'none' && app.style.display === 'none') {
    _showLogin();
  }
}, 1000);

// ─── Authentication ───────────────────────────────────────────────────────────
async function _showApp(user) {
  _lsUserId = (user && user.id) ? user.id : null;
  if (user?.id) _initDemoIds(user.id); // derive per-user demo IDs before any demo interaction
  // Close out jobs abandoned by a previous session's tab. Fire-and-forget: it
  // must never delay showing the app, and a failure here is logged, not fatal.
  try { _reapStaleLeaseJobs(); } catch (_) {}
  _lsMigrateAncillaryKeys(); // scope ancillary LS keys + re-hydrate _camYear
  initCamYearSelect();       // re-sync dropdown now that _camYear may have changed
  document.getElementById('loginScreen').style.display  = 'none';
  document.getElementById('appContent').style.display   = 'block';
  document.getElementById('setNewPasswordOverlay')?.classList.remove('visible');
  if (user?.email) document.getElementById('headerUserEmail').textContent = user.email;
  const _acNorm = window.AuthService ? window.AuthService.hydrateFromSupabaseUser(user) : null;
  if (_acNorm) {
    const _roleEl = document.getElementById('headerRoleBadge');
    if (_roleEl) { _roleEl.textContent = _acNorm.role; _roleEl.setAttribute('data-role', _acNorm.role); _roleEl.style.display = ''; }
    const _appEl = document.getElementById('appContent');
    if (_appEl) _appEl.setAttribute('data-role', _acNorm.role);
  }
}

// Someone who clicked "Log in" on the marketing page has already declared what
// they want. Show the form at once rather than making them wait on the auth
// round-trip and then click a second Sign In on whatever was rendered
// meanwhile — that intermediate state is the second click reported from the
// pilot walkthrough.
function _maybeShowLoginFromIntent() {
  try {
    if (!/[?&]signin=1/.test(location.search)) return false;
    _showLogin();
    var t = document.getElementById('loginTabSignIn');
    if (t && typeof switchAuthTab === 'function') { try { switchAuthTab('signin'); } catch (_) {} }
    var e = document.getElementById('loginEmail');
    if (e) setTimeout(function () { try { e.focus(); } catch (_) {} }, 60);
    return true;
  } catch (_) { return false; }
}

function _showLogin() {
  document.getElementById('loginScreen').style.display = 'flex';
  document.getElementById('appContent').style.display  = 'none';
  document.getElementById('setNewPasswordOverlay')?.classList.remove('visible');
}

let _authMode = 'signin'; // 'signin' | 'signup'
let _initialized = false;
let _lsUserId = null; // set in _showApp(), cleared in _clearAppState()

function _lsUserKey()   { return _lsUserId ? `_ms_props_v2_${_lsUserId}`       : '_ms_props_v2_anon'; }
function _errKey()      { return _lsUserId ? `mainstreet_errors_v1_${_lsUserId}`  : 'mainstreet_errors_v1'; }
function _cpKey()       { return _lsUserId ? `mainstreet_ckpt_v1_${_lsUserId}`    : 'mainstreet_ckpt_v1'; }
function _rvKey()       { return _lsUserId ? `mainstreet_review_v1_${_lsUserId}`  : 'mainstreet_review_v1'; }
function _camYearKey()  { return _lsUserId ? `ms_camYear_${_lsUserId}`            : 'ms_camYear_anon'; }

// SEC-9 — a legacy unscoped key belongs to whoever wrote it, and we cannot know
// who that was.
//
// This migration copied unscoped keys into the CURRENT user's scoped key. On a
// shared browser holding keys from an older build, whoever signed in FIRST
// inherited them — including `mainstreet_errors_v1`, which records email and
// role. That is a cross-tenant read, narrow but real, and the app performed it
// automatically at sign-in.
//
// There is no ownership stamp on those keys to check against, so adoption
// cannot be made safe — only refused. They are DELETED instead: the data is
// unattributable, its only consumers are diagnostics, and leaving it on disk
// keeps the leak available to the next migration someone writes.
//
// `camYear` is the one exception. It is a UI preference with no tenant content
// (an integer year), so it is migrated rather than discarded.
const _LS_UNSCOPED_UNATTRIBUTABLE = [
  'mainstreet_errors_v1',
  'mainstreet_ckpt_v1',
  'mainstreet_review_v1',
  'ms_debug_leases',
];

function _lsPurgeUnattributableKeys() {
  let purged = 0;
  for (const k of _LS_UNSCOPED_UNATTRIBUTABLE) {
    try {
      if (localStorage.getItem(k) !== null) { localStorage.removeItem(k); purged++; }
    } catch (_) {}
  }
  if (purged) console.warn(`[storage] discarded ${purged} unscoped legacy key(s) — owner unknown, not adopted`);
  return purged;
}
window._lsPurgeUnattributableKeys = _lsPurgeUnattributableKeys;

// One-time migration: if the unscoped key has data and the scoped key does not,
// move the value to the scoped key and delete the unscoped one.
function _lsMigrateAncillaryKeys() {
  if (!_lsUserId) return;
  // SEC-9 — refuse the unattributable ones before anything else runs.
  _lsPurgeUnattributableKeys();
  // Only camYear survives the SEC-9 cut: an integer year is a UI preference,
  // not tenant content, so adopting it leaks nothing. The other four carried
  // diagnostics and PII and are purged above rather than migrated.
  [
    ['camYear', _camYearKey()],
  ].forEach(function(pair) {
    var old = pair[0], scoped = pair[1];
    if (old === scoped) return;
    if (localStorage.getItem(scoped) !== null) return;
    var val = localStorage.getItem(old);
    if (val === null) return;
    try { localStorage.setItem(scoped, val); } catch (_) {}
    localStorage.removeItem(old);
  });
  // Re-hydrate _camYear from the now-scoped key
  var stored = localStorage.getItem(_camYearKey());
  if (stored) _camYear = parseInt(stored, 10) || _camYear;
}

function switchAuthTab(mode) {
  _authMode = mode;
  const isSignUp = mode === 'signup';
  document.getElementById('loginTabSignIn').classList.toggle('active', !isSignUp);
  document.getElementById('loginTabSignUp').classList.toggle('active',  isSignUp);
  document.getElementById('loginBtn').textContent = isSignUp ? 'Create Account' : 'Sign In';
  document.getElementById('loginPasswordHint').style.display = isSignUp ? '' : 'none';
  document.getElementById('loginForgotBtn').style.display    = isSignUp ? 'none' : '';
  document.getElementById('loginPassword').autocomplete = isSignUp ? 'new-password' : 'current-password';
  document.getElementById('loginMsg').className = 'login-msg';
  document.getElementById('loginMsg').textContent = '';
}

async function submitAuth(event) {
  if (event) event.preventDefault(); // prevent form reload in all browsers


  const email    = (document.getElementById('loginEmail').value    || '').trim();
  const password = (document.getElementById('loginPassword').value || '');
  const btn      = document.getElementById('loginBtn');
  const msgEl    = document.getElementById('loginMsg');

  if (!email) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Please enter your email address.';
    return;
  }
  if (!password) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Please enter a password.';
    return;
  }
  if (_authMode === 'signup' && password.length < 6) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Password must be at least 6 characters.';
    return;
  }

  btn.disabled    = true;
  btn.textContent = _authMode === 'signup' ? 'Creating account…' : 'Signing in…';
  msgEl.className = 'login-msg';
  msgEl.textContent = '';

  let data, error;
  try {
    const attemptAuth = () => _authMode === 'signup'
      ? db.auth.signUp({ email, password, options: { emailRedirectTo: APP_ENTRY_URL } })
      : db.auth.signInWithPassword({ email, password });

    const withTimeout = (promise, ms) => Promise.race([
      promise,
      new Promise((_, reject) => setTimeout(() => reject(new Error('__timeout__')), ms)),
    ]);

    // Two attempts: free-tier projects can take 20-30s to wake from pause
    try {
      ({ data, error } = await withTimeout(attemptAuth(), 20000));
    } catch (e) {
      if (e.message !== '__timeout__') throw e;
      msgEl.className   = 'login-msg';
      msgEl.textContent = 'Taking a moment — server is waking up, retrying…';
      ({ data, error } = await withTimeout(attemptAuth(), 25000));
    }
  } catch (e) {
    console.error('[Mainstreet] Auth exception:', e);
    const msg = e.message === '__timeout__'
      ? 'Connection timed out — please try again in a few seconds.'
      : (e.message || 'Network error — please check your connection and try again.');
    msgEl.className   = 'login-msg error';
    msgEl.textContent = msg;
    btn.disabled      = false;
    btn.textContent   = _authMode === 'signup' ? 'Create Account' : 'Sign In';
    return;
  }

  if (error) {
    console.error('[Mainstreet] Auth error:', error);
    msgEl.className   = 'login-msg error';
    msgEl.textContent = error.message || 'Sign-in failed — please check your credentials and try again.';
    // No alert — the inline message is sufficient
    btn.disabled      = false;
    btn.textContent   = _authMode === 'signup' ? 'Create Account' : 'Sign In';
  } else if (_authMode === 'signup') {
    // If email confirmation is disabled, signUp returns a live session immediately
    if (data?.session?.user) {
      _showApp(data.session.user);
      if (!_initialized) { _initialized = true; init(); }
    } else {
      // Switch tab first (it clears loginMsg), then write the success message
      switchAuthTab('signin');
      msgEl.className   = 'login-msg success';
      msgEl.textContent = '✓ Account created! Check your email for a confirmation link, then sign in here.';
      btn.disabled      = false;
    }
  } else if (data?.user) {
    // Explicit show — don't rely solely on onAuthStateChange firing in restricted browsers
    _showApp(data.user);
    if (!_initialized) { _initialized = true; init(); }
  }
}

async function signOut() {
  // SEC-10 — capture the id BEFORE _clearAppState() nulls it, then wipe this
  // user's local data. An explicit sign-out is the one point where the user has
  // said they are done with this device.
  const _outgoing = _lsUserId;
  if (window.AuthService) window.AuthService.clear();
  _lsClearUserData(_outgoing);
  _clearAppState();
  _initialized = false;
  _showLogin(); // Reset UI immediately — don't wait on Supabase
  try {
    await db.auth.signOut();
  } catch (e) {
    console.warn('[signOut] Supabase error:', e?.message);
  }
}

/**
 * SEC-10 — remove this user's data from disk, not just from memory.
 *
 * _clearAppState() nulled the in-memory state and left `_ms_props_v2_<uuid>`
 * and every scoped ancillary key sitting in localStorage. Another account
 * couldn't read them (the keys are UUID-scoped), but a signed-out user's whole
 * portfolio stayed on a shared machine indefinitely. "Sign out" implies the data
 * is gone from the device; it wasn't.
 *
 * Called from the sign-out path ONLY, never from the session-expiry path —
 * SEC-3 deliberately preserves work there so it can be recovered on re-entry.
 * Wiping on expiry would destroy exactly what that fix rescues.
 */
function _lsClearUserData(userId) {
  if (!userId) return 0;
  let removed = 0;
  try {
    // Enumerate rather than reconstruct: the key helpers are the source of
    // truth for the current shape, but a key written by an older build with a
    // different prefix would survive a hard-coded list.
    const doomed = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.endsWith('_' + userId)) doomed.push(k);
    }
    for (const k of doomed) { localStorage.removeItem(k); removed++; }
  } catch (e) { console.warn('[storage] could not clear user data:', e && e.message); }
  if (removed) console.log(`[storage] cleared ${removed} local key(s) for the signed-out user`);
  return removed;
}
window._lsClearUserData = _lsClearUserData;

function _clearAppState() {
  _lsUserId        = null;
  activePropId     = null;
  _props           = [];
  lastResults      = [];
  lastPropName     = '';
  lastTotal        = 0;
  lastInvoicesFull = [];
  lastFullResults  = [];
  lastInvoices     = [];
  lastTenants      = [];
  _lastReconIssues = [];
  _dwActiveDid     = null;
  nextDisputeId    = 0;
  _saveGeneration  = 0;
  if (_saveDebounceTimer) { clearTimeout(_saveDebounceTimer); _saveDebounceTimer = null; }
  camRuns.length     = 0;
  disputes.length    = 0;
  activityLog.length = 0;
  invoiceData.length = 0;
  portfolio.length   = 0;
  tenantData[0] = tenantData[1] = tenantData[2] = null;
  Object.keys(_snapshots).forEach(k => delete _snapshots[k]);
}

// Check existing session, then listen for changes
window.addEventListener('load', () => {
  initCamYearSelect();
  db.auth.getSession().then(({ data, error }) => {
    if (error) {
      _showLogin();
      return;
    }
    if (data?.session?.user) {
      _showApp(data.session.user);
      if (!_initialized) { _initialized = true; init(); }
    } else {
      _showLogin();
    }
  }).catch(e => {
    _showLogin();
  });
});

db.auth.onAuthStateChange((event, session) => {
  if (event === 'PASSWORD_RECOVERY') {
    // User clicked a password-reset email link. Show the set-new-password screen
    // instead of logging them into the app — they need to actually set a password.
    _showSetNewPassword();
  } else if ((event === 'SIGNED_IN' || event === 'INITIAL_SESSION') && session?.user) {
    // Don't show the app if we're in PASSWORD_RECOVERY flow
    if (document.getElementById('setNewPasswordOverlay')?.classList.contains('visible')) return;
    _showApp(session.user);
    if (!_initialized) {
      _initialized = true;
      init();
    }
  } else if (event === 'TOKEN_REFRESHED') {
    console.log('[Auth] Token refreshed');
  } else if (event === 'SIGNED_OUT') {
    // SEC-10 — Supabase can raise SIGNED_OUT without signOut() running (another
    // tab signed out, or the refresh token was revoked server-side). Clear disk
    // here too, or the sign-out only counts when it starts in this tab.
    _lsClearUserData(_lsUserId);
    _clearAppState();
    _initialized = false;
    _showLogin();
  }
});

function _showSetNewPassword() {
  document.getElementById('loginScreen').style.display = 'none';
  const appContent = document.getElementById('appContent');
  if (appContent) appContent.style.display = 'none';
  document.getElementById('setNewPasswordOverlay').classList.add('visible');
}

async function sendPasswordReset() {
  const email  = (document.getElementById('loginEmail').value || '').trim();
  const msgEl  = document.getElementById('loginMsg');
  const btn    = document.getElementById('loginForgotBtn');
  if (!email) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Enter your email address above, then click Forgot password?';
    return;
  }
  btn.disabled = true;
  msgEl.className   = 'login-msg';
  msgEl.textContent = 'Sending reset email…';
  try {
    const { error } = await db.auth.resetPasswordForEmail(email, {
      redirectTo: PUBLIC_APP_URL + '/reset-password',
    });
    if (error) throw error;
    msgEl.className   = 'login-msg success';
    msgEl.textContent = '✓ Reset email sent — check your inbox and click the link to set a new password.';
  } catch (e) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = e.message || 'Could not send reset email — please try again.';
  } finally {
    btn.disabled = false;
  }
}

async function submitNewPassword(event) {
  if (event) event.preventDefault();
  const pw1   = document.getElementById('newPasswordInput').value;
  const pw2   = document.getElementById('newPasswordConfirm').value;
  const btn   = document.getElementById('setNewPasswordBtn');
  const msgEl = document.getElementById('setNewPasswordMsg');

  if (!pw1 || pw1.length < 6) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Password must be at least 6 characters.';
    return;
  }
  if (pw1 !== pw2) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = 'Passwords do not match.';
    return;
  }

  btn.disabled      = true;
  btn.textContent   = 'Setting password…';
  msgEl.className   = 'login-msg';
  msgEl.textContent = '';

  try {
    const { data, error } = await db.auth.updateUser({ password: pw1 });
    if (error) throw error;
    // Password updated — hide overlay and show app
    document.getElementById('setNewPasswordOverlay').classList.remove('visible');
    const user = data?.user || (await db.auth.getUser())?.data?.user;
    if (user) {
      _showApp(user);
      if (!_initialized) { _initialized = true; init(); }
    } else {
      _showLogin();
    }
  } catch (e) {
    msgEl.className   = 'login-msg error';
    msgEl.textContent = e.message || 'Could not update password — please try again.';
    btn.disabled      = false;
    btn.textContent   = 'Set Password & Sign In';
  }
}

// ─── Constants ────────────────────────────────────────────────────────────────
const MODEL       = 'claude-sonnet-4-6';
const MAX_LEASES  = 3;

// Wraps fetch with a hard client-side abort timeout.
// Vercel Pro maxDuration is 60 s; 58 s gives a clean abort before platform kills the lambda.
/**
 * SEC-3 — the one place the app learns its session is gone.
 *
 * `_authHeaders()` returns {} when there is no session, so the request goes out
 * unauthenticated and the server correctly answers 401. Nothing on the client
 * read that 401. A manager whose refresh token expired mid-session kept working
 * in a fully-rendered UI while every save failed — and because savePropertyData
 * is debounced, the failure wasn't attached to anything they did. That is the
 * worst shape a session bug can take: silent, delayed, and indistinguishable
 * from working normally.
 *
 * ORDER MATTERS HERE. Work is preserved BEFORE anything is shown and before any
 * state is touched, because the in-memory edits are the thing being rescued.
 * _clearAppState() is deliberately NOT called: it would destroy exactly what
 * this function exists to save.
 */
let _authLostHandled = false;
function _onAuthLost(where) {
  if (_authLostHandled) return;       // one banner, not one per in-flight request
  _authLostHandled = true;
  console.warn('[auth] session lost at', where, '— preserving work locally');

  // 1. Rescue first. _lsSave writes per-property under the user-scoped key, so
  //    a re-sign-in as the same user finds it again.
  let saved = 0;
  try {
    for (const p of (Array.isArray(_props) ? _props : [])) {
      if (p && p.id) { _lsSave(p); saved++; }
    }
  } catch (e) { console.error('[auth] could not preserve work:', e && e.message); }

  // 2. Then say so. A toast is not enough for something that stops all saving —
  //    this stays on screen until acted on.
  try { _setSyncStatus('error', 'Session expired — work saved on this device'); } catch (_) {}
  try {
    _showAuthLostBanner(saved);
  } catch (e) {
    // Never let the notification path swallow the rescue.
    console.error('[auth] banner failed:', e && e.message);
    alert('Your session expired. Your work is saved on this device — sign in again to continue.');
  }
}

function _showAuthLostBanner(savedCount) {
  if (document.getElementById('msAuthLostBanner')) return;
  const bar = document.createElement('div');
  bar.id = 'msAuthLostBanner';
  bar.className = 'ms-authlost';
  bar.setAttribute('role', 'alert');
  bar.innerHTML =
    `<span class="ms-authlost-msg"><strong>Your session expired.</strong> ` +
    `${savedCount > 0
        ? `Your work on ${savedCount} propert${savedCount === 1 ? 'y is' : 'ies is'} saved on this device and will be restored when you sign back in.`
        : `Nothing was lost — no unsaved changes were pending.`} ` +
    `Changes made from now on will not be saved until you sign in.</span>` +
    `<button class="ms-authlost-btn" onclick="_reauthenticate()">Sign in again</button>`;
  document.body.appendChild(bar);
}

/**
 * Re-sign-in WITHOUT wiping state. The normal signOut() path clears app state,
 * which would discard the unsaved edits just rescued. Here the login overlay is
 * shown over the top and the in-memory work is left intact, so a successful
 * sign-in as the same user lands back on the same data.
 */
function _reauthenticate() {
  const b = document.getElementById('msAuthLostBanner');
  if (b) b.remove();
  _authLostHandled = false;
  if (window.AuthService) window.AuthService.clear();
  _showLogin();
}
window._reauthenticate = _reauthenticate;
window._onAuthLost     = _onAuthLost;

/** True for the errors Supabase/PostgREST raise when a JWT is missing or dead. */
function _isAuthError(e) {
  if (!e) return false;
  const msg  = String(e.message || e.error_description || e.error || e || '');
  const code = String(e.code || e.status || '');
  return code === '401' || code === 'PGRST301' || e.status === 401 ||
         /jwt (expired|invalid|malformed)|invalid token|not authenticated|authentication required|no api key/i.test(msg);
}
window._isAuthError = _isAuthError;

function _fetchWithTimeout(url, opts, ms = 58000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  return fetch(url, { ...opts, signal: ctrl.signal })
    .then(resp => {
      // SEC-3 — every API call in this app goes through here, which is why the
      // interception lives here rather than at each call site. A 401 means the
      // session is gone; the response is still returned so callers keep their
      // own error handling.
      if (resp && resp.status === 401) _onAuthLost(url);
      return resp;
    })
    .finally(() => clearTimeout(timer));
}

// Returns the Authorization header object for the current Supabase session.
// Returns {} (no-op spread) when unauthenticated so calls still go through
// to get a clean 401 from the server rather than silently failing client-side.
async function _authHeaders() {
  try {
    const { data } = await db.auth.getSession();
    if (!data?.session) return {};
    // Refresh if the token expires within the next 60 seconds so API routes
    // never receive an expired JWT (getSession() returns stale tokens as-is).
    const expiresAt = data.session.expires_at ?? 0;
    if (expiresAt - Date.now() / 1000 < 60) {
      const { data: r } = await db.auth.refreshSession();
      const tok = r?.session?.access_token;
      return tok ? { 'Authorization': `Bearer ${tok}` } : {};
    }
    return { 'Authorization': `Bearer ${data.session.access_token}` };
  } catch { return {}; }
}

// Single entry-point for every Claude API call.
// Proxies through /api/claude — API key stays server-side.
async function claudeFetch(body) {
  const resp = await _fetchWithTimeout('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: typeof body === 'string' ? body : JSON.stringify(body),
  });
  if (!resp.ok) {
    let detail = `HTTP ${resp.status}`;
    try { const b = await resp.json(); detail = b?.error?.message || b?.message || detail; } catch {}
    throw new Error(detail);
  }
  return resp.json();
}

async function explainFetch(body, opts = {}) {
  // Every other Claude call in this file goes through _fetchWithTimeout. This
  // one bounded the request only when a caller happened to pass timeoutMs, so
  // the default path had no AbortController and no timer: if /api/explain
  // stopped responding the await never settled, the ingestion pipeline stopped
  // silently, and the job sat at 'processing' with nothing to explain it.
  // Now always bounded — callers may still tighten or loosen the ceiling.
  const { timeoutMs } = opts;
  const fetchOpts = {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: typeof body === 'string' ? body : JSON.stringify(body),
  };
  try {
    // 90s matches /api/explain's maxDuration in vercel.json — a request that
    // outlives the function it called can never succeed.
    const resp = await _fetchWithTimeout('/api/explain', fetchOpts, timeoutMs || 90000);
    if (!resp.ok) {
      let detail = `HTTP ${resp.status}`;
      try { const b = await resp.json(); detail = b?.error?.message || b?.message || detail; } catch {}
      throw new Error(detail);
    }
    return await resp.json();
  } catch (e) {
    // The effective ceiling, not `timeoutMs` — which is now optional, so
    // reporting it directly produced "timed out after 0s" on the default path.
    if (e?.name === 'AbortError') throw new Error(`Request timed out after ${Math.round((timeoutMs || 90000) / 1000)}s`);
    throw e;
  }
}

// AI-2 — CAM_EXPLAIN_SYSTEM_PROMPT and LANDLORD_SYSTEM_PROMPT used to be
// defined here and shipped to /api/explain in the request body. Every promise
// they make — "never state a fact you were not given", "EVIDENCE names the KIND
// of document ... not a claim that the document exists", "do not invent
// problems" — was a browser string the caller could rewrite, and the server
// forwarded it to the model unread.
//
// They now live in api/_explain-tasks.js and are selected by name. The client
// says WHICH task it wants; the server decides what the model is told. They are
// deliberately not duplicated here: a copy in the client is a copy that will
// drift, and a copy that drifts is the version nobody is actually running.

// WHY single source of truth: previously there were THREE schema definitions
// (CLAUDE_LEASE_SYSTEM, CLAUDE_LEASE_PROMPT, and inline user prompts in each call
// function), each with different field names. This caused Claude to sometimes return
// fields the resolver didn't expect, silently dropping data. Now only this system
// prompt defines the canonical schema; both callClaudeForLease and
// callClaudeWithPdfDirect user prompts align to these exact field names.
// Canonical field set: tenant_name, lease_start_date, lease_end_date,
//   lease_type, sqft, cam_cap.
// The resolver in callClaudeForLease handles aliases (sqft→leased_sqft, etc.)
// for backward compatibility with any previously-cached extraction results.
// SEC-2 — CLAUDE_LEASE_SYSTEM and CLAUDE_ESCROW_SYSTEM used to be defined here
// and shipped to /api/claude in the request body, which forwarded them to
// Anthropic verbatim. They define the extraction schema itself — what counts as
// a CAM cap, how sqft is parsed, which entity is the tenant — so every
// extraction guarantee was a browser string the caller could rewrite, and its
// output flows into the fieldEvidence snapshots the Evidence Viewer presents as
// provenance.
//
// They now live in api/_claude-tasks.js and are selected by name
// ('lease_extraction' / 'escrow_extraction'), the same contract AI-2 gave
// /api/explain. Deliberately not duplicated here: a copy in the client is a
// copy that drifts, and a copy that drifts is the version nobody is running.

// ─── Phase 21: Escrow & Reserve Intelligence ─────────────────────────────────
// The escrow extraction schema moved to api/_claude-tasks.js with the lease one
// (task: 'escrow_extraction'). It still mirrors the lease schema's structure, so
// the same proxy/parsing conventions apply.

// SEC-2 — INVOICE_PROMPT and CATEGORY_PROMPT moved to api/_claude-tasks.js
// ('invoice_extraction' / 'category_classification'). They travelled in the USER
// turn beside the invoice image, which put instructions and customer data at the
// same level; they are system prompts on the server now. CATEGORIES below stays
// here — the client validates the returned category against it, which is a check
// on the model's answer, not an instruction to it.

const CATEGORIES = ['insurance','landscaping','snow','repairs','utilities','janitorial','security','management','other'];

// F-02 — lease exclusion prose resolved against CATEGORIES.
//
// `excluded_categories` is free text; CATEGORIES is a closed nine-value enum;
// the allocation filter compared them with exact equality, so 52 of 55 phrases
// extracted across Runs 1-3 were inert. A non-matching exclusion fails OPEN —
// the expense stays in the pool — so the tenant was billed for categories their
// lease excludes while the statement said otherwise.
//
// Every array builder below now emits APPLIED categories only, which is why the
// nine downstream `.includes(inv.category)` predicates did not have to change:
// they receive a list that is true rather than one that is aspirational.
//
// If the resolver module is missing this fails CLOSED — no categories applied
// and a synthetic unapplied entry, which blocks the tenant statement (see
// _exclusionBlockReason). Failing open here would silently over-bill.
function _exclusionState(rawExcluded) {
  const CX = (typeof window !== 'undefined' && window.CamExclusions) || null;
  if (!CX) {
    console.error('[CAM] cam-exclusions.js not loaded — exclusions cannot be resolved; statements will be blocked.');
    return {
      resolved: [], applied: [],
      notApplied: [{ raw: String(rawExcluded || ''), category: null, status: 'unmapped', candidates: [],
                     reason: 'Exclusion resolver unavailable — cannot verify which exclusions apply.' }],
      fingerprint: '', extracted: rawExcluded !== null && rawExcluded !== undefined, empty: rawExcluded === '',
    };
  }
  return CX.tenantExclusionState(rawExcluded);
}

// Applied-only category list for a tenant record (the shape stored in tenantData).
function _appliedExclusions(t) {
  return _exclusionState(t && t.excluded_categories).applied;
}

// ─── State ────────────────────────────────────────────────────────────────────
// tenantData[i] = null | { tenantName, leasedSqft, capPercentage, excludedCategories, baseYear }
const tenantData  = [null, null, null];
// invoiceData[i] = { vendorName, amount, category, invoiceDate, confidence, _error, fileUrl, fileName, fileType }
const invoiceData = [];
// glData[i] = { date, vendor, category, amount, confidence, _include }
let glData = [];

// ─── Data Model Classes ───────────────────────────────────────────────────────

class Property {
  constructor(name, totalSqFt) {
    this.name = name;
    this.totalSqFt = totalSqFt;
    this.leases = [];
    this.invoices = [];
    this.reconciliations = [];
  }
  addLeases(newLeases)  { this.leases   = this.leases.concat(newLeases);  }
  addInvoices(newInvs)  { this.invoices = this.invoices.concat(newInvs);  }
}

class Lease {
  constructor(tenantName, unitNumber, sqFt, startDate, endDate,
              excludedCategories = [], capPercentage = null, capBaseAmount = null,
              sqFtApproximate = false, baseYear = null, leaseType = null) {
    this.tenantName         = tenantName;
    this.unitNumber         = unitNumber || '';
    this.sqFt               = parseFloat(sqFt) || 0;
    this.startDate          = startDate  || '';
    this.endDate            = endDate    || '';
    this.excludedCategories = excludedCategories.map(c => c.toLowerCase());
    this.capPercentage      = capPercentage !== null ? parseFloat(capPercentage) : null;
    this.capBaseAmount      = capBaseAmount  !== null ? parseFloat(capBaseAmount)  : null;
    this.cap                = this.capPercentage; // direct alias — readable in reconciliation
    this.sqFtApproximate    = !!sqFtApproximate;
    this.baseYear           = baseYear ? parseInt(baseYear) : null;
    this.leaseType          = leaseType || null; // e.g. 'NNN', 'Gross', 'Modified Gross'
  }
}

/**
 * CAM-1 — ONE currency parser, for the engine and every surface that reports it.
 *
 * The engine used `parseFloat`, which stops at the first non-numeric character:
 *
 *   parseFloat("1,250.00")      = 1      -> an invoice worth $1
 *   parseFloat("$84,500")       = NaN    -> `|| 0` made it $0, silently dropped
 *   parseFloat("84,500.00 USD") = 84
 *
 * A dropped invoice does not fail loudly — it leaves the pool, every tenant is
 * under-billed, and the landlord absorbs it with nothing on screen to say so.
 * Extraction produces exactly these shapes.
 *
 * Returns null for anything it cannot parse, NEVER 0. Zero is a real amount and
 * must not be how the system says "I could not read this". Callers decide what
 * to do with null, and every caller in the money path must surface it.
 */
function parseMoney(v) {
  // DELEGATE, same reasoning as parseSqft. Contract unchanged: a number, or
  // null when the value could not be read. Never 0 for unreadable.
  return window.SourceValues.readMoney(v).value;
}
window.parseMoney = parseMoney;

// ── Invoice amounts, canonicalised once on the way in ───────────────────────
//
// 35 places read `inv.amount` with `parseFloat(inv.amount) || 0`. Every one of
// them is CORRECT for a number and wrong for "$1,250.00", which parseFloat reads
// as NaN -> 0. The engine meanwhile built its Invoice objects with parseMoney
// and allocated the full $1,250. So the pool the screen reported and the pool
// the engine distributed were different pools, and `Math.abs()` in the variance
// banner hid the sign of the gap.
//
// Rewriting 35 readers would be a wide change that leaves the same assumption
// unenforced for the 36th. Instead the assumption is made true: an amount that
// enters invoiceData is a Number, or '' when nothing readable was provided.
// Every existing reader then behaves, unchanged.
//
// UNREADABLE IS NOT ZERO. A value that cannot be read becomes '' rather than 0,
// which routes it into the "N invoices with no amount were excluded" banner that
// already exists — a warning, not a silent $0. The original text is kept on
// `amountUnparsed`, the same field name Invoice already uses for this, so the
// two layers describe the condition with one word.
function canonicaliseInvoiceAmount(inv) {
  if (!inv) return inv;
  const r = window.SourceValues.readMoney(inv.amount);
  if (r.status === 'unreadable') {
    if (inv.amountUnparsed == null) inv.amountUnparsed = String(inv.amount);
    inv.amount = '';
  } else if (r.value !== null) {
    inv.amount = r.value;
    if (inv.amountUnparsed != null) delete inv.amountUnparsed;
  }
  return inv;
}
function canonicaliseInvoiceAmounts(list) {
  if (Array.isArray(list)) list.forEach(canonicaliseInvoiceAmount);
  return list;
}
window.canonicaliseInvoiceAmount  = canonicaliseInvoiceAmount;
window.canonicaliseInvoiceAmounts = canonicaliseInvoiceAmounts;


class Invoice {
  // PW-3 — relations set in the invoice register (CAM eligible, space, building
  // system) used to be dropped at this boundary. The engine therefore could not
  // honour them however carefully the manager set them, and the "CAM eligible"
  // checkbox changed a display total and nothing else.
  constructor(id, date, amount, vendor, category, description = '', rel = {}) {
    this.id              = id || null;
    this.camEligible     = window.CamPool.isEligible(rel);   // absent → recoverable
    this.spaceId         = rel.spaceId || null;
    this.system          = rel.system  || null;
    this.date            = date     || '';
    // CAM-1 — null means "unreadable", which is not the same as zero. The
    // reconciliation refuses to allocate an unreadable invoice rather than
    // silently pricing it at nothing.
    var _parsed         = parseMoney(amount);
    this.amountUnparsed = _parsed === null ? String(amount == null ? '' : amount) : null;
    this.amount         = _parsed === null ? 0 : _parsed;
    this.vendorName      = vendor   || '';  // field matchInvoiceToTenant expects
    this.category        = category || 'other';
    this.invoiceDate     = date     || '';  // field matchInvoiceToTenant expects
    this.description     = description;
    this.matchedTenant   = null;
    this.matchedTenantId = null;
    this.matchConfidence = 0;
    this.matchReason     = '';
  }
}

class ReconciliationResult {
  constructor(tenantName, unitNumber, sqFt, totalAllocated, proRataPercent,
              includedInvoices, capApplied = false, capAdjustment = null,
              occupancy = null) {
    this.tenantName         = tenantName;
    this.unitNumber         = unitNumber || '';
    this.sqFt               = sqFt;
    this.totalAllocated     = totalAllocated;
    this.proRataPercent     = proRataPercent;
    this.includedInvoices   = includedInvoices || [];
    this.capApplied         = capApplied;
    this.capAdjustment      = capAdjustment;
    // T2 — HOW MUCH OF THE PERIOD, and everything needed to reproduce it without
    // recomputing: the rational (numerator/denominator), the days behind it, the
    // window, the case, and where the basis came from. NULL means this run
    // predates occupancy — it does NOT mean a factor of 1, and no reader may
    // treat it as one.
    this.occupancy          = occupancy || null;
    // The two shares, and their product, kept as three separate values. The
    // effective share is DERIVED for display and is never the stored pro-rata.
    this.effectiveSharePercent = (occupancy && occupancy.applied && occupancy.factor !== null)
      ? parseFloat((proRataPercent * occupancy.factor).toFixed(4))
      : proRataPercent;
    this.ambiguityFlags     = [];  // populated by runFullReconciliation after construction
    this.status             = totalAllocated > 0 ? 'calculated' : 'needs review';
    const total = this.includedInvoices.reduce((s, inv) => s + (inv.share || 0), 0);
    this.averageConfidence  = total > 0
      ? Math.round(this.includedInvoices.reduce((s, inv) => s + (inv.matchConfidence || 0) * (inv.share || 0), 0) / total)
      : 0;
    // Aliases for lastResults consumers (runCAMAllocation shape compatibility)
    this.name           = tenantName;
    this.allocatedAmount = totalAllocated;
    this.proRata        = proRataPercent / 100;
    this.eligibleCount  = (includedInvoices || []).length;
  }
}

// ─── Portfolio State ──────────────────────────────────────────────────────────
const portfolio = [];
let activePropId = null; // null = portfolio view
let _props = []; // canonical merged array from loadProperties()
// Has a properties load actually SUCCEEDED this session? Consulted by
// _acqOrphaned(): "this property is gone" is only sayable once we know what
// exists. An empty _props after a failed load must never be read as deletion.
let _propsLoadedOk = false;

// ─── Acquisition Review State ─────────────────────────────────────────────────
// Fully isolated — never touches _props, tenantData, invoiceData, or activePropId.
let _acqReviews    = [];
let _activeAcqId   = null;
let _acqTenants    = [];
let _acqInvoices   = [];
let _acqSqFt       = 0;
let _acqActiveTab  = 'risk';                          // 'risk' | 'rentroll'
let _acqRentRollSort = { col: 'tenant_name', dir: 'asc' };
let _leaseAlertsDismissed   = false;       // session-only; resets on reload
let _actionCenterDismissed = false;       // session-only; resets on reload

// Returns the currently selected property object, or null if none is active.
function currentProperty() {
  if (!activePropId) return null;
  return _props.find(p => p.id === activePropId) || null;
}

// ─── Supabase Storage: reading a stored document ──────────────────────────────

/**
 * SEC-1 — turn a stored document reference into a URL that may actually be read.
 *
 * The `leases` and `invoices` buckets were public, so `/object/public/...` URLs
 * worked for anyone who had one. Once those buckets are private, every stored
 * URL stops resolving — and every surface that renders a document
 * (Evidence Viewer, lease modal, Documents, Ask-the-Lease citations) goes
 * through here instead.
 *
 * The server re-derives the object path from whatever is passed and checks that
 * it belongs to the caller before signing, so nothing here needs to be trusted.
 * Signed URLs are short-lived, which is why they are fetched at view time rather
 * than stored: a URL kept in a row would be expired by the time anyone used it.
 *
 * Returns null rather than throwing — every caller has a real "can't show it"
 * path already, and a throw here would take out the surface around it.
 */
const _signedUrlCache = new Map();   // ref → { url, until }

async function resolveDocumentUrl(ref) {
  if (!ref) return null;
  // Anything not in our storage (a sample fixture, an external link) is
  // returned untouched — there is nothing for us to sign.
  if (!/\/storage\/v1\/object\//.test(String(ref)) && !/^(leases|invoices)\//.test(String(ref))) {
    return ref;
  }

  const hit = _signedUrlCache.get(ref);
  // 30s of headroom so a URL fetched now is not handed to pdf.js as it expires.
  if (hit && hit.until - 30000 > Date.now()) return hit.url;

  try {
    const resp = await _fetchWithTimeout('/api/document-url', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
      body: JSON.stringify({ ref }),
    }, 15000);
    if (!resp.ok) {
      let msg = `HTTP ${resp.status}`;
      try { msg = (await resp.json()).error || msg; } catch (_) {}
      console.warn('[document] could not authorise', ref, '—', msg);
      return null;
    }
    const body = await resp.json();
    if (!body || !body.url) return null;
    _signedUrlCache.set(ref, { url: body.url, until: Date.now() + (body.expiresIn || 300) * 1000 });
    return body.url;
  } catch (e) {
    console.warn('[document] authorisation request failed:', e && e.message);
    return null;
  }
}
window.resolveDocumentUrl = resolveDocumentUrl;

/**
 * SEC-1 — the ONE way a stored document reaches the browser.
 *
 * Every previous fix converted one call site at a time, and each pass missed
 * some: the invoice viewer, then the Space chips, then the AI evidence chips,
 * then Property Documents, then timeline attachments. A per-site fix is a fix
 * that has to be remembered, and this has now been forgotten four times.
 *
 * So the render sites stop deciding. They emit a marker; these three functions
 * and the observer below do the rest:
 *
 *   docLinkHtml()   a clickable document  → <button data-doc-url> or <a href>
 *   docImageHtml()  an inline thumbnail   → <img data-doc-src> (src filled later)
 *   the observer    fills every data-doc-src the moment it enters the DOM
 *
 * A caller that forgets to hydrate cannot exist, because nothing calls hydrate.
 */
// isStoredDocumentRef / docLinkHtml / docImageHtml live in document-links.js —
// a pure module both the browser and Node can load, so the rendering decision
// is exercised by tests directly rather than only through a browser. What stays
// here is what needs the DOM and the network.

/** Resolve, then open. The scheme is pinned: a stored ref must never navigate. */
async function openStoredDocument(ref) {
  const readable = await resolveDocumentUrl(ref);
  if (!readable) {
    showToast('⚠️ That document could not be opened — you may not have access to it, or it is no longer stored.',
      { color: '#92400e', textColor: '#fef3c7', duration: 8000 });
    return;
  }
  let u;
  try { u = new URL(readable, window.location.origin); } catch (_) { return; }
  if (u.protocol !== 'https:' && u.protocol !== 'http:' && u.protocol !== 'blob:') return;
  window.open(u.href, '_blank', 'noopener');
}
window.openStoredDocument = openStoredDocument;

// One delegated handler for every document button, anywhere in the app.
document.addEventListener('click', function (e) {
  const btn = e.target && e.target.closest && e.target.closest('[data-doc-url]');
  if (!btn) return;
  e.preventDefault();
  openStoredDocument(btn.getAttribute('data-doc-url'));
});

/**
 * Fill in every stored thumbnail as it enters the DOM.
 *
 * An observer rather than a hydrate() call at each render site, because "call
 * hydrate after you render" is exactly the instruction that gets forgotten —
 * this whole exercise is the evidence.
 */
async function _hydrateDocImages(root) {
  const imgs = [];
  if (root.nodeType === 1) {
    if (root.matches && root.matches('img[data-doc-src]')) imgs.push(root);
    if (root.querySelectorAll) imgs.push(...root.querySelectorAll('img[data-doc-src]'));
  }
  for (const img of imgs) {
    const ref = img.getAttribute('data-doc-src');
    img.removeAttribute('data-doc-src');   // claim it before awaiting — no double work
    const readable = await resolveDocumentUrl(ref);
    if (readable) img.src = readable;
    else img.alt = (img.alt || 'Image') + ' — not available';
  }
}
if (typeof MutationObserver === 'function') {
  new MutationObserver(function (records) {
    for (const r of records) for (const n of r.addedNodes) _hydrateDocImages(n);
  }).observe(document.documentElement, { childList: true, subtree: true });
}

// ─── Supabase Storage upload ──────────────────────────────────────────────────

/**
 * The one client-side size gate, checked BEFORE the file is read or encoded.
 *
 * Two guards used to sit in this file at 60 MB — eighteen times what the
 * platform accepts. Everything between ~3.3 MB and 60 MB passed, was read into
 * memory, base64-encoded (seconds of main-thread work and ~1.33× the
 * allocation), sent, and came back as a bare HTTP 413 that no code path
 * explained. Failing here costs nothing and says why.
 *
 * The limit itself lives in request-limits.js, which the serverless handlers
 * require() — so the two sides cannot drift apart.
 *
 * Returns true when the file may be sent. On refusal it has already told the
 * user, in one sentence naming the size, the ceiling, and what to do.
 */
function _guardUploadSize(file, what) {
  const L = window.MSRequestLimits;
  if (!L) {
    // The gate is not optional. Without it this function would return true and
    // silently restore the behaviour it exists to prevent.
    console.error('[upload] request-limits.js did not load — refusing rather than guessing');
    showToast('⚠️ Upload is unavailable — the page did not load completely. Refresh and try again.',
      { color: '#92400e', textColor: '#fef3c7', duration: 8000 });
    return false;
  }
  const verdict = L.checkUploadSize(file && file.size, what);
  if (verdict.ok) return true;
  console.warn('[upload] refused before encoding:', file && file.name, verdict.error);
  showToast('⚠️ ' + verdict.error, { color: '#92400e', textColor: '#fef3c7', duration: 14000 });
  return false;
}
window._guardUploadSize = _guardUploadSize;

async function uploadInvoiceFile(file) {
  // Fail before toBase64, not after the round trip.
  if (!_guardUploadSize(file, 'invoice')) {
    throw new Error(window.MSRequestLimits
      ? window.MSRequestLimits.checkUploadSize(file && file.size, 'invoice').error
      : 'Upload is unavailable — the page did not load completely.');
  }
  const attempt = async () => {
    const fileBase64 = await toBase64(file);
    const resp = await fetch('/api/upload', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
      body: JSON.stringify({ fileName: file.name, fileType: file.type, fileBase64 }),
    });
    const result = await resp.json();
    if (resp.status === 429) {
      const err = new Error('Upload rate limit reached — wait a moment and try again');
      err.isRateLimit = true;
      throw err;
    }
    if (!resp.ok || result.error) throw new Error(result.error || `HTTP ${resp.status}`);
    return result.url;
  };

  for (let i = 0; i < 3; i++) {
    try {
      const url = await attempt();
      return { url, error: null };
    } catch (e) {
      if (e.isRateLimit) {
        // Rate-limit window is 60s — short retries won't recover; surface immediately
        console.warn('[uploadInvoiceFile] rate limited:', e.message);
        return { url: null, error: 'rate-limited' };
      }
      if (i < 2) {
        await new Promise(r => setTimeout(r, (i + 1) * 1200));
        continue;
      }
      console.error('[uploadInvoiceFile] failed after 3 attempts:', e.message);
      return { url: null, error: 'cloud-backup-failed' };
    }
  }
}

// ─── Claude API helpers ───────────────────────────────────────────────────────

async function toBase64(file) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload  = () => res(r.result.split(',')[1]);
    r.onerror = () => rej(new Error('Could not read file — try a different file'));
    r.readAsDataURL(file);
  });
}

function parseJSON(text) {
  if (typeof text !== 'string' || !text.trim()) {
    throw new Error('Empty response from API');
  }
  // Strip markdown code fences Claude sometimes wraps around JSON
  const cleaned = text.replace(/^```(?:json)?\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    throw new Error('Could not parse API response as JSON');
  }
}

// SEC-2 — takes a TASK NAME, not a prompt. The instructions live in
// api/_claude-tasks.js; this sends only the document.
async function callClaude(file, task) {
  let base64;
  try {
    base64 = await toBase64(file);
  } catch (e) {
    console.error('[Mainstreet] File read error:', e);
    throw new Error('Could not read file — try a different file');
  }

  // Determine media type — force PDF for non-image files
  const isImage   = file.type.startsWith('image/');
  const mediaType = isImage ? (file.type || 'image/jpeg') : 'application/pdf';

  const contentBlock = isImage
    ? { type: 'image',    source: { type: 'base64', media_type: mediaType, data: base64 } }
    : { type: 'document', source: { type: 'base64', media_type: mediaType, data: base64 } };

  let data;
  try {
    data = await claudeFetch({
      task,
      max_tokens: 1024,
      messages: [{ role: 'user', content: [contentBlock] }],
    });
  } catch (e) {
    console.error('[Mainstreet] fetch error:', e);
    throw new Error('Could not reach the server — check your connection');
  }

  if (!data || typeof data !== 'object') {
    throw new Error('Extraction failed — try a different file or contact support');
  }

  return data;
}

function applyRawTextFallback(tenants) {
  const MONTHS = /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s+\d{4}\b/i;
  tenants.forEach(t => {
    if (!t || !t._rawText) return;
    if (!t.startDate) {
      const match = t._rawText.match(MONTHS);
      if (match) {
        const d = new Date(match[0]);
        if (!isNaN(d)) t.startDate = d.toISOString().split('T')[0];
      }
    }
  });
}

function splitTextByTenant(extractedText, tenants) {
  if (!extractedText || !tenants?.length) return tenants;

  const text = extractedText.replace(/\s+/g, ' ');

  const positions = tenants.map(t => {
    if (!t.tenantName) return null;

    const name = t.tenantName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(name, 'i');
    const match = text.match(regex);

    if (!match) return null;

    return { tenant: t, index: match.index };
  }).filter(Boolean);

  positions.sort((a, b) => a.index - b.index);

  for (let i = 0; i < positions.length; i++) {
    const start = positions[i].index;
    const nextIndex = positions[i + 1]?.index || text.length;
    const extendedEnd = Math.min(nextIndex + 1500, text.length);
    positions[i].tenant._rawText = text.slice(start, extendedEnd);
  }

  return tenants;
}

function enrichLeaseData(data, extractedText) {
  if (!extractedText) return data;
  // Handle array response (new prompt returns [...])
  if (Array.isArray(data)) {
    data.forEach(item => enrichLeaseData(item, extractedText));
    return data;
  }

  const text = extractedText.toLowerCase();

  // --- SQFT (fallback)
  if (!data.leasedSqft) {
    const sqftMatch = extractedText.match(/([\d,]{2,6})\s*(sq\s*ft|square feet)/i);
    if (sqftMatch) {
      data.leasedSqft = parseInt(sqftMatch[1].replace(/,/g, ''));
    }
  }

  // --- START DATE
  if (!data.startDate) {
    const startMatch = extractedText.match(
      /(commence|commencement|start)[^\n]*?(\b\w+ \d{1,2}, \d{4}\b)/i
    );
    if (startMatch) {
      data.startDate = startMatch[2];
    }
  }

  // --- END DATE
  if (!data.endDate) {
    const endMatch = extractedText.match(
      /(expire|expiration|end(?:\s+date)?|terminate)[^\n]*?(\b\w+ \d{1,2}, \d{4}\b)/i
    );
    if (endMatch) {
      data.endDate = endMatch[2];
    }
  }

  // --- TERM FALLBACK
  if (!data.endDate && data.startDate) {
    const termMatch = extractedText.match(/(\d+)\s*\(?\d*\)?\s*year/i);
    if (termMatch) {
      const years = parseInt(termMatch[1]);
      const start = new Date(data.startDate);
      if (!isNaN(start)) {
        start.setFullYear(start.getFullYear() + years);
        data.endDate = start.toLocaleDateString('en-US', {
          month: 'short',
          day: 'numeric',
          year: 'numeric'
        });
      }
    }
  }

  // --- START DATE ("on or about" fallback)
  if (!data.startDate) {
    const match = extractedText.match(/on or about ([A-Z][a-z]+ \d{1,2}, \d{4})/i);
    if (match) data.startDate = match[1];
  }

  // FINAL fallback — always extract first real date if still missing
  if (!data.startDate && extractedText) {
    const dateMatch = extractedText.match(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s+\d{4}\b/i);
    if (dateMatch) {
      data.startDate = dateMatch[0];
    }
  }


  // --- LEASE TYPE
  if (!data.leaseType) {
    if (/cam|common area maintenance|taxes|insurance/i.test(text)) {
      data.leaseType = "NNN";
    } else if (/gross/i.test(text)) {
      data.leaseType = "Gross";
    }
  }

  // --- CAP %
  if (!data.capPercentage) {
    const capMatch = extractedText.match(/(\d+(\.\d+)?)\s*%.*cap/i);
    if (capMatch) {
      data.capPercentage = parseFloat(capMatch[1]);
    }
  }

  // --- EXCLUSIONS
  if (!data.excludedCategories) {
    const exclMatch = extractedText.match(/exclusions?\s*[:\-]?\s*(.*)/i);
    if (exclMatch) {
      data.excludedCategories = exclMatch[1].trim();
    }
  }

  return data;
}


// Remove stray single-letter initials (e.g. "P." or "M.") that AI sometimes
// prepends/appends to extracted names, then collapse extra whitespace.
function cleanTenantName(raw) {
  if (!raw) return '';
  return raw
    .replace(/\b[A-Z]\.\s*/g, '')   // drop "P. ", "M. " etc.
    .replace(/\s+/g, ' ')
    .replace(/^[\s,;.]+|[\s,;.]+$/g, '')
    .trim();
}

// Returns true when a name is a real business/person name rather than a
// document-level phrase that the AI mistakenly returned as the tenant name.
function isStrongName(name) {
  if (!name || name.length <= 3) return false;
  if (/^(unknown\s*tenant|n\/a|none|null)$/i.test(name.trim())) return false;
  if (/\b(lease|agreement|contract|addendum|exhibit|amendment|schedule|document)\b/i.test(name)) return false;
  if (name.toLowerCase().includes('.pdf')) return false;
  // snake_case / kebab-case with no spaces → system-generated filename fragment
  if (/[_\-]/.test(name) && !/\s/.test(name)) return false;
  return true;
}

// Normalizes any date string/value to YYYY-MM-DD; returns '' if absent or unparseable.
function toISODate(val) {
  if (!val) return '';
  const s = String(val).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = new Date(s);
  return isNaN(d) ? '' : d.toISOString().split('T')[0];
}

// Deterministic tenant name extractor — runs before and after Claude as a hard fallback.
function extractTenantFromText(text) {
  if (!text) return null;

  const landlordWords = /properties|realty|real estate|holdings|capital|management|investments|partners|trust|fund|group llc|llp/i;

  // 1. Explicit label with entity suffix — highest confidence
  const labelMatch = text.match(
    /(?:tenant|lessee|occupant)\s*[:\-]?\s*([A-Z][A-Za-z0-9,&.\s]{2,60}?(?:LLC|L\.L\.C\.|INC\.?|CORP\.?|LTD\.?|L\.P\.|CO\.))/i
  );
  if (labelMatch) {
    const name = labelMatch[1].trim().replace(/\s+/g, ' ');
    if (isStrongName(name)) return name;
  }

  // 2. Explicit label without entity suffix — still reliable
  const labelOnly = text.match(/(?:tenant|lessee|occupant)\s*[:\-]\s*([A-Z][A-Za-z0-9,&.\s]{3,50})/i);
  if (labelOnly) {
    const name = labelOnly[1].split('\n')[0].trim().replace(/\s+/g, ' ');
    if (isStrongName(name) && !landlordWords.test(name)) return name;
  }

  // 3. Collect ALL entity names, filter landlord words, return first survivor
  const allEntities = text.match(
    /[A-Z][A-Za-z0-9,&.\s]{2,60}?(?:LLC|L\.L\.C\.|INC\.?|CORP\.?|LTD\.?|L\.P\.|CO\.)/g
  ) || [];
  const filtered = allEntities
    .map(n => n.trim().replace(/\s+/g, ' '))
    .filter(n => isStrongName(n) && !landlordWords.test(n));
  if (filtered.length > 0) return filtered[0];

  // 4. Any entity name at all (last resort before filename)
  if (allEntities.length > 0) return allEntities[0].trim().replace(/\s+/g, ' ');

  return null;
}

// Regex-based fallback: scans raw lease text for date strings.
function extractDatesFromText(text) {
  if (!text) return {};
  const re = /\b(\d{1,2}\/\d{1,2}\/\d{2,4}|\w+\s\d{1,2},\s\d{4})\b/g;
  const matches = text.match(re) || [];
  if (matches.length < 2) return {};
  return {
    startDate:     matches[0],
    endDate:       matches[1],
    _usedFallback: true,
  };
}

// A DATE THE LEASE HAS AND WE CANNOT READ IS NOT A DATE THE LEASE LACKS.
//
// toISODate answers '' for both, and normalizeTenant stored that '' — so
// "Commencement: upon substantial completion", "TBD", and a European
// "31/08/2026" all arrived downstream indistinguishable from a lease with no
// date at all. Two different conversations with the tenant: one is "send us
// your dates", the other is "your lease says the term starts on an event that
// has to be dated before we can bill it". lease-period.js has had an
// `unreadable` status the whole time and nothing in storage could ever produce
// it.
//
// So the ISO field keeps its exact contract — ISO or empty, and every existing
// consumer is untouched — and what could not be read is kept beside it, under
// the field it belongs to. obligationTerm() pairs them back up; it remains the
// only reader of either.
function _dateWithRaw(input) {
  const raw = input == null ? '' : String(input).trim();
  const iso = toISODate(raw);
  return { iso, unreadable: (raw !== '' && iso === '') ? raw : null };
}

function normalizeTenant(d) {
  if (!d) return d;
  const fallback = extractDatesFromText(d.rawText || '');
  const _start = _dateWithRaw(d.start_date ?? d.startDate ?? d.lease_start_date ?? fallback.startDate ?? '');
  const _end   = _dateWithRaw(d.end_date   ?? d.endDate   ?? d.lease_end_date  ?? fallback.endDate   ?? '');
  const _cam   = _dateWithRaw(d.cam_commencement_date ?? d.camCommencementDate ?? '');
  // Carried forward when normalizeTenant runs over an already-normalized record,
  // which it does on every load — otherwise the second pass, seeing an empty ISO
  // field and no raw input, would erase the distinction it exists to keep.
  const _prior = (d.unreadableDates && typeof d.unreadableDates === 'object') ? d.unreadableDates : {};
  const _unreadable = {};
  for (const [k, r] of [['start_date', _start], ['end_date', _end], ['cam_commencement_date', _cam]]) {
    // A readable date clears the record of the unreadable one: once the manager
    // corrects "TBD" to a real date there is nothing left that could not be read.
    if (r.iso) continue;
    const keep = r.unreadable ?? (_prior[k] ?? null);
    if (keep) _unreadable[k] = String(keep);
  }
  return {
    tenant_name:         cleanTenantName(d.tenant_name ?? d.tenantName ?? d.name ?? ''),
    suite:               d.suite ?? d.unit ?? d.unitNumber ?? '',
    leased_sqft:         d.leased_sqft         ?? d.leasedSqft ?? d.sqft  ?? '',
    start_date:          _start.iso,
    end_date:            _end.iso,
    lease_type:          d.lease_type          ?? d.leaseType                     ?? '',
    excluded_categories: d.excluded_categories ?? d.excludedCategories            ?? null,  // F-02: null = never extracted, '' = none found
    cap:                 d.cap                 ?? d.cam_cap ?? d.capPercentage    ?? null,
    flags:               d.flags               ?? [],
    confidence:          d.confidence          ?? {},
    baseYear:            d.baseYear            ?? null,
    unitNumber:          d.unitNumber          ?? '',
    doc_has_dates:       d.doc_has_dates       ?? true,
    doc_has_lease_type:  d.doc_has_lease_type  ?? true,
    leaseUrl:            d.leaseUrl ?? d.lease_url ?? d.file_url ?? null,
    leaseExpected:       d.leaseExpected ?? !!(d.leaseUrl ?? d.lease_url ?? d.file_url),
    extractionFailed:    d.extractionFailed    ?? false,
    _needsReview:        d._needsReview        ?? false,
    _pendingJobReview:   d._pendingJobReview   ?? false,
    _userConfirmed:      d._userConfirmed      ?? false,
    _jobId:              d._jobId              ?? null,
    _usedFallback:       d._usedFallback       ?? fallback._usedFallback ?? false,
    id:                  d.id                  ?? crypto.randomUUID(),
    fileName:            d.fileName            ?? '',
    _error:              d._error              ?? null,
    reviewOverrides:     d.reviewOverrides     ?? {},
    review:              d.review              ?? {},
    // ── State a CAM blocker depends on ─────────────────────────────────────
    //
    // This function is an allow-list, and the property blob is re-read through
    // it on every property load. These three were written to storage and then
    // silently dropped on the way back in, which is worse than never saving
    // them: the record looked complete and the behaviour was not.
    //
    // _edgeCases is computed ONCE, at extraction, and never recomputed. Losing
    // it on load meant _hasPropertyMismatch() went false, _propertyMismatchBlockReason()
    // returned null, and a lease whose document names a different property
    // silently became CAM-eligible again on the next page load — the blocker
    // evaporating in the permissive direction, with the warning gone from the
    // card too. That is the one direction a safety gate must never fail in.
    //
    // _propertyConfirm is the landlord's explicit verification. Dropping it
    // discarded a recorded human decision — who, when, against which document —
    // so the audit trail on the record disappeared even though the activity log
    // entry survived.
    //
    // _exclusionAck is the same shape for the exclusion gate. It failed the
    // safe way (the landlord was asked again) but was lost for the same reason,
    // and is restored here rather than left as a known-broken sibling.
    _edgeCases:          d._edgeCases          ?? null,
    _propertyConfirm:    d._propertyConfirm    ?? null,
    _exclusionAck:       d._exclusionAck       ?? null,
    capBaseAmount:       d.capBaseAmount       ?? null,
    fieldEvidence:       d.fieldEvidence       ?? {},
    admin_fee_pct:       d.admin_fee_pct       ?? null,
    gross_up_pct:        d.gross_up_pct        ?? null,
    expense_stop:        d.expense_stop        ?? null,
    audit_rights:        d.audit_rights        ?? null,
    pro_rata_method:     d.pro_rata_method     ?? null,
    renewal_options:     d.renewal_options     ?? null,
    // ALLOW-LIST. Omitting either of these would write them to storage and drop
    // them on the next property load — the failure this list already carries a
    // warning about, and the one that would make a lease's own partial-period
    // clause evaporate between sessions.
    cam_commencement_date: _cam.iso || null,
    // ALLOW-LIST, and the reason this one is here: without it the record of what
    // could not be read is written to storage and dropped on the next load, and
    // the field goes back to reading as simply absent.
    unreadableDates:       Object.keys(_unreadable).length ? _unreadable : null,
    partial_period_basis:  (() => {
      const v = d.partial_period_basis ?? d.partialPeriodBasis ?? null;
      const k = v == null ? '' : String(v).trim().toLowerCase();
      return k === '' ? null : k;
    })(),
    base_rent:           d.base_rent           ?? null,
    security_deposit:    d.security_deposit    ?? null,
    amendments:          Array.isArray(d.amendments) ? d.amendments : [],
    property_name:       (() => {
      const v = d.property_name ?? d.propertyName ?? null;
      return (typeof v === 'string' && v.trim()) ? v.trim() : null;
    })(),
  };
}

function isValidTenant(d) {
  if (!d) return false;
  return (
    d.tenant_name && d.tenant_name.trim().length > 0 &&
    d.leased_sqft != null && String(d.leased_sqft).trim().length > 0
  );
}


// Scores extraction quality from 0–100 and maps to high/medium/low/failed.
// Called in processFile after normalizeTenant; the result is stored on the tenant
// entry and drives badge colour, auto-expand, and manual-confirm requirements.
// meta: { usedPdfDirect, ocrChars, fileSizeBytes, processingMs, extractionFailed }
function computeExtractionConfidence(norm, meta) {
  if (!norm || meta?.extractionFailed) {
    return { level: 'failed', score: 0, reasons: ['Extraction returned no data'], failedFields: ['all'] };
  }

  let score = 100;
  const reasons = [];
  const failedFields = [];

  if (!norm.tenant_name || !norm.tenant_name.trim()) {
    score -= 40; reasons.push('No tenant name extracted'); failedFields.push('tenant_name');
  } else if (!isStrongName(norm.tenant_name)) {
    score -= 10; reasons.push('Tenant name looks weak (possible OCR noise)');
  }
  if (!norm.start_date)  { score -= 15; reasons.push('Missing lease start date'); failedFields.push('start_date'); }
  if (!norm.end_date)    { score -= 15; reasons.push('Missing lease end date');   failedFields.push('end_date'); }
  if (!norm.lease_type)  { score -= 10; reasons.push('Lease type not identified'); failedFields.push('lease_type'); }
  if (!norm.leased_sqft) { score -= 10; reasons.push('Square footage not found'); failedFields.push('leased_sqft'); }
  if (norm._usedFallback) { score -= 8; reasons.push('Dates came from regex fallback, not AI'); }
  // Very short text layer suggests poor OCR quality on the text path
  if (!meta?.usedPdfDirect && meta?.ocrChars != null && meta.ocrChars < 500) {
    score -= 10; reasons.push('Very short text layer — possible OCR degradation');
  }

  score = Math.max(0, score);
  const level = score >= 80 ? 'high' : score >= 55 ? 'medium' : score > 0 ? 'low' : 'failed';
  return { level, score, reasons, failedFields };
}

async function extractPdfText(file) {
  // For non-PDF files (txt, etc.) fall back to plain text read
  if (!file.name.toLowerCase().endsWith('.pdf') && file.type !== 'application/pdf') {
    return file.text();
  }

  const pdfjs = window['pdfjsLib'];
  if (!pdfjs) {
    console.error('PDF.js not ready');
    throw new Error('PDF.js failed to load');
  }
  const lib = pdfjs;

  const arrayBuffer = await file.arrayBuffer();
  const pdf = await lib.getDocument({ data: arrayBuffer }).promise;

  // WHY 50: Ask-the-Lease needs full lease text for QA. Substantive clauses (CAM,
  // exclusions, renewals) typically appear on pages 10–40. 5 pages only covered
  // the cover sheet and recitals, making QA useless for standard commercial leases.
  // Field extraction (callClaudeForLease) uses prepareLeaseTextForClaude which
  // caps its own input window — extra stored pages don't affect extraction cost.
  const MAX_PAGES = 50;
  if (pdf.numPages > MAX_PAGES) {
    console.warn(`[extractPdfText] PDF has ${pdf.numPages} pages — reading only first ${MAX_PAGES}. Exhibits beyond page 50 will not be stored.`);
  }

  const pages = [];
  for (let p = 1; p <= Math.min(pdf.numPages, MAX_PAGES); p++) {
    // Real-document robustness (Phase 27): one corrupt/unreadable page must not
    // abort the whole document — mark it and keep going, so downstream extraction
    // sees an explicit gap instead of silently losing everything after it.
    try {
      const page = await pdf.getPage(p);
      const content = await page.getTextContent();
      const pageText = content.items.map(item => item.str).join(' ');
      // WHY marker: ask-lease citations need page numbers. Claude reads these markers
      // and reports them as citation.page. Format must match the system prompt in ask-lease.js.
      pages.push(`--- Page ${p} ---\n${pageText}`);
    } catch (pageErr) {
      console.warn(`[extractPdfText] page ${p} unreadable — continuing:`, pageErr?.message);
      pages.push(`--- Page ${p} ---\n[This page could not be read — it may be corrupted or image-only.]`);
    }
  }

  // Truncation must be visible IN the text, not just the console — otherwise
  // extraction silently misses exhibits/amendments past the cap and nobody knows.
  if (pdf.numPages > MAX_PAGES) {
    pages.push(`--- Document truncated ---\n[Pages ${MAX_PAGES + 1}–${pdf.numPages} were not read. Exhibits or amendments beyond page ${MAX_PAGES} are not reflected in extracted terms.]`);
  }

  return pages.join('\n\n');
}

// Converts a File/Blob to a base64 string without stack-overflowing on large files.
async function fileToBase64(file) {
  const arrayBuffer = await file.arrayBuffer();
  const bytes = new Uint8Array(arrayBuffer);
  let binary = '';
  const CHUNK = 8192;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

// Sends the PDF directly to Claude as a base64 document block.
// Claude uses vision to read scanned PDFs — no OCR middleware needed.
async function callClaudeWithPdfDirect(file) {
  const base64 = await fileToBase64(file);

  const extractionPrompt = `Extract the following fields from this commercial lease document.
Return ONLY valid JSON. No explanation. No markdown.

{
  "tenant_name": string or null,
  "lease_start_date": "YYYY-MM-DD" or null,
  "lease_end_date": "YYYY-MM-DD" or null,
  "cam_commencement_date": "YYYY-MM-DD" or null,
  "partial_period_basis": "per_diem" | "monthly" | "full_period" | null,
  "lease_type": "NNN" | "Gross" | "Modified Gross" | null,
  "sqft": number or null,
  "cam_cap": number or null,
  "property_name": string or null
}

PROPERTY NAME: The name or address of the building/property covered by this lease, as stated in the premises description or recitals (e.g. "Lakeview Plaza", "123 Main Street"). Null if not stated.

TENANT NAME:
- Look for labels: "Tenant:", "Lessee:", "Occupant:"
- If no label: first business entity (LLC, Inc, Corp) that is NOT the landlord
- Exclude names containing: Properties, Realty, Holdings, Capital, Investments, Management
- NEVER return null if any company name exists

DATES:
- Start: Commencement Date → Lease Start Date → Effective Date → Execution Date
- End: Expiration Date → Lease End Date → calculate from start date + term length

CAM COMMENCEMENT DATE: Only when the CAM/operating-expense obligation begins on a DIFFERENT date from the lease start — e.g. "Tenant shall commence payment of Operating Expenses upon the Rent Commencement Date", "upon opening for business", or after a stated free-rent or abatement period. Return null when CAM begins with the lease term. Do NOT copy the lease start date into this field.

PARTIAL PERIOD BASIS: How the lease says CAM is apportioned when the term covers only PART of an expense year. Look for: "prorated on a per diem basis", "prorated based on the number of days", "a fraction, the numerator of which is the number of days", "prorated monthly", "based on the number of full calendar months", or language requiring the full annual amount regardless of a partial year.
  per diem / number of days   → "per_diem"
  monthly / calendar months   → "monthly"
  full amount regardless      → "full_period"
Return null if the lease says nothing about partial years. Null is a real answer here — do NOT guess.

LEASE TYPE: Triple Net / NNN → "NNN" | Modified Gross | Gross

CAM CAP (CRITICAL): Search the ENTIRE document for any language limiting CAM or operating expense increases.
Look for: "CAM cap", "expense cap", "expense stop", "base year stop", "not to exceed", "shall not pay more than", "increases limited to", "capped at", "no more than X%", "controllable expense cap".
If a percentage (e.g. 5%) → return 5. If a dollar amount → return that number.
Only return null if NO cap language exists anywhere in the document.

Return best guess — do not leave fields null unless truly impossible.`;

  // ── Lease Ingestion Hardening ───────────────────────────────────────────
  // Vercel's Node runtime rejects request bodies over ~4.5 MB BEFORE the
  // handler runs, and base64 adds ~33%. Sending a copier scan whole used to
  // fail with HTTP 413. If the encoded payload won't fit, downscale the pages
  // and send them in batches instead of failing.
  const LI = window.LeaseIngest;
  if (LI && !LI.fitsInOneRequest(file.size)) {
    return await _visionExtractCompressed(file, extractionPrompt, LI);
  }
  // Telemetry: vision-direct run (scanned PDF small enough to send whole).
  const _tel = LI ? LI.begin(file.size) : null;
  if (_tel) LI.mark(_tel, { path: LI.PATHS.VISION_DIRECT, payloadBytes: LI.estimateEncodedBytes(file.size) });

  const messages = [{
    role: 'user',
    content: [
      {
        type: 'document',
        source: { type: 'base64', media_type: 'application/pdf', data: base64 },
      },
      { type: 'text', text: extractionPrompt },
    ],
  }];

  const res = await _fetchWithTimeout('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: JSON.stringify({ messages, max_tokens: 1500, task: 'lease_extraction' }),
  });

  if (!res.ok) {
    // A 413 here means the pre-flight budget was wrong — fall back to the
    // compressed path rather than surfacing a raw HTTP code to the user.
    if (res.status === 413 && LI) {
      console.warn('[EXTRACTION] 413 on direct vision — retrying compressed');
      if (_tel) LI.end(_tel, 'failure', 'http-413-retried-compressed');
      return await _visionExtractCompressed(file, extractionPrompt, LI);
    }
    if (_tel) LI.end(_tel, 'failure', 'http-' + res.status);
    throw new Error(`Claude PDF direct failed: HTTP ${res.status}`);
  }
  const data = await res.json();
  // Mark telemetry: PDF direct path uses Claude's native document understanding
  if (window.ms_extractionDebug) window.ms_extractionDebug.OCRUsed = true;
  if (_tel) { LI.end(_tel, 'success'); _recordIngestTelemetry(LI.summary(_tel)); }
  console.log('[EXTRACTION] PDF direct (vision) path used');
  return data;
}

// Last ingestion run, attached to the lease job's debug_summary so path mix can
// be aggregated in SQL. Operational metrics only — no document content.
let _lastIngestTelemetry = null;
function _recordIngestTelemetry(s) {
  try {
    _lastIngestTelemetry = s || null;
    if (window.ms_extractionDebug) window.ms_extractionDebug.ingest = s || null;
    // Proof of life: a batch finished. Resets the watchdog so a slow but
    // healthy extraction is never mistaken for a stalled one.
    if (typeof _touchJobWatchdog === 'function') _touchJobWatchdog();
  } catch (_) {}
}

// Downscale a large scanned lease and extract fields in page batches, merging
// the results. Partial success beats total failure: one failed batch never
// discards the others, so a 40-page scan with one bad page still extracts.
async function _visionExtractCompressed(file, extractionPrompt, LI) {
  const t0 = Date.now();
  const tel = LI.begin(file.size);
  let pages;
  try {
    pages = await LI.rasterize(file, { dpi: LI.DEFAULT_DPI });
  } catch (e) {
    LI.end(tel, 'failure', 'rasterize-failed');
    _recordIngestTelemetry(LI.summary(tel));
    throw e;
  }
  if (!pages.length) {
    LI.end(tel, 'failure', 'no-readable-pages');
    _recordIngestTelemetry(LI.summary(tel));
    throw new Error('Could not read any pages from this PDF');
  }

  const batches = LI.planBatches(pages.map(p => p.bytes));
  // A single batch is "compressed"; more than one is "chunked" — the distinction
  // tells us whether copier scans are merely downscaled or genuinely split.
  LI.mark(tel, {
    path: batches.length > 1 ? LI.PATHS.VISION_CHUNKED : LI.PATHS.VISION_COMPRESSED,
    pages: pages.length,
    batches: batches.length,
    payloadBytes: pages.reduce((s, p) => s + (p.bytes || 0), 0),
  });
  console.log(`[EXTRACTION] compressed vision — ${pages.length} pages → ${batches.length} batch(es)`,
    `| ${(file.size / 1048576).toFixed(1)}MB source`);

  const parts = [];
  let failures = 0;
  for (let b = 0; b < batches.length; b++) {
    const group = batches[b].map(i => pages[i]).filter(Boolean);
    if (!group.length) continue;
    const isFirst = b === 0;
    const scope = `This is part ${b + 1} of ${batches.length} of one lease (pages ` +
      `${group[0].page}–${group[group.length - 1].page}). Extract every field you can see in these pages. ` +
      `Return null for anything not visible here — do not guess; other parts cover the rest.`;
    const messages = [{
      role: 'user',
      content: [
        ...LI.buildImageBlocks(group),
        { type: 'text', text: (isFirst ? extractionPrompt : extractionPrompt + '\n\n' + scope) },
      ],
    }];
    try {
      const res = await _fetchWithTimeout('/api/claude', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
        body: JSON.stringify({ messages, max_tokens: 1500, task: 'lease_extraction' }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      parts.push(await res.json());
    } catch (e) {
      failures++;
      console.warn(`[EXTRACTION] batch ${b + 1}/${batches.length} failed:`, e?.message);
    }
  }

  LI.mark(tel, { batchFailures: failures });
  if (!parts.length) {
    LI.end(tel, 'failure', 'all-batches-failed');
    _recordIngestTelemetry(LI.summary(tel));
    throw new Error('Could not read this scanned lease — every page batch failed');
  }
  LI.end(tel, 'success', failures ? failures + '-of-' + batches.length + '-batches-failed' : null);
  _recordIngestTelemetry(LI.summary(tel));
  const merged = LI.mergeExtractions(parts);
  if (window.ms_extractionDebug) {
    window.ms_extractionDebug.OCRUsed = true;
    window.ms_extractionDebug.compressedBatches = batches.length;
    window.ms_extractionDebug.batchFailures = failures;
  }
  console.log(`[EXTRACTION] compressed vision done in ${Date.now() - t0}ms`,
    `| ${parts.length}/${batches.length} batches ok`);
  return merged;
}

// Extracts substantive lease text from a scanned PDF so Ask-the-Lease works
// on vision-path documents. Runs concurrently with callClaudeWithPdfDirect but
// uses a different prompt (text transcription, not structured JSON). The result
// is stored in extracted_text of the lease_documents row.
//
// Uses /api/explain (not /api/claude) because explain returns raw content[0].text
// — no JSON extraction step that would mangle plain-text lease content.
// Timeout is 85s to accommodate max_tokens=8096 output (~25-30s generation time).
async function extractTextFromPdfDirect(file) {
  // This path sends the WHOLE PDF as one base64 body. lease-ingest.js batches
  // and downscales for /api/claude; nothing did so here, so a scanned lease
  // over ~3.3 MB spent up to 85 seconds on a request the platform had already
  // rejected, and surfaced as "PDF text extraction failed: HTTP 413" with no
  // explanation. Refuse up front, in words, before encoding.
  const _L = window.MSRequestLimits;
  if (!_L) throw new Error('Upload is unavailable — the page did not load completely. Refresh and try again.');
  const _verdict = _L.checkUploadSize(file && file.size, 'lease');
  if (!_verdict.ok) throw new Error(_verdict.error);

  const base64 = await fileToBase64(file);

  // AI-2 — the transcription RULES moved to the server
  // (api/_explain-tasks.js, lease_text_extraction). What stays here is the
  // request: which provisions this product needs out of the document. Rules are
  // instructions; a list of wanted sections is a query.
  const prompt = `Return the substantive text from this commercial lease document.

Include the complete text of all provisions relating to:
- Parties (tenant name, landlord name, guarantors)
- Premises (address, suite, square footage)
- Lease term (commencement, expiration, any options)
- Rent schedule (base rent, percentage rent, escalations)
- CAM charges, operating expenses, and maintenance obligations
- Expense exclusions and limitations (caps, expense stops, base years)
- Administrative fees and gross-up provisions
- Audit rights
- Renewal and extension options
- Assignment and subletting
- Default and remedies

Also include the complete text of any exhibits, addenda, or schedules that contain financial terms or definitions.`;

  const messages = [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
      { type: 'text', text: prompt },
    ],
  }];

  // 85s timeout — generating 8096 output tokens takes ~25-30s; allow headroom
  const res = await _fetchWithTimeout('/api/explain', {
    method:  'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body:    JSON.stringify({ task: 'lease_text_extraction', messages, max_tokens: 8096 }),
  }, 85000);

  if (!res.ok) throw new Error(`PDF text extraction failed: HTTP ${res.status}`);
  const data = await res.json();
  const text = data?.content?.[0]?.text;
  if (!text) throw new Error('No text returned from PDF text extraction');
  console.log('[extractTextFromPdfDirect] extracted', text.length, 'chars from', file.name);
  return text;
}

async function extractLeaseText(file) {
  // For non-PDFs read as plain text
  if (!file.name.toLowerCase().endsWith('.pdf') && file.type !== 'application/pdf') {
    return file.text();
  }

  // Try PDF.js text layer first (works for digital/searchable PDFs)
  let text = await extractPdfText(file);
  // WHY toLowerCase: legal PDFs routinely use all-caps headings ("LEASE AGREEMENT").
  // The original text.includes('Lease') is case-sensitive and returns false for 'LEASE',
  // incorrectly routing digital leases through PDF vision → hitting the 413 body limit.
  const isWeak = !text || text.length < 1000 || !text.toLowerCase().includes('lease') || text.split(' ').length < 100;

  if (!isWeak) {
    return text;
  }

  // Scanned / image-based PDF — return null so the caller uses Claude's PDF vision
  return null;
}

function normalizeText(text) {
  if (!text) return '';
  // WHY the 4th regex was removed: ([a-zA-Z])\s+([a-zA-Z]) → '$1$2' fused all words
  // together ("Commencement Date" → "CommencementDate", "Triple Net" → "TripleNet"),
  // breaking keyword-label detection in the regex fallback path.
  // The three remaining transforms are safe: CR → space, newline → space, collapse runs.
  return text
    .replace(/\r/g, ' ')
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractLeaseData(text) {
  if (!text || typeof text !== 'string') {
    return { start_date: '', end_date: '', lease_type: '' };
  }

  const matches = text.match(
    /\b(\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s+\d{4})\b/gi
  ) || [];

  const dates = matches
    .map(d => new Date(d))
    .filter(d => !isNaN(d))
    .sort((a, b) => a - b);

  return {
    start_date: dates[0]              ? dates[0].toISOString().slice(0, 10)              : '',
    end_date:   dates.length          ? dates[dates.length - 1].toISOString().slice(0, 10) : '',
    lease_type: /triple[\s-]?net|nnn/i.test(text)                             ? 'Triple Net (NNN)'
              : /modified[\s-]?gross/i.test(text)                              ? 'Modified Gross'
              : /pro\s*rata\s*share.{0,120}(?:taxes|insurance|operating)/i.test(text) ? 'NNN'
              : /gross/i.test(text)                                             ? 'Gross'
              : '',
  };
}

// Shims — delegate to ReviewEngine (review-engine.js)
function getWarnings(flags)       { return ReviewEngine.getWarnings(flags); }
function computeFlags(d)          { return ReviewEngine.computeFlags(d); }
function computeFlagsStrict(d)    { return ReviewEngine.computeFlagsStrict(d); }

// Extracts lines most likely to contain key lease fields.
function extractImportantSections(text) {
  const keywords = [
    'tenant', 'lessee', 'occupant', 'landlord', 'lessor',
    'term', 'commencement', 'expiration', 'commence', 'expires',
    'lease term', 'rent', 'square', 'premises', 'nnn', 'triple net',
    'gross', 'modified gross', 'sqft', 'sq ft', 'square feet',
  ];
  return text
    .split('\n')
    .filter(line => keywords.some(k => line.toLowerCase().includes(k)))
    .slice(0, 250)
    .join('\n');
}

// Builds the text sent to Claude: keyword lines first (signal boost),
// then head + tail of the full document so dates/terms near the middle
// and end of the lease are not lost to blind truncation.
function prepareLeaseTextForClaude(rawText) {
  if (!rawText) return '';
  const clean = rawText
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]{3,}/g, '  ')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();

  const keyLines  = extractImportantSections(clean);
  const head      = clean.slice(0, 4000);
  const tail      = clean.length > 4000 ? clean.slice(-2000) : '';

  return [
    keyLines ? `KEY SECTIONS:\n${keyLines}` : '',
    `FULL CONTEXT (start):\n${head}`,
    tail ? `FULL CONTEXT (end):\n${tail}` : '',
  ].filter(Boolean).join('\n\n...\n\n');
}

// Phase 0 (M5): the single source of truth for "can this lease be reconciled".
// Reads the list from lease-intelligence.js so the ingest gate and the
// explainability summary cannot drift apart again; the literal is a fallback for
// load-order and for Node test harnesses that have not evaluated the module.
function _reconciliationCriticalFields() {
  const fromModule = window.LeaseIntelligence?.RECONCILIATION_CRITICAL_FIELDS;
  return Array.isArray(fromModule) && fromModule.length
    ? fromModule
    : ['tenant_name', 'leased_sqft', 'start_date', 'end_date'];
}

// Lowers a confidence level by one step so it can never read 'high' for a lease
// that cannot be reconciled. Mirrors the thresholds in deriveExtractionConfidence.
function _capConfidenceLevel(level) {
  return level === 'high' ? 'medium' : level;
}

async function callClaudeForLease(text, fileName) {
  const leaseSnippet = prepareLeaseTextForClaude(text);
  // WHY cam_cap added: the system prompt (CLAUDE_LEASE_SYSTEM) always asks for cam_cap,
  // but the user prompt previously omitted it. Conflicting instructions caused Claude to
  // sometimes skip it. Now both prompts agree on the full canonical field set.
  const prompt = `
You are extracting structured data from a commercial lease document.
NOTE: This text may have been extracted via OCR from a scanned document — tolerate minor spelling errors, extra spaces, or character substitutions.
Return ONLY valid JSON. No explanation. No markdown.

Extract:
{
  "tenant_name": string,
  "lease_start_date": "YYYY-MM-DD" or null,
  "lease_end_date": "YYYY-MM-DD" or null,
  "cam_commencement_date": "YYYY-MM-DD" or null,
  "partial_period_basis": "per_diem" | "monthly" | "full_period" | null,
  "lease_type": "NNN" | "Gross" | "Modified Gross" | null,
  "sqft": number or null,
  "cam_cap": number or null,
  "admin_fee_pct": number or null,
  "gross_up_pct": number or null,
  "expense_stop": number or null,
  "audit_rights": true | false | null,
  "pro_rata_method": "rentable" | "leasable" | "occupied" | "gross" | null,
  "renewal_options": string or null,
  "excluded_categories": string or null,
  "property_name": string or null,
  "quotes": { "cam_cap": string|null, "admin_fee_pct": string|null, "gross_up_pct": string|null, "expense_stop": string|null, "audit_rights": string|null, "pro_rata_method": string|null, "renewal_options": string|null, "cam_commencement_date": string|null, "partial_period_basis": string|null }
}

TENANT NAME (highest priority):
- Look for labels: "Tenant:", "Lessee:", "Occupant:"
- If no label found: pick the first business entity (LLC, Inc, Corp, Ltd, L.P.)
- If multiple entities: EXCLUDE names with Properties/Realty/Holdings/Capital/Investments
- NEVER return null if any company name exists

DATES:
- Start: Commencement Date → Lease Start Date → Effective Date → Execution Date
- End: Expiration Date → Lease End Date → calculate from start + term length if needed

CAM COMMENCEMENT DATE: Only when the CAM/operating-expense obligation begins on a DIFFERENT date from the lease start — "commence payment of Operating Expenses upon the Rent Commencement Date", "upon opening for business", or after a stated free-rent or abatement period. Null when CAM begins with the term. Do NOT copy the lease start date here.

PARTIAL PERIOD BASIS: How the lease apportions CAM when the term covers only PART of an expense year. "per diem" / "number of days" → "per_diem". "prorated monthly" / "full calendar months" → "monthly". Full annual amount regardless of a partial year → "full_period". Return null if the lease is silent — null is a real answer, do NOT guess.

CAM CAP: Search the entire document for any language limiting CAM increases ("not to exceed", "capped at X%", "expense stop"). Return the number (e.g. 5% → 5). Null if no cap language exists.

PROPERTY NAME: The name or address of the building/property covered by this lease, as stated in the premises description or recitals (e.g. "Lakeview Plaza", "123 Main Street"). Null if not stated.

QUOTES: For each non-null extracted value, copy ≤120 chars of the exact verbatim clause text that led to that value.

IMPORTANT: Best guess always. Do not leave tenant_name null if any company name exists.

LEASE TEXT:
"""
${leaseSnippet}
"""
`;
  const messages = [{ role: 'user', content: prompt }];

  console.log('[EXTRACTION] starting lease extraction (text path)');
  const _extractStart = Date.now();

  const res = await _fetchWithTimeout('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: JSON.stringify({ messages, max_tokens: 1500, task: 'lease_extraction' }),
  });

  if (!res.ok) {
    throw new Error(`Lease extraction failed: HTTP ${res.status}`);
  }

  const response = await res.json();

  // Normalize: accept string, object, or array
  let parsed = response;
  if (typeof parsed === 'string') {
    try {
      parsed = JSON.parse(parsed);
    } catch (e) {
      console.error('[callClaudeForLease] Claude returned invalid JSON string:', parsed);
      return null;
    }
  }
  if (!Array.isArray(parsed)) {
    parsed = [parsed];
  }
  parsed = parsed.filter(t => t && typeof t === 'object');

  if (parsed.length === 0) {
    console.error('[callClaudeForLease] No valid tenant objects in response');
    return null;
  }

  const data = parsed[0];

  // Normalize leaseType so UI always receives the expected label
  const normalizeLeaseType = (val) => {
    if (!val) return null;
    const v = String(val).toLowerCase();
    if (v.includes('nnn') || v.includes('triple')) return 'Triple Net (NNN)';
    if (v.includes('modified'))                     return 'Modified Gross';
    if (v.includes('gross'))                        return 'Gross';
    return val;
  };
  // Safely parse a numeric value without coercing 0 to null
  const _pf = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
  // Normalize CAM cap: "35%" → 35, "0.35" → 35, "35" → 35
  const normalizeCap = val => {
    if (val == null) return null;
    const n = parseFloat(String(val).replace(/[^0-9.]/g, ''));
    if (isNaN(n)) return null;
    return n < 1 ? Math.round(n * 100) : n;
  };

  const raw = data;
  const _meta = (raw.__meta && typeof raw.__meta === 'object') ? raw.__meta : {};
  const cleanText = normalizeText(text);
  const fb = extractLeaseData(cleanText);

  // Accept either schema: tenant_name (user prompt) or tenantName (system prompt)
  const aiName = raw.tenant_name ?? raw.tenantName ?? null;
  // Regex fallback when Claude returns null/empty for the tenant name
  const resolvedName = (aiName && String(aiName).trim()) || extractTenantFromText(text) || '';
  const resolvedSqft = (() => {
    const v = raw.leasedSqft ?? raw.leased_sqft ?? raw.sqft ?? raw.squareFeet ?? null;
    if (v != null && v !== '') {
      const n = Number(String(v).replace(/[^0-9.]/g, ''));
      if (!isNaN(n)) return n;
    }
    return null;
  })();
  const resolvedStart = raw.lease_start_date ?? raw.startDate ?? raw.start_date ?? fb.start_date ?? '';
  const resolvedEnd   = raw.lease_end_date   ?? raw.endDate   ?? raw.end_date   ?? fb.end_date   ?? '';
  const resolvedType  = normalizeLeaseType(raw.lease_type ?? raw.leaseType ?? fb.lease_type) ?? '';


  const doc_has_dates = /\b(?:\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4})\b/i.test(text);
  const doc_has_lease_type = /triple[\s-]?net|nnn|gross|modified[\s-]?gross/i.test(text);

  const finalFlags = computeFlags({ start_date: resolvedStart, end_date: resolvedEnd, lease_type: resolvedType, flags: raw.flags, doc_has_dates, doc_has_lease_type });

  const normalized = normalizeTenant({
    tenant_name:         resolvedName,
    leased_sqft:         resolvedSqft,
    start_date:          resolvedStart,
    end_date:            resolvedEnd,
    lease_type:          resolvedType,
    cap:                 normalizeCap(raw.capPercentage ?? raw.cam_cap ?? null),
    // F-02: '' and null are DIFFERENT. '' means extraction ran and found no
    // exclusion schedule; null means the field was never extracted. This used to
    // collapse '' into null, and normalizeTenant then turned null back into '',
    // so CAM_EXCLUSIONS_UNDEFINED could never fire. SIGA proved it matters:
    // '' in Runs 1-2, five exclusions in Run 3, from byte-identical input.
    excluded_categories: raw.excludedCategories ?? raw.excluded_categories ?? null,
    baseYear:            raw.baseYear ?? null,
    confidence:          raw.confidence || {},
    flags:               finalFlags,
    doc_has_dates,
    doc_has_lease_type,
    _error:              null,
    admin_fee_pct:       _pf(raw.admin_fee_pct),
    gross_up_pct:        _pf(raw.gross_up_pct),
    expense_stop:        _pf(raw.expense_stop),
    audit_rights:        raw.audit_rights != null
      ? (typeof raw.audit_rights === 'string'
          ? raw.audit_rights.toLowerCase() === 'true'
          : Boolean(raw.audit_rights))
      : null,
    pro_rata_method:     raw.pro_rata_method ?? null,
    renewal_options:     raw.renewal_options ?? null,
    // WHEN THE CAM OBLIGATION BEGINS, when the lease sets it apart from the
    // lease term — free rent, delivery vs opening, "upon opening for business".
    // Nothing reads this field directly: LeasePeriod.obligationTerm() resolves
    // it against start_date and is the only owner of the question.
    cam_commencement_date: toISODate(raw.cam_commencement_date ?? raw.camCommencementDate ?? '') || null,
    // How the lease apportions CAM across a partial year. NULL IS A REAL
    // ANSWER — it means the lease is silent, and LeasePeriod.partialPeriodBasis
    // reports that as source 'default' rather than letting a product choice
    // read as lease-confirmed.
    partial_period_basis: (() => {
      const v = raw.partial_period_basis ?? raw.partialPeriodBasis ?? null;
      const k = v == null ? '' : String(v).trim().toLowerCase();
      return k === '' ? null : k;
    })(),
    property_name:       (() => {
      const v = raw.property_name ?? raw.propertyName ?? null;
      return (typeof v === 'string' && v.trim()) ? v.trim() : null;
    })(),
  });

  // Inject quote-bearing evidence snapshots for fields where Claude returned verbatim clause text.
  // Map: Claude quote key → normalized field key (cam_cap is stored as 'cap' in tenant objects).
  const _quoteMap = {
    cam_cap:          'cap',
    admin_fee_pct:    'admin_fee_pct',
    gross_up_pct:     'gross_up_pct',
    expense_stop:     'expense_stop',
    audit_rights:     'audit_rights',
    pro_rata_method:  'pro_rata_method',
    renewal_options:  'renewal_options',
    tenant_name:      'tenant_name',
    lease_type:       'lease_type',
    sqft:             'leased_sqft',
    lease_start_date: 'start_date',
    lease_end_date:   'end_date',
    cam_commencement_date: 'cam_commencement_date',
    partial_period_basis:  'partial_period_basis',
  };
  const _rawQuotes = (raw.quotes && typeof raw.quotes === 'object') ? raw.quotes : {};
  const _qTs = new Date().toISOString();
  const _extractionModel = _meta.model || null;
  let _fev = normalized.fieldEvidence || {};
  let _clauseMatchCount = 0;
  for (const [quoteKey, fieldKey] of Object.entries(_quoteMap)) {
    const qt = typeof _rawQuotes[quoteKey] === 'string' ? _rawQuotes[quoteKey].trim().slice(0, 200) : null;
    if (!qt) continue;
    _clauseMatchCount++;
    console.log(`[CLAUSE MATCH] ${fieldKey}: "${qt.slice(0, 60)}${qt.length > 60 ? '…' : ''}"`);
    const prev = (_fev[fieldKey] || { snapshots: [] }).snapshots;
    _fev = {
      ..._fev,
      [fieldKey]: { snapshots: [...prev, {
        fieldKey,
        value:                  normalized[fieldKey] ?? null,
        confidence:             { status: 'estimated', note: 'AI-extracted' },
        // Phase 0 (P1b): this read `normalized.fileName`, which is not set here —
        // the filename is spread onto the tenant later (processLeaseFile), so
        // every evidence snapshot persisted source_file NULL and the Evidence
        // Viewer had no document to name. The filename now arrives as a parameter.
        sourceFile:             fileName || normalized.fileName || null,
        page:                   null,
        section:                null,
        quote:                  qt,
        extractionId:           normalized._jobId || null,
        extractionVersion:      'v1',
        extractionModel:        _extractionModel,
        extractedAt:            _qTs,
        superseded:             false,
        amendmentId:            null,
        reviewerUid:            null,
        reviewerEmail:          null,
        reviewedAt:             _qTs,
        approved:               false,
        manuallyEdited:         false,
        originalExtractedValue: null,
      }]},
    };
  }
  normalized.fieldEvidence = _fev;

  // The model that ACTUALLY served this extraction, reported by Anthropic in
  // its own response and forwarded by api/claude.js as __meta.model. It was
  // already being written into each fieldEvidence snapshot here, but it stopped
  // at this function — so saveLeaseDocument() had nothing to record and two
  // call sites wrote the literal 'claude-3-5-sonnet-20241022' instead. That
  // model had not run in this product for some time; the Evidence Viewer
  // displayed it as provenance anyway.
  //
  // null when the response did not name a model. Never a default: a provenance
  // field that guesses is worse than one that is blank, because a blank one
  // cannot be mistaken for a record of what happened.
  normalized._extractionModel = _extractionModel;

  // Populate extraction telemetry for debugging / diagnostics panel
  const _extractMs = Date.now() - _extractStart;
  window.ms_extractionDebug = {
    model:               _extractionModel,
    inputTokens:         _meta.inputTokens  ?? null,
    outputTokens:        _meta.outputTokens ?? null,
    extractionDurationMs: _extractMs,
    OCRUsed:             false,
    OCRConfidence:       null,
    clauseMatches:       _clauseMatchCount,
    fallbackUsed:        normalized._usedFallback || false,
    extractionVersion:   'v1',
    lastExtractedAt:     _qTs,
  };
  console.log('[EXTRACTION] complete', {
    model: _extractionModel, ms: _extractMs,
    clauseMatches: _clauseMatchCount, tokens: _meta.outputTokens,
  });

  return normalized;
}

// ── Phase 21: Escrow & Reserve document extraction ──────────────────────────
//
// Generic text-extraction helper for non-lease documents. extractLeaseText()
// can't be reused as-is because its "weak text" heuristic checks for the
// literal word "lease", which never appears in mortgage/escrow/reserve
// documents and would force every digital PDF through the (slower, more
// expensive) vision path. Same PDF.js-first strategy, generic weak check.
async function extractDocumentText(file) {
  if (!file.name.toLowerCase().endsWith('.pdf') && file.type !== 'application/pdf') {
    return file.text();
  }
  const text = await extractPdfText(file);
  const isWeak = !text || text.length < 500 || text.split(' ').length < 60;
  return isWeak ? null : text;
}

// Reserve/escrow clauses can appear anywhere in a 20-50 page financing
// document (often buried mid-document, not near the top or bottom) — unlike
// prepareLeaseTextForClaude (lease-keyword-boosted head+tail truncation,
// tuned for lease term/rent/sqft which cluster near the start), this sends
// the full cleaned text up to a generous char budget, preserving every
// "--- Page N ---" marker so Claude can cite source pages accurately.
function prepareEscrowTextForClaude(rawText) {
  if (!rawText) return '';
  const clean = rawText
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]{3,}/g, '  ')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();
  const MAX_CHARS = 120000; // ~30k tokens — comfortably inside the model's context window
  return clean.length > MAX_CHARS ? clean.slice(0, MAX_CHARS) : clean;
}

async function callClaudeForEscrowDocument(text) {
  const snippet = prepareEscrowTextForClaude(text);
  const prompt = `
You are extracting lender reserve/escrow terms from a commercial real estate financing document.
NOTE: This text may have been extracted via OCR — tolerate minor spelling errors or spacing noise.
This document may describe more than one reserve account (e.g. a separate Roof Reserve, HVAC Reserve, and Capital Reserve). Return a JSON ARRAY with one element per distinct reserve account described, even if that means an array of one.
Return ONLY valid JSON. No explanation. No markdown.

Extract, for each reserve account found:
{
  "reserve_type": string,
  "reserve_name": string or null,
  "current_balance": number or null,
  "eligible_uses": string or null,
  "requires_invoices": true | false | null,
  "requires_photos": true | false | null,
  "requires_lien_waivers": true | false | null,
  "requires_contractor_bids": true | false | null,
  "requires_engineer_certification": true | false | null,
  "min_draw_amount": number or null,
  "requires_approval": true | false | null,
  "draw_request_deadline": "YYYY-MM-DD" or null,
  "repair_completion_deadline": "YYYY-MM-DD" or null,
  "reserve_expiration_date": "YYYY-MM-DD" or null,
  "notes": string or null,
  "evidence": { "reserve_type": {"quote": string|null, "page": number|null}, "current_balance": {"quote": string|null, "page": number|null}, "eligible_uses": {"quote": string|null, "page": number|null} }
}

RESERVE TYPE: Identify the reserve each element governs — "Roof Reserve", "HVAC Reserve", "Tenant Improvement Reserve", "Leasing Commission Reserve", "Capital Reserve", "Insurance Recovery Reserve", or the lender's own term.

DOCUMENT TEXT:
"""
${snippet}
"""
`;
  const messages = [{ role: 'user', content: prompt }];

  console.log('[ESCROW EXTRACTION] starting reserve document extraction (text path)');

  const res = await _fetchWithTimeout('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: JSON.stringify({ messages, max_tokens: 2400, task: 'escrow_extraction' }),
  });

  if (!res.ok) throw new Error(`Escrow document extraction failed: HTTP ${res.status}`);

  let parsed = await res.json();
  if (typeof parsed === 'string') {
    try { parsed = JSON.parse(parsed); } catch (e) {
      console.error('[callClaudeForEscrowDocument] invalid JSON string:', parsed);
      return null;
    }
  }
  if (!Array.isArray(parsed)) parsed = parsed ? [parsed] : [];
  parsed = parsed.filter(p => p && typeof p === 'object');
  return parsed.length ? parsed : null;
}

async function callClaudeForEscrowDocumentPdfDirect(file) {
  const base64 = await fileToBase64(file);

  const extractionPrompt = `Extract lender reserve/escrow terms from this financing document.
This document may describe more than one reserve account (e.g. a separate Roof Reserve, HVAC Reserve, and Capital Reserve). Return a JSON ARRAY with one element per distinct reserve account described, even if that means an array of one.
Return ONLY valid JSON. No explanation. No markdown.

[
  {
    "reserve_type": string,
    "reserve_name": string or null,
    "current_balance": number or null,
    "eligible_uses": string or null,
    "requires_invoices": true | false | null,
    "requires_photos": true | false | null,
    "requires_lien_waivers": true | false | null,
    "requires_contractor_bids": true | false | null,
    "requires_engineer_certification": true | false | null,
    "min_draw_amount": number or null,
    "requires_approval": true | false | null,
    "draw_request_deadline": "YYYY-MM-DD" or null,
    "repair_completion_deadline": "YYYY-MM-DD" or null,
    "reserve_expiration_date": "YYYY-MM-DD" or null,
    "notes": string or null,
    "evidence": {
      "reserve_type":    { "quote": string or null, "page": number or null },
      "current_balance": { "quote": string or null, "page": number or null },
      "eligible_uses":    { "quote": string or null, "page": number or null }
    }
  }
]

For evidence: copy the exact verbatim clause (≤160 chars) and the page number it appears on (page 1 = first page of the PDF). Never paraphrase. Null both if not determinable.
Return best guess — do not leave reserve_type null.`;

  const messages = [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
      { type: 'text', text: extractionPrompt },
    ],
  }];

  const res = await _fetchWithTimeout('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(await _authHeaders()) },
    body: JSON.stringify({ messages, max_tokens: 2400, task: 'escrow_extraction' }),
  });

  if (!res.ok) throw new Error(`Escrow PDF direct extraction failed: HTTP ${res.status}`);
  console.log('[ESCROW EXTRACTION] PDF direct (vision) path used');
  let parsed = await res.json();
  if (typeof parsed === 'string') {
    try { parsed = JSON.parse(parsed); } catch (e) {
      console.error('[callClaudeForEscrowDocumentPdfDirect] invalid JSON string:', parsed);
      return null;
    }
  }
  if (!Array.isArray(parsed)) parsed = parsed ? [parsed] : [];
  parsed = parsed.filter(p => p && typeof p === 'object');
  return parsed.length ? parsed : null;
}

// Opens a file picker and triggers escrow/reserve document upload for the active property.
// Accepts multiple PDFs at once — lender reserve packages typically arrive
// as several files (mortgage, reserve schedule, exhibits) that all describe
// the same reserve account(s) and should be processed together as one
// package rather than one upload at a time.
function openEscrowDocumentUpload() {
  const propertyId = activePropId;
  if (!propertyId) { showToast('Select a property first.', { color: '#92400e', textColor: '#fef3c7' }); return; }
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = '.pdf,application/pdf';
  inp.multiple = true;
  inp.style.display = 'none';
  inp.addEventListener('change', (e) => {
    if (e.target.files.length) handleEscrowDocumentUpload(propertyId, Array.from(e.target.files));
    inp.remove();
  });
  document.body.appendChild(inp);
  inp.click();
}

// Lets a user pick one or more new files to replace an existing reserve's
// source document(s) in place (same reserve card, fresh extraction) instead
// of creating a duplicate card.
function openEscrowDocumentReplace(reserveId) {
  const propertyId = activePropId;
  if (!propertyId) { showToast('Select a property first.', { color: '#92400e', textColor: '#fef3c7' }); return; }
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = '.pdf,application/pdf';
  inp.multiple = true;
  inp.style.display = 'none';
  inp.addEventListener('change', (e) => {
    if (e.target.files.length) handleEscrowDocumentUpload(propertyId, Array.from(e.target.files), { replaceReserveId: reserveId });
    inp.remove();
  });
  document.body.appendChild(inp);
  inp.click();
}

// Re-runs extraction against the document already on file for this reserve
// (e.g. after an extraction-pipeline fix) without requiring a re-upload.
async function reprocessEscrowReserveDocument(reserveId) {
  const propertyId = activePropId;
  const prop = _props.find(p => p.id === propertyId);
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === reserveId);
  if (!reserve || !reserve.sourceFileUrl) {
    showToast('No source document available to reprocess.', { color: '#92400e', textColor: '#fef3c7' });
    return;
  }
  try {
    // SEC-1 — the stored URL will not fetch once the bucket is private.
    const _readable = await resolveDocumentUrl(reserve.sourceFileUrl);
    if (!_readable) throw new Error('You do not have access to that document, or it is no longer stored');
    const res = await fetch(_readable);
    if (!res.ok) throw new Error('Could not fetch the stored document');
    const blob = await res.blob();
    const file = new File([blob], reserve.sourceFileName || 'reserve-document.pdf', { type: blob.type || 'application/pdf' });
    await handleEscrowDocumentUpload(propertyId, file, { replaceReserveId: reserveId });
  } catch (err) {
    console.error('[reprocessEscrowReserveDocument]', err);
    showToast('Reprocess failed: ' + (err.message || 'unknown error'), { color: '#7f1d1d', textColor: '#fca5a5' });
  }
}

// Reserve Package View — lists every source document accumulated onto a
// reserve card (a reserve commonly arrives as a multi-file lender package:
// mortgage, reserve schedule, exhibits — this is the one place a user can
// see and open all of them, instead of only the most recently uploaded one).
function openEscrowPackageView(reserveId) {
  const prop = currentProperty();
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === reserveId);
  if (!reserve) return;

  const docs = Array.isArray(reserve.sourceDocuments) ? reserve.sourceDocuments : [];
  const rows = docs.length
    ? docs.map(d => `
      <div class="escrow-doc-row">
        <span>${esc(d.fileName || 'Document')}</span>
        ${d.fileUrl ? docLinkHtml(d.fileUrl, 'View', { className: 'escrow-doc-btn' }) : ''}
      </div>`).join('')
    : `<p style="color:var(--text-3);font-size:0.85rem;">No source documents recorded for this reserve.</p>`;

  document.getElementById('escrowPackageBody').innerHTML = `
    <div class="modal-confirm-msg">${esc(reserve.reserveTypeLabel)} &mdash; ${docs.length} document${docs.length === 1 ? '' : 's'}</div>
    ${rows}`;
  document.getElementById('escrowPackageModal').style.display = 'flex';
}

function closeEscrowPackageView() {
  document.getElementById('escrowPackageModal').style.display = 'none';
}

function deleteEscrowReserve(reserveId) {
  const propertyId = activePropId;
  const prop = _props.find(p => p.id === propertyId);
  if (!prop) return;
  const reserve = (prop.escrowReserves || []).find(r => r.id === reserveId);
  if (!reserve) return;
  if (!confirm(`Delete the ${reserve.reserveTypeLabel} reserve? This cannot be undone.`)) return;
  prop.escrowReserves = (prop.escrowReserves || []).filter(r => r.id !== reserveId);
  _lsSave(prop);
  saveProperty(prop);
  logActivity('escrow_reserve_deleted', `Reserve deleted — ${reserve.reserveTypeLabel}`, {
    severity: 'warning', actor: 'User', relatedEntity: prop.name || 'Property',
  });
  showToast('Reserve deleted.', { color: '#052e16', textColor: '#86efac' });
  renderEscrowProfile(prop);
}

// Appends any source-document entries from `newDocs` not already present
// (by fileUrl) in `existingDocs`, so replace/reprocess actions accumulate a
// document history instead of losing it.
function _mergeEscrowSourceDocuments(existingDocs, newDocs) {
  const merged = Array.isArray(existingDocs) ? existingDocs.slice() : [];
  (Array.isArray(newDocs) ? newDocs : []).forEach(d => {
    if (!merged.some(m => m.fileUrl === d.fileUrl)) merged.push(d);
  });
  return merged;
}

// Orchestrates escrow/reserve document extraction and storage on the property.
// filesOrFile: a single File, or an array/FileList of Files uploaded together
// as one reserve package — they're extracted individually (each may mention
// different reserves) but merged as a single batch, so a reserve type that
// appears in more than one file in the batch (or more than once within the
// same file) collapses into one card with the union of every source's
// citations, instead of one card per extraction.
// opts.replaceReserveId: when set, the extracted reserve(s) matching that
// reserve's type are merged into the existing card (same id) instead of
// appending a new one — used by the Replace/Reprocess document actions.
let _escrowUploadInProgress = false;
async function handleEscrowDocumentUpload(propertyId, filesOrFile, opts = {}) {
  const prop = _props.find(p => p.id === propertyId);
  if (!prop) return;

  if (_escrowUploadInProgress) {
    showToast('A reserve document is already being processed — please wait.', { color: '#92400e', textColor: '#fef3c7' });
    return;
  }
  _escrowUploadInProgress = true;
  const uploadBtn = document.getElementById('escrowUploadBtn');
  const uploadBtnLabel = uploadBtn ? uploadBtn.innerHTML : null;
  if (uploadBtn) { uploadBtn.disabled = true; uploadBtn.innerHTML = '⏳ Processing…'; }

  const files = Array.isArray(filesOrFile) ? filesOrFile
    : (filesOrFile instanceof FileList ? Array.from(filesOrFile) : [filesOrFile]);

  const Engine = window.EscrowReserveEngine;

  try {
    let batchReserves = [];
    for (const file of files) {
      showToast(files.length > 1 ? `Reading ${file.name}…` : 'Reading reserve document…',
        { color: '#0c4a6e', textColor: '#7dd3fc', duration: 8000 });

      const docText = await extractDocumentText(file);
      let extractedList, extractionPath;
      if (docText && docText.length >= 50) {
        extractedList = await callClaudeForEscrowDocument(docText);
        extractionPath = 'text';
      } else {
        extractedList = await callClaudeForEscrowDocumentPdfDirect(file);
        extractionPath = 'pdf_vision';
      }
      if (!Array.isArray(extractedList)) extractedList = extractedList ? [extractedList] : [];
      if (!extractedList.length) {
        console.warn(`[handleEscrowDocumentUpload] no reserve fields extracted from ${file.name}`);
        continue;
      }

      const fileUrl = await uploadLeaseToStorage(file, propertyId);
      const reserves = extractedList.map(extracted => Engine.normalizeReserve(extracted, {
        sourceFileName: file.name,
        sourceFileUrl:  fileUrl,
        extractionPath,
        ocrChars: docText ? docText.length : null,
      }));
      batchReserves = batchReserves.concat(reserves);
    }

    if (!batchReserves.length) throw new Error('Could not extract reserve fields from the uploaded document(s)');

    // Collapse same-type reserves extracted anywhere in this batch (same
    // file, multiple pages, or multiple files in the same package) into one
    // reserve per type, carrying the union of their citations.
    let mergedBatch = Engine.mergeReserveExtractions(batchReserves);

    if (!Array.isArray(prop.escrowReserves)) prop.escrowReserves = [];
    const processedLabels = [];

    // Replace/reprocess: merge the matching extracted reserve into the
    // targeted card in place (keep its id) instead of appending a new one.
    if (opts.replaceReserveId) {
      const targetIdx = prop.escrowReserves.findIndex(r => r.id === opts.replaceReserveId);
      if (targetIdx !== -1) {
        const target = prop.escrowReserves[targetIdx];
        const matchIdx = mergedBatch.findIndex(r => r.reserveType === target.reserveType);
        const replacement = mergedBatch.splice(matchIdx !== -1 ? matchIdx : 0, 1)[0];
        replacement.id = target.id;
        replacement.sourceDocuments = _mergeEscrowSourceDocuments(target.sourceDocuments, replacement.sourceDocuments);
        prop.escrowReserves[targetIdx] = replacement;
        processedLabels.push(replacement.reserveTypeLabel);
      }
    }

    // De-duplicate against the property's existing reserves by reserve
    // type (not by source file name) — a property only ever shows one card
    // per reserve type; any newly-extracted reserve of a type already on
    // file is merged into that card instead of creating a duplicate.
    mergedBatch.forEach(newReserve => {
      const existingIdx = prop.escrowReserves.findIndex(r => r.reserveType === newReserve.reserveType);
      if (existingIdx !== -1) {
        const existing = prop.escrowReserves[existingIdx];
        const combined = Engine.mergeReserveExtractions([existing, newReserve])[0];
        combined.id = existing.id;
        prop.escrowReserves[existingIdx] = combined;
      } else {
        prop.escrowReserves.push(newReserve);
      }
      processedLabels.push(newReserve.reserveTypeLabel);
    });

    // Property memory: reserve work joins the property's history. Guarded and
    // deduped so a re-processed document cannot double-record.
    try {
      const _rk = 'reserve:' + processedLabels.join('|') + ':' + files.map(f => f && f.name).join('|');
      appendPropertyTimelineEventOnce(prop, _rk, {
        type: 'reserve_updated', severity: 'info',
        title: 'Reserve updated — ' + processedLabels.join(', '),
        description: files.length + ' source document' + (files.length !== 1 ? 's' : '') + ' processed.',
        metadata: { reserves: processedLabels.join(', '), documents: files.length },
        actor: 'Property Manager',
      });
    } catch (_e) { console.warn('[timeline] reserve_updated skipped:', _e && _e.message); }
    _lsSave(prop);
    await saveProperty(prop);
    const labels = processedLabels.join(', ');
    logActivity('escrow_document_uploaded', `Reserve document${files.length > 1 ? 's' : ''} uploaded — ${labels}`, {
      severity: 'success', actor: 'User', relatedEntity: prop.name || 'Property',
    });
    showToast(processedLabels.length > 1
      ? `✓ ${processedLabels.length} reserves extracted: ${labels}`
      : `✓ ${labels} extracted`, { color: '#052e16', textColor: '#86efac' });
    renderEscrowProfile(prop);
  } catch (err) {
    console.error('[handleEscrowDocumentUpload]', err);
    showToast('Reserve document upload failed: ' + (err.message || 'unknown error'), { color: '#7f1d1d', textColor: '#fca5a5', duration: 6000 });
  } finally {
    _escrowUploadInProgress = false;
    if (uploadBtn) { uploadBtn.disabled = false; uploadBtn.innerHTML = uploadBtnLabel; }
  }
}

// ─── Escrow & Reserve Profile (Track 2) ────────────────────────────────────

function renderEscrowProfile(property) {
  const listEl     = document.getElementById('escrowReservesList');
  const drawListEl = document.getElementById('escrowDrawRequestsList');
  if (!listEl || !drawListEl) return;

  const reserves = property.escrowReserves || [];
  const draws    = property.drawRequests   || [];
  const Engine   = window.EscrowReserveEngine;

  if (!reserves.length) {
    listEl.innerHTML = `<p style="color:var(--text-3);font-size:0.875rem;">No reserve documents uploaded yet. Upload a mortgage, loan, escrow, or reserve agreement above to extract reserve terms automatically.</p>`;
  } else {
    listEl.innerHTML = reserves.map(r => {
      const bal = Engine.computeReserveBalance(r, draws);
      const dl  = r.deadlines     || {};
      const req = r.requirements  || {};
      const reqBadges = [
        req.requiresInvoices               && 'Invoices',
        req.requiresPhotos                 && 'Photos',
        req.requiresLienWaivers            && 'Lien Waivers',
        req.requiresContractorBids         && 'Contractor Bids',
        req.requiresEngineerCertification  && 'Engineer Cert.',
        req.requiresApproval               && 'Approval',
      ].filter(Boolean).map(b => `<span class="escrow-req-badge">${esc(b)}</span>`).join('');

      const conf = r.extractionConfidence || { level: 'low', score: 0, reasons: [] };
      const confCls = { high: 'escrow-conf-high', medium: 'escrow-conf-medium', low: 'escrow-conf-low', failed: 'escrow-conf-low' }[conf.level] || 'escrow-conf-low';
      const confLabel = { high: 'High', medium: 'Medium', low: 'Low', failed: 'Failed' }[conf.level] || 'Low';
      const confTitle = (conf.reasons || []).join('; ') || 'Verbatim source quote found for key fields';
      const confBadge = `<span class="escrow-conf-badge ${confCls}" title="${esc(confTitle)}">Confidence: ${esc(confLabel)}</span>`;

      const pages = Array.isArray(r.sourcePages) ? r.sourcePages : [];
      const sourceLine = pages.length
        ? `<div class="escrow-source-pages">&#x1F4CE; Source: Page${pages.length > 1 ? 's' : ''} ${pages.join(', ')}${r.sourceFileName ? ` &middot; ${esc(r.sourceFileName)}` : ''}</div>`
        : (r.sourceFileName ? `<div class="escrow-source-pages">&#x1F4CE; Source: ${esc(r.sourceFileName)} (no page citation extracted)</div>` : '');

      const evidenceQuote = r.evidence?.current_balance?.quote || r.evidence?.reserve_type?.quote;
      const evidenceLine = evidenceQuote
        ? `<div class="escrow-reserve-notes" style="font-style:italic;">&#x201C;${esc(evidenceQuote)}&#x201D;</div>`
        : '';

      const docCount = Array.isArray(r.sourceDocuments) ? r.sourceDocuments.length : (r.sourceFileName ? 1 : 0);
      const hasCitation = !!(r.evidence && Object.values(r.evidence).some(ev => ev && ev.quote));
      const docMgmtLine = `
        <div class="escrow-doc-mgmt">
          <span class="escrow-doc-count">Reserve Package &mdash; ${docCount} document${docCount === 1 ? '' : 's'}</span>
          <button class="escrow-doc-btn" onclick="openEscrowPackageView('${r.id}')">&#x1F4C1; View Documents</button>
          <button class="escrow-doc-btn" onclick="openEscrowDocumentReplace('${r.id}')">Replace</button>
          ${r.sourceFileUrl ? `<button class="escrow-doc-btn" onclick="reprocessEscrowReserveDocument('${r.id}')">Reprocess AI</button>` : ''}
          ${hasCitation ? `<button class="escrow-doc-btn" onclick="openEscrowSourceCitation('${r.id}')">Source Citation</button>` : ''}
          <button class="escrow-doc-btn escrow-doc-btn-danger" onclick="deleteEscrowReserve('${r.id}')">Delete</button>
        </div>`;

      // Phase 21D: assistant-voice summary of the extracted terms (engine-built,
      // states only what is on file).
      const narrative = Engine.buildReserveNarrative ? Engine.buildReserveNarrative(r) : null;

      return `
      <div class="escrow-reserve-card" data-reserve-id="${esc(r.id)}">
        <div class="escrow-reserve-head">
          <strong>${esc(r.reserveTypeLabel)}</strong>
          <span class="escrow-reserve-balance">${fmt(bal.availableBalance)} available</span>
        </div>
        <div class="escrow-reserve-sub">of ${fmt(bal.currentBalance)} current balance${bal.committedAmount ? ` &middot; ${fmt(bal.committedAmount)} committed to open draws` : ''}</div>
        ${narrative ? `<div class="escrow-ai-summary"><div class="escrow-ai-summary-lbl">AI Summary</div>${esc(narrative)}</div>` : ''}
        ${confBadge}
        ${sourceLine}
        ${evidenceLine}
        ${r.eligibleUses ? `<div class="escrow-reserve-row"><span>Eligible Uses</span><span>${esc(r.eligibleUses)}</span></div>` : ''}
        ${reqBadges ? `<div class="escrow-req-badges">${reqBadges}</div>` : ''}
        ${dl.drawRequestDeadline      ? `<div class="escrow-reserve-row"><span>Draw Request Deadline</span><span>${esc(dl.drawRequestDeadline)}</span></div>` : ''}
        ${dl.repairCompletionDeadline ? `<div class="escrow-reserve-row"><span>Repair Completion Deadline</span><span>${esc(dl.repairCompletionDeadline)}</span></div>` : ''}
        ${dl.reserveExpirationDate    ? `<div class="escrow-reserve-row"><span>Reserve Expiration</span><span>${esc(dl.reserveExpirationDate)}</span></div>` : ''}
        ${r.notes ? `<div class="escrow-reserve-notes">${esc(r.notes)}</div>` : ''}
        ${docMgmtLine}
        <button class="report-btn" style="margin-top:8px;" onclick="openDrawBuilder('${r.id}')">+ New Draw Request</button>
      </div>`;
    }).join('');
  }

  if (!draws.length) {
    drawListEl.innerHTML = `<p style="color:var(--text-3);font-size:0.875rem;">No reserve requests yet. Start one from a reserve account above — for example, after a roof repair is completed, attach its invoices and documentation and MainStreet will assemble the lender package.</p>`;
  } else {
    const fmtHistoryDate = (iso) => {
      if (!iso) return '';
      const d = new Date(iso);
      return isNaN(d.getTime()) ? '' : d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) + ' ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
    };
    drawListEl.innerHTML = draws.slice().reverse().map(dr => {
      const reserve = reserves.find(r => r.id === dr.reserveId);
      const history = Array.isArray(dr.statusHistory) ? dr.statusHistory : [];
      const historyRows = history.map(h => `
        <div class="escrow-status-history-item">
          <div class="escrow-status-history-row">
            <span>${esc(Engine.DRAW_STATUS_LABELS[h.status] || h.status)}</span>
            <span>${esc(fmtHistoryDate(h.timestamp || h.at))}${h.actor ? ` &middot; ${esc(h.actor)}` : ''}</span>
          </div>
          ${h.note ? `<div class="escrow-status-history-note">${esc(h.note)}</div>` : ''}
        </div>`).join('');
      const historyBlock = historyRows
        ? `<div class="escrow-status-history">${historyRows}</div>`
        : '';
      const validation = reserve ? Engine.validateDrawRequest(reserve, dr, draws) : null;
      // Phase 21D: doc-checkmark chips + AI readiness status on each request card.
      const readiness = (reserve && Engine.computeEscrowReadiness && dr.status === 'draft')
        ? Engine.computeEscrowReadiness(reserve, dr, draws) : null;
      const _docsObj = dr.attachedDocuments || {};
      const _chip = (n, label) => n ? `<span class="escrow-docchip">&#x2713; ${n} ${label}${n > 1 ? 's' : ''}</span>` : '';
      const docChips = [
        _chip((dr.invoices || []).length, 'invoice'),
        _chip((_docsObj.contractorBids || []).length, 'contractor bid'),
        _chip((_docsObj.photos || []).length, 'photo'),
        _chip((_docsObj.lienWaivers || []).length, 'lien waiver'),
        _chip((_docsObj.engineerCertification || []).length, 'engineer report'),
      ].filter(Boolean).join('');
      const aiStatusHtml = readiness ? `
        <div class="escrow-ai-status ${readiness.ready ? 'escrow-ai-status--ok' : 'escrow-ai-status--warn'}">
          <span class="escrow-ai-status-head">AI Status: ${readiness.ready ? 'Ready for reimbursement' : 'Not ready yet'} &middot; ${readiness.score}%</span>
          <span class="escrow-ai-status-sub">${esc(readiness.summary || '')}</span>
        </div>` : '';
      return `
      <div class="escrow-draw-card" data-draw-id="${esc(dr.id)}">
        <div class="escrow-draw-head">
          <strong>${dr.drawNumber ? `Draw #${esc(dr.drawNumber)} &mdash; ` : ''}${esc(reserve ? reserve.reserveTypeLabel : 'Reserve')} &mdash; ${fmt(dr.amountRequested)}</strong>
        </div>
        ${docChips ? `<div class="escrow-docchips">${docChips}</div>` : ''}
        ${aiStatusHtml}
        ${_drawStatusStepperHtml(dr, Engine, validation)}
        ${historyBlock}
        <div class="escrow-draw-actions">
          <button class="report-btn" onclick="generateDrawPackageReport('${dr.id}')">&#x1F4CB; Generate Package</button>
          <button class="report-btn" onclick="openDrawEmailModal('${dr.id}')">&#x2709; Generate Email</button>
        </div>
      </div>`;
    }).join('');
  }
}

// ─── Draw Request Builder (Track 3 / 4) ────────────────────────────────────

let _drawDraft = null;
const DRAW_DOC_CATEGORY_LABELS = {
  photos: 'Photo', lienWaivers: 'Lien Waiver',
  contractorBids: 'Contractor Bid', engineerCertification: 'Engineer Certification',
};

function openDrawBuilder(reserveId) {
  const prop = currentProperty();
  if (!prop) return;
  const reserve = (prop.escrowReserves || []).find(r => r.id === reserveId);
  if (!reserve) return;

  _drawDraft = {
    reserveId, amountRequested: '', amountManuallySet: false, invoiceIds: [], showAllInvoices: false,
    attachedDocuments: { photos: [], lienWaivers: [], contractorBids: [], engineerCertification: [] },
  };
  _renderDrawBuilderBody(prop, reserve);
  document.getElementById('drawBuilderModal').style.display = 'flex';
}

function closeDrawBuilder() {
  document.getElementById('drawBuilderModal').style.display = 'none';
  _drawDraft = null;
}

// Keeps Amount Requested in sync with the selected invoices' total — a
// property manager who just picked $3,400 + $3,200 + $2,900 of invoices
// shouldn't have to re-type $9,500. Stops auto-filling once the user has
// typed their own value (amountManuallySet), and can be reset via the
// "Reset to invoice total" control.
function _autoFillDrawAmount() {
  if (!_drawDraft || _drawDraft.amountManuallySet) return;
  const prop = currentProperty();
  const allInvoices = (prop && prop.invoices) || [];
  const total = (_drawDraft.invoiceIds || [])
    .reduce((s, idx) => s + (parseFloat(allInvoices[idx] && allInvoices[idx].amount) || 0), 0);
  _drawDraft.amountRequested = total ? String(total) : '';
}

function _resetDrawAmountToInvoiceTotal() {
  if (!_drawDraft) return;
  _drawDraft.amountManuallySet = false;
  _autoFillDrawAmount();
  const prop = currentProperty();
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === _drawDraft.reserveId);
  if (reserve) _renderDrawBuilderBody(prop, reserve);
}

function _renderDrawBuilderBody(prop, reserve) {
  const allInvoices = prop.invoices || [];
  const Engine = window.EscrowReserveEngine;
  // Lender workflow: only show invoices classified for this reserve's type
  // (e.g. roofing invoices for a Roof Reserve draw) unless the user opts in
  // to seeing everything — covers invoices the classifier got wrong, and
  // properties where no invoices have been classified yet.
  const relevantIdx = [];
  allInvoices.forEach((inv, idx) => {
    const reserveType = inv.reserveType || (Engine ? Engine.classifyInvoiceReserveType(inv).reserveType : 'other');
    if (reserveType === reserve.reserveType) relevantIdx.push(idx);
  });
  const showAll = !!_drawDraft.showAllInvoices || relevantIdx.length === 0;
  const visibleIdx = showAll ? allInvoices.map((_, idx) => idx) : relevantIdx;

  const invoiceRows = visibleIdx.map(idx => {
    const inv = allInvoices[idx];
    return `
    <label class="escrow-invoice-row">
      <input type="checkbox" ${_drawDraft.invoiceIds.includes(idx) ? 'checked' : ''}
        onchange="_toggleDrawInvoice(${idx}, this.checked)">
      <span>${esc(inv.vendorName || inv.fileName || 'Vendor')} &mdash; ${fmt(inv.amount || 0)}</span>
    </label>`;
  }).join('') || `<p style="color:var(--text-3);font-size:0.85rem;">No invoices uploaded yet — upload invoices in the CAM tab, then return here to attach them to this draw.</p>`;

  const filterToggle = allInvoices.length > relevantIdx.length
    ? `<button class="modal-cancel" style="padding:2px 8px;margin-bottom:6px;" onclick="_toggleDrawInvoiceFilter()">${showAll ? 'Show relevant invoices only' : `Show all invoices (${allInvoices.length})`}</button>`
    : '';

  const selectedTotal = (_drawDraft.invoiceIds || [])
    .reduce((s, idx) => s + (parseFloat(allInvoices[idx] && allInvoices[idx].amount) || 0), 0);

  const docRows = Object.entries(_drawDraft.attachedDocuments)
    .flatMap(([cat, docs]) => docs.map((d, idx) => `
      <div class="escrow-doc-row">
        <span>${esc(DRAW_DOC_CATEGORY_LABELS[cat] || cat)}: ${esc(d.fileName)}</span>
        <button class="modal-cancel" style="padding:2px 8px;" onclick="_removeDrawSupportingDoc('${cat}', ${idx})">Remove</button>
      </div>`)).join('');

  // Submission readiness checklist — reuses the same Engine.validateDrawRequest
  // logic that gates the actual draw status workflow, so "ready" here means the
  // same thing it means once the draw is submitted, not a separate UI-only check.
  const draftForValidation = {
    amountRequested: _drawDraft.amountRequested,
    invoices: (_drawDraft.invoiceIds || []).map(idx => allInvoices[idx]).filter(Boolean),
    attachedDocuments: _drawDraft.attachedDocuments,
  };
  const validation = Engine ? Engine.validateDrawRequest(reserve, draftForValidation, prop.drawRequests || []) : null;
  // Phase 21B: Escrow Readiness Score — same validation gate, expressed as the
  // property-manager-facing "what is preventing the lender from releasing funds?"
  const readiness = (Engine && Engine.computeEscrowReadiness)
    ? Engine.computeEscrowReadiness(reserve, draftForValidation, prop.drawRequests || [])
    : null;
  const DOC_CHECK_KEYS = ['invoices', 'photos', 'lienWaivers', 'contractorBids', 'engineerCertification'];
  const DOC_CHECK_LABELS = { invoices: 'Invoices', photos: 'Photo', lienWaivers: 'Lien Waiver', contractorBids: 'Contractor Bid', engineerCertification: 'Engineer Certification' };
  const docChecklist = validation ? validation.checklist.filter(c => DOC_CHECK_KEYS.includes(c.key)) : [];
  const satisfiedDocs = docChecklist.filter(c => c.met);
  const missingDocs = docChecklist.filter(c => !c.met);
  const checklistHtml = docChecklist.length
    ? `
      <div class="escrow-section-label" style="margin-top:12px;">Required Documents</div>
      ${satisfiedDocs.map(c => `<div class="escrow-doc-row"><span>&#x2713; ${esc(DOC_CHECK_LABELS[c.key] || c.label)}</span></div>`).join('')}
      ${missingDocs.length ? `<div style="margin-top:4px;font-size:0.85rem;color:var(--c-fbbf24);">Missing:</div>${missingDocs.map(c => `<div class="escrow-doc-row"><span>&#x2610; ${esc(DOC_CHECK_LABELS[c.key] || c.label)}</span></div>`).join('')}` : ''}
      ${readiness ? `
      <div style="margin-top:10px;font-size:0.95rem;font-weight:700;color:${readiness.ready ? '#86efac' : '#fbbf24'};">
        Escrow Readiness: ${readiness.score}%
      </div>
      <div style="font-size:0.85rem;color:${readiness.ready ? '#86efac' : '#cbd5e1'};margin-top:3px;line-height:1.5;">${esc(readiness.summary || '')}</div>
      ${readiness.missing.slice(0, 4).map(i => `<div style="font-size:0.8rem;color:var(--c-fbbf24);margin-top:2px;">&#x26A0; ${esc(i.label)}${i.detail ? ` — ${esc(i.detail)}` : ''}</div>`).join('')}`
      : `<div style="margin-top:6px;font-size:0.85rem;color:${missingDocs.length === 0 ? '#86efac' : '#fbbf24'};">
        Submission Ready: ${satisfiedDocs.length} of ${docChecklist.length} documents
      </div>`}`
    : '';

  document.getElementById('drawBuilderBody').innerHTML = `
    <div class="modal-confirm-msg">New draw request against <strong>${esc(reserve.reserveTypeLabel)}</strong></div>
    <label style="display:block;margin:10px 0;">
      Amount Requested
      <input type="number" id="drawAmountInput" step="0.01" min="0" value="${esc(_drawDraft.amountRequested)}"
        onchange="_drawDraft.amountRequested = this.value; _drawDraft.amountManuallySet = true;" style="display:block;width:100%;margin-top:4px;">
      ${_drawDraft.invoiceIds.length ? `<button class="modal-cancel" style="padding:2px 8px;margin-top:4px;" onclick="_resetDrawAmountToInvoiceTotal()">Reset to invoice total (${fmt(selectedTotal)})</button>` : ''}
    </label>
    <div class="escrow-section-label">Invoices${selectedTotal ? ` &mdash; ${fmt(selectedTotal)} selected` : ''}</div>
    ${filterToggle}
    ${invoiceRows}
    ${checklistHtml}
    <div class="escrow-section-label" style="margin-top:12px;">Supporting Documents</div>
    ${docRows}
    <div style="display:flex;gap:6px;margin-top:6px;flex-wrap:wrap;">
      <button class="report-btn" onclick="addDrawSupportingDoc('photos')">+ Photo</button>
      <button class="report-btn" onclick="addDrawSupportingDoc('lienWaivers')">+ Lien Waiver</button>
      <button class="report-btn" onclick="addDrawSupportingDoc('contractorBids')">+ Contractor Bid</button>
      <button class="report-btn" onclick="addDrawSupportingDoc('engineerCertification')">+ Engineer Cert.</button>
    </div>`;
}

function _toggleDrawInvoice(idx, checked) {
  if (!_drawDraft) return;
  _drawDraft.invoiceIds = checked
    ? [...new Set([...(_drawDraft.invoiceIds || []), idx])]
    : _drawDraft.invoiceIds.filter(i => i !== idx);
  _autoFillDrawAmount();
  const prop = currentProperty();
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === _drawDraft.reserveId);
  if (reserve) _renderDrawBuilderBody(prop, reserve);
}

function _toggleDrawInvoiceFilter() {
  if (!_drawDraft) return;
  _drawDraft.showAllInvoices = !_drawDraft.showAllInvoices;
  const prop = currentProperty();
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === _drawDraft.reserveId);
  if (reserve) _renderDrawBuilderBody(prop, reserve);
}

function _removeDrawSupportingDoc(category, idx) {
  if (!_drawDraft) return;
  _drawDraft.attachedDocuments[category].splice(idx, 1);
  const prop = currentProperty();
  const reserve = (prop.escrowReserves || []).find(r => r.id === _drawDraft.reserveId);
  _renderDrawBuilderBody(prop, reserve);
}

function addDrawSupportingDoc(category) {
  if (!_drawDraft) return;
  const propertyId = activePropId;
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.style.display = 'none';
  inp.addEventListener('change', async (e) => {
    const file = e.target.files[0];
    inp.remove();
    if (!file || !_drawDraft) return;
    try {
      showToast('Uploading document…', { color: '#0c4a6e', textColor: '#7dd3fc', duration: 5000 });
      const fileUrl = await uploadLeaseToStorage(file, propertyId);
      _drawDraft.attachedDocuments[category].push({ fileName: file.name, fileUrl });
      const prop = currentProperty();
      const reserve = (prop.escrowReserves || []).find(r => r.id === _drawDraft.reserveId);
      _renderDrawBuilderBody(prop, reserve);
      showToast('✓ Document attached', { color: '#052e16', textColor: '#86efac' });
    } catch (err) {
      console.error('[addDrawSupportingDoc]', err);
      showToast('Upload failed: ' + (err.message || 'unknown error'), { color: '#7f1d1d', textColor: '#fca5a5' });
    }
  });
  document.body.appendChild(inp);
  inp.click();
}

async function confirmCreateDrawRequest() {
  if (!_drawDraft) return;
  const prop = currentProperty();
  if (!prop) return;
  const Engine = window.EscrowReserveEngine;

  const amountRequested = parseFloat(_drawDraft.amountRequested);
  if (!amountRequested || isNaN(amountRequested) || amountRequested <= 0) {
    showToast('Enter an amount greater than $0 before creating a draw request.', { color: '#7f1d1d', textColor: '#fca5a5' });
    return;
  }

  const invoices = (prop.invoices || []).filter((_, idx) => _drawDraft.invoiceIds.includes(idx));

  const now = new Date().toISOString();
  const drawRequest = {
    id: 'draw_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
    drawNumber: (prop.drawRequests || []).length + 1,
    reserveId: _drawDraft.reserveId,
    amountRequested,
    status: 'draft',
    invoices,
    attachedDocuments: _drawDraft.attachedDocuments,
    createdAt: now,
    statusHistory: [{ status: 'draft', timestamp: now, note: null, actor: 'User' }],
  };

  if (!Array.isArray(prop.drawRequests)) prop.drawRequests = [];
  prop.drawRequests.push(drawRequest);

  _lsSave(prop);
  await saveProperty(prop);
  logActivity('escrow_draw_created', `Draw request created — ${fmt(drawRequest.amountRequested)}`, {
    severity: 'info', actor: 'User', relatedEntity: prop.name || 'Property',
  });
  showToast('✓ Draw request created', { color: '#052e16', textColor: '#86efac' });
  closeDrawBuilder();
  renderEscrowProfile(prop);
}

// ─── Draw Request Tracking (Track 5) ────────────────────────────────────────

// Lifecycle stepper — replaces the old free-form status dropdown. Only
// renders the statuses Engine.getValidNextDrawStatuses() says are legal next
// steps as clickable, so a draw can no longer jump straight from Draft to
// Funded. "Reject" is shown as a separate action since it's a side-branch,
// not a forward step in the main lifecycle.
const _DRAW_MAIN_STAGES = ['draft', 'submitted', 'under_review', 'approved', 'funded'];

// Tracks which draw card currently has the inline rejection-reason form open
// (re-rendered cards lose DOM state, so this lives outside the markup).
let _drawRejectFormId = null;

function _showDrawRejectForm(drawRequestId) {
  _drawRejectFormId = drawRequestId;
  const prop = currentProperty();
  if (prop) renderEscrowProfile(prop);
}

function _cancelDrawRejectForm() {
  _drawRejectFormId = null;
  const prop = currentProperty();
  if (prop) renderEscrowProfile(prop);
}

async function _confirmDrawReject(drawRequestId) {
  const el = document.getElementById(`drawRejectReason-${drawRequestId}`);
  const reason = (el?.value || '').trim();
  if (!reason) {
    showToast('A rejection reason is required.', { color: '#7f1d1d', textColor: '#fca5a5' });
    return;
  }
  _drawRejectFormId = null;
  await updateDrawStatus(drawRequestId, 'denied', reason);
}

function _drawRejectFormHtml(dr) {
  return `<div class="draw-stepper">
    <div class="draw-reject-form">
      <label for="drawRejectReason-${dr.id}">Rejection reason (required)</label>
      <textarea id="drawRejectReason-${dr.id}" rows="2" placeholder="Explain why this draw is being rejected and what's needed to resubmit…"></textarea>
      <div class="draw-reject-form-btns">
        <button class="draw-step-reject" onclick="_confirmDrawReject('${dr.id}')">Confirm Rejection</button>
        <button class="d-cancel-btn" onclick="_cancelDrawRejectForm()">Cancel</button>
      </div>
    </div>
  </div>`;
}

// Reviewer-facing summary of why a draw was rejected and what's still
// unmet, so a property manager knows what to fix before resubmitting —
// reuses the same checklist the draw package PDF shows, computed live
// rather than duplicating its logic.
function _drawRejectionDetailHtml(dr, Engine, validation) {
  const lastDenied = (Array.isArray(dr.statusHistory) ? dr.statusHistory : [])
    .slice().reverse().find(h => h.status === 'denied');
  const reasonHtml = lastDenied && lastDenied.note
    ? `<div class="draw-rejection-reason"><strong>Reason:</strong> ${esc(lastDenied.note)}</div>`
    : `<div class="draw-rejection-reason draw-rejection-reason--none">No rejection reason was recorded.</div>`;
  const missing = (validation && validation.missing) || [];
  const remediationHtml = missing.length
    ? `<div class="draw-rejection-remediation">
        <strong>Before resubmitting, address:</strong>
        <ul>${missing.map(m => `<li>${esc(m.detail || m.label)}</li>`).join('')}</ul>
      </div>`
    : '';
  return `<div class="draw-rejection-detail">${reasonHtml}${remediationHtml}</div>`;
}

function _drawStatusStepperHtml(dr, Engine, validation) {
  if (_drawRejectFormId === dr.id) {
    return _drawRejectFormHtml(dr);
  }
  if (dr.status === 'denied') {
    return `<div class="draw-stepper draw-stepper--rejected">
      <span class="draw-step-rejected-badge">&#x2715; Rejected</span>
    </div>
    ${_drawRejectionDetailHtml(dr, Engine, validation)}`;
  }
  const currentIdx = _DRAW_MAIN_STAGES.indexOf(dr.status);
  const nextValid = Engine.getValidNextDrawStatuses(dr.status);
  const nextForward = nextValid.find(s => s !== 'denied');
  const pillsHtml = _DRAW_MAIN_STAGES.map((s, idx) => {
    const state = idx < currentIdx ? 'done' : idx === currentIdx ? 'current' : 'upcoming';
    const clickable = s === nextForward;
    return `<button class="draw-step draw-step--${state}"
      title="${esc(Engine.DRAW_STATUS_LABELS[s])}${clickable ? ' — click to advance' : ''}"
      ${clickable ? `onclick="updateDrawStatus('${dr.id}','${s}')"` : 'disabled'}>
      <span class="draw-step-dot"></span><span class="draw-step-label">${esc(Engine.DRAW_STATUS_LABELS[s])}</span>
    </button>`;
  }).join('<span class="draw-step-connector"></span>');
  const rejectBtnHtml = nextValid.includes('denied')
    ? `<button class="draw-step-reject" onclick="_showDrawRejectForm('${dr.id}')">Reject</button>`
    : '';
  return `<div class="draw-stepper">${pillsHtml}${rejectBtnHtml}</div>`;
}

async function updateDrawStatus(drawRequestId, status, note) {
  const prop = currentProperty();
  if (!prop) return;
  const ok = window.EscrowReserveEngine.applyDrawStatus(prop.drawRequests || [], drawRequestId, status, { actor: 'User', note: note || null });
  if (!ok) {
    showToast('That status change isn’t allowed — draws must move through each stage in order.', { color: '#7f1d1d', textColor: '#fca5a5' });
    return;
  }

  _lsSave(prop);
  await saveProperty(prop);
  logActivity('escrow_draw_status', `Draw request status changed to ${window.EscrowReserveEngine.DRAW_STATUS_LABELS[status]}${note ? ` — ${note}` : ''}`, {
    severity: 'info', actor: 'User', relatedEntity: prop.name || 'Property',
  });
  renderEscrowProfile(prop);
}

// ─── Draw Request Package Generation (Track 4) ──────────────────────────────

function generateDrawPackageReport(drawRequestId) {
  const prop = currentProperty();
  if (!prop) return;
  const Engine = window.EscrowReserveEngine;
  const drawRequest = (prop.drawRequests || []).find(d => d.id === drawRequestId);
  const reserve     = drawRequest && (prop.escrowReserves || []).find(r => r.id === drawRequest.reserveId);
  if (!drawRequest || !reserve) return;

  const validation = Engine.validateDrawRequest(reserve, drawRequest, prop.drawRequests || []);
  const pkg = Engine.buildDrawRequestPackage(prop, reserve, drawRequest, validation);
  const html = window.EscrowDrawPackets.formatDrawPackageHtml(pkg);

  logActivity('escrow_draw_package', `Draw request package generated — ${pkg.complete ? 'lender-ready' : 'draft'}`, {
    severity: pkg.complete ? 'success' : 'warning', actor: 'User', relatedEntity: prop.name || 'Property',
  });
  openReport('Escrow Draw Request Package', html);
}

// ─── Draw Submission Email (Track 6) ────────────────────────────────────────

let _drawEmailDrawId = null;

function openDrawEmailModal(drawRequestId) {
  const prop = currentProperty();
  if (!prop) return;
  const Engine = window.EscrowReserveEngine;
  const drawRequest = (prop.drawRequests || []).find(d => d.id === drawRequestId);
  const reserve     = drawRequest && (prop.escrowReserves || []).find(r => r.id === drawRequest.reserveId);
  if (!drawRequest || !reserve) return;

  const draft = Engine.buildDrawEmailDraft(prop, reserve, drawRequest);
  _drawEmailDrawId = drawRequestId;
  document.getElementById('drawEmailSubject').value = draft.subject;
  document.getElementById('drawEmailBody').value    = draft.body;
  document.getElementById('drawEmailMailtoLink').href =
    'mailto:?subject=' + encodeURIComponent(draft.subject) + '&body=' + encodeURIComponent(draft.body);
  document.getElementById('drawEmailModal').style.display = 'flex';

  logActivity('escrow_draw_email', `Draw request email draft generated — ${reserve.reserveTypeLabel}`, {
    severity: 'info', actor: 'User', relatedEntity: prop.name || 'Property',
  });
}

function closeDrawEmailModal() {
  document.getElementById('drawEmailModal').style.display = 'none';
  _drawEmailDrawId = null;
}

function copyDrawEmailField(fieldId, btnId) {
  const input = document.getElementById(fieldId);
  input.select();
  try {
    navigator.clipboard.writeText(input.value).catch(() => document.execCommand('copy'));
  } catch { document.execCommand('copy'); }
  const btn  = document.getElementById(btnId);
  const orig = btn.textContent;
  btn.textContent = '✓ Copied!';
  setTimeout(() => { btn.textContent = orig; }, 2000);
}

// ─── Reserve Source Citation Viewer ─────────────────────────────────────────

function openEscrowSourceCitation(reserveId) {
  const prop = currentProperty();
  const reserve = prop && (prop.escrowReserves || []).find(r => r.id === reserveId);
  if (!reserve) return;

  // Phase 24: route into the Interactive Evidence Viewer (document render +
  // quote highlight) when available; the legacy quote-only modal remains the
  // fallback so the button never dead-ends.
  if (window.EvidenceViewer) {
    const cites = EvidenceViewer.fromReserve(reserve);
    if (cites.length) { EvidenceViewer.open({ citations: cites, index: 0 }); return; }
  }

  const evidence = reserve.evidence || {};
  const fieldLabels = { reserve_type: 'Reserve Type', current_balance: 'Current Balance', eligible_uses: 'Eligible Uses' };
  const rows = Object.entries(evidence)
    .filter(([, ev]) => ev && ev.quote)
    .map(([field, ev]) => `
      <div class="escrow-citation-item">
        <div class="escrow-citation-head">
          <strong>${esc(fieldLabels[field] || field)}</strong>
          <span>${esc(reserve.sourceFileName || 'Reserve Agreement')}${ev.page != null ? ` &middot; Page ${esc(ev.page)}` : ''}</span>
        </div>
        <blockquote class="escrow-citation-quote">&#x201C;${esc(ev.quote)}&#x201D;</blockquote>
      </div>`).join('');

  document.getElementById('escrowCitationBody').innerHTML = rows ||
    `<p style="color:var(--text-3);font-size:0.85rem;">No verbatim source citations available for this reserve.</p>`;
  document.getElementById('escrowCitationModal').style.display = 'flex';
}

function closeEscrowSourceCitation() {
  document.getElementById('escrowCitationModal').style.display = 'none';
}

// ─── SVG icons ────────────────────────────────────────────────────────────────
const CHECK_SVG = `<svg viewBox="0 0 12 12" width="10" height="10" fill="none" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="2,6 5,9 10,3"/></svg>`;
const CROSS_SVG = `<svg viewBox="0 0 12 12" width="10" height="10" stroke="white" stroke-width="2.2" stroke-linecap="round"><line x1="2" y1="2" x2="10" y2="10"/><line x1="10" y1="2" x2="2" y2="10"/></svg>`;

// ─── Tenant Slots ─────────────────────────────────────────────────────────────

function renderTenantSlots() {
  const container = document.getElementById('tenantSlots');
  container.innerHTML = '';
  for (let i = 0; i < MAX_LEASES; i++) {
    const slot = document.createElement('div');
    slot.className = 'tenant-slot';
    slot.id = `ts-${i}`;
    slot.innerHTML = `<div class="slot-head">Tenant ${i + 1}</div>
                      <div class="slot-body" id="tb-${i}"></div>`;
    container.appendChild(slot);
    renderTenantUploadZone(i);
  }
}

function renderTenantUploadZone(i) {
  const body = document.getElementById(`tb-${i}`);
  const zone = document.createElement('div');
  zone.className = 'upload-zone';

  const inp = document.createElement('input');
  inp.type   = 'file';
  inp.accept = '.pdf,application/pdf';
  inp.addEventListener('change', e => {
    if (e.target.files[0]) handleLease(i, e.target.files[0]);
  });

  zone.innerHTML = `<div class="uz-icon">📄</div>
                    <div class="uz-label">Upload Lease</div>
                    <div class="uz-sub">PDF only</div>`;
  zone.appendChild(inp);
  body.innerHTML = '';
  body.appendChild(zone);
}

async function handleLease(i, file) {
  console.log('[handleLease] dropped:', file.name, `(${(file.size/1024).toFixed(1)} KB)`);
  const body = document.getElementById(`tb-${i}`);
  body.innerHTML = `<div class="spinner-wrap">
    <div class="spinner"></div>
    <div class="spinner-label">AI reading lease…</div>
  </div>`;

  const property = currentProperty();
  if (!property) { renderTenantError(i, 'No property selected'); return; }

  // Only clear this slot — preserve other tenants already uploaded
  tenantData[i] = null;

  try {
    // Ensure property has a DB id so the storage path is valid
    if (!property.id) await saveProperty(property);

    // Upload to storage and extract text in parallel — neither depends on the other
    const [leaseUrl, leaseText] = await Promise.all([
      uploadLeaseToStorage(file, property.id),
      extractLeaseText(file),
    ]);

    // Digital PDF: text layer extracted — send text to Claude
    // Scanned PDF: leaseText is null/short — send PDF bytes directly (vision)
    let extracted;
    let _visionTextPromise = null;
    const _usedPdfDirect = !(leaseText && leaseText.length >= 50);
    if (!_usedPdfDirect) {
      // Telemetry: the text path — the majority case we want to confirm.
      const _tt = window.LeaseIngest ? window.LeaseIngest.begin(file.size) : null;
      if (_tt) window.LeaseIngest.mark(_tt, { path: window.LeaseIngest.PATHS.TEXT, payloadBytes: leaseText.length });
      try {
        extracted = await callClaudeForLease(leaseText, file.name);
        if (_tt) { window.LeaseIngest.end(_tt, 'success'); _recordIngestTelemetry(window.LeaseIngest.summary(_tt)); }
      } catch (e) {
        if (_tt) { window.LeaseIngest.end(_tt, 'failure', 'text-extraction-failed'); _recordIngestTelemetry(window.LeaseIngest.summary(_tt)); }
        throw e;
      }
    } else {
      // Start text extraction concurrently with field extraction — both need the
      // same file but neither depends on the other's result.
      _visionTextPromise = extractTextFromPdfDirect(file).catch(e => {
        console.warn('[extractTextFromPdfDirect:single] failed:', e?.message);
        return null;
      });
      extracted = await callClaudeWithPdfDirect(file);
    }

    if (!extracted) throw new Error('Could not extract lease fields');
    const normalized = normalizeTenant(extracted);
    if (!isValidTenant(normalized)) throw new Error('Extracted tenant has no usable fields');

    // Phase 19: edge case detection — mirrors the bulk upload pipeline (_runLeaseJobPipeline)
    // so single-lease uploads also catch property-name mismatches and other extraction risks.
    if (window.LeaseIntelligence) {
      const _liCtx = {
        ocrChars: (!_usedPdfDirect && leaseText) ? leaseText.length : 0,
        usedPdfDirect: _usedPdfDirect,
        ocrText: (!_usedPdfDirect && leaseText) ? leaseText.slice(0, 500) : null,
        currentPropertyName: property.name || null,
      };
      normalized._edgeCases = window.LeaseIntelligence.detectLeaseEdgeCases(normalized, _liCtx);
      normalized._explainability = window.LeaseIntelligence.generateLeaseExplainability(normalized);
    }

    tenantData[i] = { ...normalized, leaseFile: file, leaseExpected: true, fileName: file.name, leaseUrl };
    storeLeaseFile(normalized.id, file);
    renderTenantFields(i);
    checkSqftValidation();

    const deduped = dedupeTenants(tenantData.filter(t => t !== null));
    property.tenants = deduped;

    await saveProperty(property);
    // Full resync ONCE after save — replaces any stale rows for this property
    await resyncTenantsToTable(property.id, deduped);

    // Phase 22A/22C: persist lease document record.
    // For vision-path leases, await the text extraction promise started earlier.
    // UI is already updated (renderTenantFields ran above) so this wait is invisible.
    const _extractedText = _usedPdfDirect
      ? (await _visionTextPromise)
      : leaseText;
    saveLeaseDocument({
      propertyId:      property.id,
      tenantId:        normalized.id || null,
      tenantName:      normalized.tenant_name || null,
      fileName:        file.name,
      fileUrl:         leaseUrl,
      extractedText:   _extractedText,
      parsingStatus:   'success',
      // The model that ran, not a literal. See normalizeExtractedTenant().
      extractionModel: normalized._extractionModel ?? null,
      usedPdfDirect:   _usedPdfDirect,
    }).catch(e => console.warn('[saveLeaseDocument:single] failed:', e?.message));
  } catch (err) {
    renderTenantError(i, err.message);
  }
}

// ─── Sqft Validation ─────────────────────────────────────────────────────────

function validateTotalSqFt(property, newLease) {
  const totalSqFt = parseFloat(property.totalSqFt || property.totalSqft) || 0;
  if (!totalSqFt) return { valid: true, message: null };

  const existingTotal = (property.leases || [])
    .filter(l => l.tenantName !== (newLease?.tenantName))
    .reduce((s, l) => s + (parseSqft(l.sqFt || l.leasedSqft)), 0);

  const newTotal = existingTotal + parseSqft(newLease?.sqFt || newLease?.leasedSqft || 0);

  if (newTotal > totalSqFt) {
    return {
      valid: false,
      message: `Total tenant square footage (${newTotal.toLocaleString()} sqft) exceeds property total (${totalSqFt.toLocaleString()} sqft). Please adjust.`,
    };
  }
  return { valid: true, message: null };
}

function checkSqftValidation() {
  const prop = currentProperty();
  const totalSqFt = Number(prop?.totalSqft) || 0;
  if (!totalSqFt) { window._sqftInvalid = false; clearSqftBanner(); return true; }

  const usedSqFt = tenantData.filter(t => t).reduce((s, t) => s + parseSqft(t.leased_sqft), 0);

  if (!usedSqFt) { window._sqftInvalid = false; clearSqftBanner(); return true; }

  window._sqftInvalid = usedSqFt > totalSqFt;

  const used  = usedSqFt.toLocaleString();
  const total = totalSqFt.toLocaleString();

  if (usedSqFt > totalSqFt) {
    showSqftBanner(`⚠ Total leased (${used} sqft) exceeds building total (${total} sqft). Please adjust tenant sizes.`, 'over');
  } else if (usedSqFt < totalSqFt) {
    showSqftBanner(`⚠ Total leased (${used} sqft) is less than building total (${total} sqft). Some space may be unaccounted for.`, 'under');
  } else {
    window._sqftInvalid = false;
    clearSqftBanner();
  }
  return !window._sqftInvalid;
}

function runCamValidation() {
  const prop = currentProperty();

  const validTenants = getValidTenants();

  const tenantTotal = validTenants.reduce(
    (sum, t) => sum + (Number(t.leased_sqft) || 0),
    0
  );

  const propertyTotal = Number(prop?.totalSqft) || 0;


  const isValid = tenantTotal <= propertyTotal;

  window._sqftInvalid = !isValid;

  if (!isValid) {
    return;
  }

  if (typeof calculateCAM === 'function') calculateCAM();
}

// True when the lease's own stated property/building name doesn't match the
// property it was uploaded into (see lease-intelligence.js PROPERTY_NAME_MISMATCH
// edge case, populated by detectLeaseEdgeCases()). Same check review-engine.js
// uses to flag "Needs Review" — reused here to keep the tenant out of CAM math
// until a human resolves the mismatch, rather than just warning about it.
function _hasPropertyMismatch(t) {
  const edgeCaseTypes = (t?._edgeCases && Array.isArray(t._edgeCases.edgeCases))
    ? t._edgeCases.edgeCases.map(e => e.type) : [];
  return edgeCaseTypes.includes('PROPERTY_NAME_MISMATCH');
}

// Whether a detected mismatch is STILL BLOCKING, i.e. detected and not resolved
// by an explicit landlord confirmation. _hasPropertyMismatch() above is the raw
// detector and is deliberately left alone — a confirmed lease still carries its
// mismatch on _edgeCases, still shows in AI Review Notes, and still reads as a
// mismatch to anything that asks. Confirmation resolves the CONSEQUENCE, never
// the finding.
//
// Returns null when CAM may proceed; otherwise the reason, for the card and the
// banner. Mirrors _exclusionBlockReason()'s shape on purpose, including its
// stale case: a confirmation that no longer matches the lease in front of us is
// reported as stale rather than quietly ignored, so the landlord is told why
// they are being asked again.
function _propertyMismatchBlockReason(t) {
  if (!_hasPropertyMismatch(t)) return null;

  const LI = window.LeaseIntelligence;
  const confirmed = LI && typeof LI.isPropertyMismatchConfirmed === 'function'
    ? LI.isPropertyMismatchConfirmed(t)
    : false;   // module missing ⇒ nothing is confirmed ⇒ stays blocked

  // A confirmation belongs to the property it was made in. If this record has
  // been copied or moved to a different property, the human verification does
  // not travel with it.
  const c = t && t._propertyConfirm;
  const sameProperty = !c || !c.propertyId || !activePropId || c.propertyId === activePropId;

  if (confirmed && sameProperty) return null;

  return {
    tenantName:    t.tenant_name,
    extractedName: (t.property_name || '').trim(),
    propertyName:  (currentProperty()?.name || '').trim(),
    hasConfirm:    !!c,
    staleConfirm:  !!c && (!confirmed || !sameProperty),
  };
}

function getValidTenants() {
  return (currentProperty()?.tenants || []).filter(t =>
    t &&
    t.tenant_name &&
    // WAS Number(t.leased_sqft) > 0, which is NaN for "50,000" — so a lease with
    // a formatted area was dropped from CAM while every warning surface, which
    // used parseSqft, stayed silent about it. This function still OWNS the
    // eligibility decision; it no longer owns a private opinion about what the
    // value means.
    window.SourceValues.readArea(t.leased_sqft).usable &&
    !t.extractionFailed &&
    !_propertyMismatchBlockReason(t)
  );
}

function renderFailedTenants(tenants) {
  const el = document.getElementById('bulkResults');
  if (!el || !tenants.length) return;
  const srcTenants = currentProperty()?.tenants || tenantData;
  const rows = tenants.map((d) => {
    const i = srcTenants.findIndex(t => t?.id && t.id === d?.id);
    if (i === -1) return '';
    return `
      <div class="bulk-tenant-row has-error" id="btr-failed-${i}">
        <div class="bulk-tenant-summary">
          <span class="bulk-t-status">❌</span>
          <span class="bulk-t-name">${esc(d.fileName || d.tenant_name || 'Unknown')}</span>
          <span class="bulk-t-meta" data-retry data-index="${i}" style="cursor:pointer;">Extraction failed — tap to re-upload</span>
          <button class="view-lease-btn" data-retry data-index="${i}" style="margin-left:0;color:var(--c-f97316);">&#x21BA; Retry</button>
          <button class="bulk-t-remove" onclick="event.stopPropagation();removeBulkTenant(${i})">Remove</button>
        </div>
      </div>`;
  }).join('');
  el.insertAdjacentHTML('beforeend', `
    <div class="bulk-results-head" style="margin-top:16px;border-top:1px solid rgba(239,68,68,0.2);padding-top:12px;">
      <h3 style="color:var(--c-f87171);">Needs Attention (${tenants.length})</h3>
    </div>
    ${rows}`);
}

function updatePropertySqft(val) {
  const prop = currentProperty();
  if (!prop) return;

  const nameEl = document.getElementById('propertyName');
  if (nameEl && nameEl.value.trim()) prop.name = nameEl.value.trim();

  prop.totalSqft = Number(val) || 0;

  saveProperty(prop);

  checkSqftValidation();
  runCamValidation();

  // Do NOT re-render the property while the number is still being typed.
  //
  // renderProperty() rebuilds the whole pane — including switchLeaseTab('bulk')
  // and renderBulkResults() — and it ran on every keystroke. On a phone that
  // relayout under an open keyboard threw the page to the top and dropped focus
  // after the FIRST digit, so "25550" needed five separate taps. The model,
  // localStorage, the sqft banner and CAM validation above are all already
  // up to date; the only thing deferred is redrawing the surrounding DOM.
  //
  // The full render happens on commit (blur / Enter) via commitPropertySqft().
  const sqftEl = document.getElementById('totalSqft');
  if (document.activeElement === sqftEl) return;

  renderProperty(prop);
}

// Commit point for Total Sqft: the user has finished typing (blur, or Enter).
// This is where the deferred renderProperty() from updatePropertySqft() happens,
// so the pane catches up exactly once instead of once per digit.
function commitPropertySqft(val) {
  const prop = currentProperty();
  if (!prop) return;
  prop.totalSqft = Number(val) || 0;
  saveProperty(prop);
  checkSqftValidation();
  runCamValidation();
  // Refresh, not navigation: the user is still on this screen and may be
  // reaching for Save. Jumping to the top here is the same defect one beat later.
  renderProperty(prop, { scrollToTop: false });
}

function showSqftBanner(msg, severity) {
  const el = document.getElementById('sqft-error');
  if (!el) { return; }
  el.innerText = msg;
  el.dataset.severity = severity;
  el.classList.remove('hidden');
}

function clearSqftBanner() {
  const el = document.getElementById('sqft-error');
  if (!el) return;
  el.innerText = '';
  el.classList.add('hidden');
  delete el.dataset.severity;
}

function toInputDate(val) {
  if (!val) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(val)) return val;
  const d = new Date(val);
  if (!isNaN(d)) return d.toISOString().slice(0, 10);
  const m = val.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`;
  return '';
}

function renderTenantFields(i) {
  const d = tenantData[i];
  const body = document.getElementById(`tb-${i}`);
  body.innerHTML = `
    <div class="extracted">
      <div class="status-row ok">
        <span class="status-dot ok">${CHECK_SVG}</span>
        Fields extracted — review and edit below
        <button class="re-btn" onclick="resetTenant(${i})">Re-upload</button>
      </div>
      ${_requiredGapsHtml(d, i, false)}
      ${_leaseEdgeCaseAndReviewNotesHtml(d, i)}
      ${d.leaseExpected
        ? (d.leaseFile instanceof File || d.leaseUrl)
          ? `<button class="action-btn" onclick="openLeaseModalFromFile(${i})">&#x1F4C4; View Lease</button>`
          : `<div class="lease-missing-note">⚠️ Lease not attached — using manual data</div>`
        : ''}
      <div class="field-row">
        <div class="field">
          <label>Tenant Name</label>
          <input type="text" value="${esc(d.tenant_name || '')}"
            onfocus="isEditingField=true"
            onblur="handleFieldBlur(${i},'tenant_name',this.value)"/>
        </div>
        <div class="field">
          <label title="The square footage this tenant occupies — not the total building size. Used to calculate this tenant's pro-rata share of CAM expenses.">Leased Sqft &#x24D8;</label>
          <input type="number" value="${d.leased_sqft ?? ''}"
            onfocus="isEditingField=true"
            onblur="handleFieldBlur(${i},'leased_sqft',this.value);checkSqftValidation()"/>
        </div>
      </div>
      <div class="field-row">
        <div class="field">
          <label>Lease Start Date</label>
          <input type="date" value="${toInputDate(d.start_date)}"
            onfocus="isEditingField=true"
            onblur="handleFieldBlur(${i},'start_date',this.value)"/>
        </div>
        <div class="field">
          <label>Lease End Date</label>
          <input type="date" value="${toInputDate(d.end_date)}"
            onfocus="isEditingField=true"
            onblur="handleFieldBlur(${i},'end_date',this.value)"/>
        </div>
      </div>
      <div class="field-row">
        <div class="field">
          <label>Lease Type</label>
          <select onchange="handleFieldBlur(${i},'lease_type',this.value||null)">
            <option value="">Select lease type</option>
            <option value="Triple Net (NNN)"${d.lease_type === 'Triple Net (NNN)' ? ' selected' : ''}>Triple Net (NNN)</option>
            <option value="Gross"${d.lease_type === 'Gross' ? ' selected' : ''}>Gross</option>
            <option value="Modified Gross"${d.lease_type === 'Modified Gross' ? ' selected' : ''}>Modified Gross</option>
          </select>
        </div>
        <div class="field">
          <label>Excluded Categories (comma-separated)</label>
          <input type="text" value="${esc(d.excluded_categories || '')}"
            onfocus="isEditingField=true"
            onblur="handleFieldBlur(${i},'excluded_categories',this.value)"/>
        </div>
      </div>
    </div>`;
}

function renderTenantError(i, msg) {
  const body = document.getElementById(`tb-${i}`);
  body.innerHTML = `
    <div class="extracted">
      <div class="status-row err">
        <span class="status-dot err">${CROSS_SVG}</span>
        Extraction failed: ${esc(msg)}
        <button class="re-btn" onclick="resetTenant(${i})">Try again</button>
      </div>
    </div>`;
}

function resetTenant(i) {
  const prop = currentProperty();
  if (prop?.tenants) prop.tenants[i] = null;
  tenantData[i] = null;
  renderTenantUploadZone(i);
  checkSqftValidation();
}

// ─── Lease Tab Switching ──────────────────────────────────────────────────────

// ─── Property Workspace Tabs (Phase 22 — pure UI reorganization) ───────────
// Buckets the same pre-existing workspace sections (cardSetup, cardLeases,
// cardGL, cardInvoices, results, escrowSection, reportsSection, etc.) under
// tabbed navigation to cut scrolling. No business logic, data model, or
// extraction engine touched — this only toggles which already-rendered
// section is visible.
// 'estoppels' is intentionally omitted — the Estoppels feature is not built yet and its
// tab/pane are hidden so the app reads as production-ready. Re-add 'estoppels' here and
// un-hide #wsTabBtn-estoppels in index.html once the feature ships.
// Information architecture: the app is organized around real estate subjects,
// not software modules — Property (the building as a whole), Spaces (each
// suite), CAM (a workflow that references invoices), Reports (outputs only),
// Reserves (capital planning). 'documents' is retired from navigation: lease
// intake moved under Spaces, property documents live on Property.
// 'property' has no pane in index.html — property-os.js builds #wsPane-property
// at runtime (property-os.js:97). Grepping the HTML for it finds nothing, which
// is misleading; the tab works.
const WORKSPACE_TABS = ['overview', 'property', 'spaces', 'cam', 'reports', 'reserves'];
let _activeWorkspaceTab = 'overview';

function switchWorkspaceTab(tab) {
  if (WORKSPACE_TABS.indexOf(tab) === -1) return;
  _activeWorkspaceTab = tab;
  WORKSPACE_TABS.forEach(t => {
    const pane = document.getElementById('wsPane-' + t);
    const btn  = document.getElementById('wsTabBtn-' + t);
    if (pane) pane.style.display = (t === tab) ? 'block' : 'none';
    if (btn)  btn.classList.toggle('active', t === tab);
  });
}

// ─── Phase A (mobile nav): tab switching + KPI-tile shortcuts ────────────────
// Touch-only helpers layered on top of switchWorkspaceTab. Desktop is left
// byte-for-byte unchanged: every added scroll is gated behind a max-width:768px
// media check, and switchWorkspaceTab itself is untouched so all existing
// programmatic callers (Phase 29 deep-link routers, tests) behave exactly as before.

function _navIsTouchViewport() {
  try { return !!(window.matchMedia && window.matchMedia('(max-width: 768px)').matches); }
  catch (_) { return false; }
}

// Height to reserve at the top of the viewport so the sticky tab bar never
// covers what we scroll to. Zero on desktop (the bar isn't sticky there), so
// desktop scrolling lands flush at the top exactly as before.
function _workspaceStickyOffset() {
  var card = document.getElementById('propertyWorkspaceNavCard');
  if (!card) return 0;
  var pos = '';
  try { pos = getComputedStyle(card).position; } catch (_) {}
  if (pos !== 'sticky') return 0;
  return Math.round(card.getBoundingClientRect().height);
}

// Smooth-scroll so `el`'s top sits just below the sticky tab bar (top-aligned,
// never centered) — this is what keeps section headers from hiding behind the
// pinned bar. One scroll only, so there is no double-scroll/jump. `extraGap`
// spaces the header a touch below the bar.
function _scrollBelowStickyBar(el, extraGap) {
  if (!el) return;
  var offset = _workspaceStickyOffset();
  var y = window.pageYOffset + el.getBoundingClientRect().top - offset - (extraGap || 0);
  window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
}

// After a user taps a workspace tab, bring the newly shown pane up under the
// (sticky, on mobile) tab bar so the change is immediately visible instead of
// happening below the fold. No-op on desktop.
function _scrollWorkspaceIntoView(tab) {
  if (!_navIsTouchViewport()) return;
  var pane = document.getElementById('wsPane-' + (tab || _activeWorkspaceTab));
  if (!pane) return;
  // Defer a frame so the just-shown pane has laid out before we measure it.
  requestAnimationFrame(function () { _scrollBelowStickyBar(pane, 8); });
}

// Tab-bar button handler (item 2). The buttons call this instead of
// switchWorkspaceTab directly so the reveal-scroll is scoped to real user taps.
function switchWorkspaceTabFromNav(tab) {
  switchWorkspaceTab(tab);
  _scrollWorkspaceIntoView(tab);
}

// KPI tile → its section (item 1). Switch to the owning workspace tab (if the
// destination lives in a pane), then top-align + flash the target section so its
// header lands just under the (sticky, on mobile) tab bar — never centered, so
// the header is never hidden behind the bar. `anchors` is a comma-separated id
// list; the first that exists (preferring a visible one) wins, so callers can
// pass a fallback chain. `tab` may be empty for portfolio tiles that scroll in
// place. Uses its own single scroll (not _ccFlashEl, which centers) — one
// smooth scroll, no jump.
function _kpiTileNavigate(tab, anchors) {
  if (tab) { try { switchWorkspaceTab(tab); } catch (_) {} }
  var ids = typeof anchors === 'string' ? anchors.split(',') : (Array.isArray(anchors) ? anchors : []);
  requestAnimationFrame(function () {
    var el = null;
    for (var i = 0; i < ids.length; i++) {
      var id = (ids[i] || '').trim();
      if (!id) continue;
      var cand = document.getElementById(id);
      if (!cand) continue;
      if (cand.offsetParent !== null) { el = cand; break; } // prefer a visible target
      if (!el) el = cand;                                    // else first that exists
    }
    if (!el) return;
    _scrollBelowStickyBar(el, 12);
    el.classList.add('cc-target-flash');
    setTimeout(function () { el.classList.remove('cc-target-flash'); }, 2600);
  });
}

// One delegated listener pair drives every KPI tile (both the static portfolio
// bar and the re-rendered property header), so re-renders never need re-binding
// and keyboard access (Enter/Space) comes for free on the role="button" tiles.
var _kpiNavBound = false;
function _bindKpiNav() {
  if (_kpiNavBound) return;
  _kpiNavBound = true;
  function handle(e) {
    var tile = e.target && e.target.closest ? e.target.closest('[data-kpi-nav]') : null;
    if (!tile) return;
    if (e.type === 'keydown') {
      if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
      e.preventDefault();
    }
    _kpiTileNavigate(tile.getAttribute('data-kpi-tab') || '', tile.getAttribute('data-kpi-nav') || '');
  }
  document.addEventListener('click', handle);
  document.addEventListener('keydown', handle);
}

// Give the sticky tab bar a visible "pinned" state the moment it sticks, so the
// navigation reads as persistent on mobile instead of looking like an ordinary
// tab bar until you scroll. A zero-height sentinel sits just above the bar; the
// bar is pinned exactly when the sentinel has scrolled above the viewport top
// (its rect.top < 0). A passive, rAF-throttled scroll/resize handler drives it —
// correct even for instant jumps (scroll restoration, programmatic scrollTo)
// which an IntersectionObserver can miss, and cheap enough to be jank-free.
// Desktop is unaffected: the .ws-pinned styles live only inside the
// max-width:768px block, so toggling the class does nothing on desktop.
var _stickyPinBound = false;
function _initStickyTabPin() {
  if (_stickyPinBound) return;
  var card = document.getElementById('propertyWorkspaceNavCard');
  var sentinel = document.getElementById('wsStickySentinel');
  if (!card || !sentinel) return;
  _stickyPinBound = true;
  var ticking = false;
  function apply() {
    ticking = false;
    card.classList.toggle('ws-pinned', sentinel.getBoundingClientRect().top < 0);
  }
  function onScroll() {
    if (ticking) return;
    ticking = true;
    (window.requestAnimationFrame || window.setTimeout)(apply);
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll, { passive: true });
  apply();
}

if (typeof document !== 'undefined') {
  var _navInit = function () { _bindKpiNav(); _initStickyTabPin(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _navInit);
  else _navInit();
}

// ─── Option A: compact mobile header overflow menu ──────────────────────────
// The ⋮ button in the mobile context row opens a small menu of the actions that
// used to sit above the tabs (Explain This, Data Health, Command Center, Sign
// out). Ask AI stays a first-class button in the row. Desktop never shows the
// bar, so these are effectively mobile-only affordances.
function _closeWsMenu() {
  var menu = document.getElementById('wsMoreMenu');
  var btn = document.getElementById('wsMoreBtn');
  if (menu) menu.style.display = 'none';
  if (btn) btn.setAttribute('aria-expanded', 'false');
  document.removeEventListener('click', _onWsMenuOutside, true);
  document.removeEventListener('keydown', _onWsMenuKey, true);
}
function _onWsMenuOutside(e) {
  var wrap = e.target && e.target.closest ? e.target.closest('.wsm-more-wrap') : null;
  if (!wrap) _closeWsMenu();
}
function _onWsMenuKey(e) {
  if (e.key === 'Escape') { _closeWsMenu(); var b = document.getElementById('wsMoreBtn'); if (b) b.focus(); }
}
function toggleWsMenu(e) {
  if (e) e.stopPropagation();
  var menu = document.getElementById('wsMoreMenu');
  var btn = document.getElementById('wsMoreBtn');
  if (!menu) return;
  var isOpen = menu.style.display !== 'none';
  if (isOpen) { _closeWsMenu(); return; }
  menu.style.display = 'block';
  if (btn) btn.setAttribute('aria-expanded', 'true');
  // Defer binding so this same click doesn't immediately close the menu.
  setTimeout(function () {
    document.addEventListener('click', _onWsMenuOutside, true);
    document.addEventListener('keydown', _onWsMenuKey, true);
  }, 0);
}
function wsMenuAction(kind) {
  _closeWsMenu();
  try {
    if (kind === 'explain') explainCurrentScreen();
    else if (kind === 'health') openRecoveryModal();
    else if (kind === 'command') showCommandCenter();
    else if (kind === 'signout') signOut();
  } catch (err) { console.warn('[wsMenuAction]', kind, err && err.message); }
}

// Populate the compact mobile bar's property name (primary) and CAM year
// (secondary label). Called from the property render path and on CAM-year change.
function _syncMobilePropHeader(name) {
  var mn = document.getElementById('wsMobilePropName');
  if (mn && typeof name === 'string' && name) mn.textContent = name;
  var my = document.getElementById('wsMobileCamYear');
  if (my && typeof getCamYear === 'function') my.textContent = getCamYear() + ' CAM';
}

// ─── Property KPI Header (Phase 23) ─────────────────────────────────────────
// Pure aggregation of data already computed elsewhere (Selectors, the escrow
// engine, camReconciliation) — no new metrics engine, no new persisted fields.
function _fmtKpiMoney(n) {
  return '$' + Math.round(Number(n) || 0).toLocaleString();
}

function renderPropertyKpiHeader(property) {
  const slot = document.getElementById('propertyKpiHeader');
  if (!slot || !property) return;

  const tenants = (property.tenants || []).filter(t => t && t.tenant_name);
  const totalSqft = Number(property.totalSqft) || 0;
  const occSqft = tenants.reduce((s, t) => s + (parseFloat(t.leased_sqft) || 0), 0);
  const occupancyPct = totalSqft > 0 ? Math.round((occSqft / totalSqft) * 100) : null;

  const meta = Selectors.buildPropMeta(property);
  const readiness = Selectors.derivePropertyReadiness(property);

  const reserves = property.escrowReserves || [];
  const Engine = window.EscrowReserveEngine;
  const reserveBalanceTotal = Engine
    ? reserves.reduce((s, r) => s + (Engine.computeReserveBalance(r, property.drawRequests || []).availableBalance || 0), 0)
    : null;

  const camTotal = meta.total || 0;

  const lastEvent = Array.isArray(property.timeline) && property.timeline.length
    ? property.timeline[property.timeline.length - 1]
    : null;

  // `tab` = owning workspace pane to switch to; `anchor` = comma-separated id
  // fallback chain to scroll+flash on arrival (Phase A — every tile is a shortcut).
  const tiles = [
    { label: 'Occupancy', value: occupancyPct !== null ? occupancyPct + '%' : '—',
      sub: totalSqft ? `${occSqft.toLocaleString()} / ${totalSqft.toLocaleString()} sqft` : 'Set total sqft to enable',
      tab: 'spaces', anchor: 'cardLeases,spacesSection' },
    { label: 'Spaces', value: tenants.length, sub: tenants.length === 1 ? '1 tenant space' : `${tenants.length} tenant spaces`,
      tab: 'spaces', anchor: 'spacesSection' },
    { label: 'Active Reserves', value: reserves.length,
      sub: reserveBalanceTotal !== null ? `${_fmtKpiMoney(reserveBalanceTotal)} available` : 'No reserves yet',
      tab: 'reserves', anchor: 'escrowSection' },
    { label: 'Open Disputes', value: meta.openDisputes || 0, alert: (meta.openDisputes || 0) > 0,
      sub: (meta.openDisputes || 0) > 0 ? 'Needs attention' : 'None open',
      tab: 'cam', anchor: 'disputeSection' },
    { label: 'Lease Expirations', value: readiness.expiringCount || 0,
      warn: (readiness.expiringCount || 0) > 0, alert: (readiness.expiredCount || 0) > 0,
      sub: readiness.expiredCount ? `${readiness.expiredCount} already expired` : 'Next 12 months',
      tab: 'spaces', anchor: 'cardLeases,spacesSection' },
    { label: 'CAM Expenses', value: _fmtKpiMoney(camTotal), sub: camTotal ? 'Total pool, most recent run' : 'No CAM run yet',
      tab: 'cam', anchor: 'results,cardInvoices' },
  ];

  const tileHtml = tiles.map(t => `
    <div class="kpi-tile kpi-tile--nav${t.alert ? ' kpi-alert' : t.warn ? ' kpi-warn' : ''}"
      data-kpi-nav="${esc(t.anchor)}" data-kpi-tab="${esc(t.tab)}"
      role="button" tabindex="0" aria-label="${esc(t.label + ': ' + String(t.value) + '. ' + t.sub + '. Go to section.')}">
      <div class="kpi-tile-label">${esc(t.label)}</div>
      <div class="kpi-tile-value">${esc(String(t.value))}</div>
      <div class="kpi-tile-sub">${esc(t.sub)}</div>
    </div>`).join('');

  const lastActivityHtml = lastEvent
    ? `<div class="kpi-last-activity">&#x1F553; Last activity: ${esc(lastEvent.title || lastEvent.type)} &middot; ${esc(_fmtKpiTimestamp(lastEvent.timestamp))}</div>`
    : '';

  slot.innerHTML = `<div class="kpi-header-row">${tileHtml}</div>${lastActivityHtml}`;
}

// ── Property overview settlement panel ───────────────────────────────────────
// The headline XRPL surface on every property view: renders the full RLUSD
// settlement flow (Pay → RLUSD → Settle on XRPL → View Transaction) prominently,
// driven by the property's settlement record, with the wallet infra status as a
// small secondary line beneath. This is what makes "MainStreet settles on XRPL"
// obvious the moment a judge opens a property — not a buried, opt-in detail.
function renderPropertySettlementPanel() {
  const slot = document.getElementById('rlusdSettlementPanel');
  if (!slot) return;
  const prop = currentProperty() || {};
  slot.innerHTML =
    _buildSettlementFlowHtml(_getSettlementState(prop), { showPayButton: false }) +
    '<div id="rlusdInfraStatus" class="stl-infra-status"></div>';
  renderRlusdSettlementPanel('rlusdInfraStatus').catch(() => {});
}

// ── RLUSD Settlement Wallet infra status (small secondary line) ──────────────
// A neutral one-line status of the on-chain settlement rail (activating / funding /
// live), shown beneath the prominent settlement flow. Fire-and-forget.
async function renderRlusdSettlementPanel(containerId = 'rlusdSettlementPanel') {
  const slot = document.getElementById(containerId);
  if (!slot) return;
  try {
    const headers = await _authHeaders();
    if (!headers.Authorization) { slot.innerHTML = ''; return; }
    const resp = await fetch('/api/rlusd-settlement', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...headers },
      body: JSON.stringify({ action: 'status' }),
    });
    const status = await resp.json();
    slot.innerHTML = _buildRlusdStatusHtml(status);
  } catch (e) {
    console.warn('[rlusd] status check failed:', e?.message);
    slot.innerHTML = '';
  }
}

function _buildRlusdStatusHtml(status) {
  // Neutral "settlement rail" framing — this is a secondary infra line beneath the
  // prominent settlement flow, so it states where the rail is in activation rather
  // than reading as a broken/unavailable feature.
  const pending = (txt) => `<div class="rlusd-status-panel rlusd-status--pending">
      <span class="rlusd-status-dot"></span>
      <span>${txt}</span>
    </div>`;
  if (!status || !status.configured) {
    return pending('RLUSD settlement rail &middot; activating on XRPL mainnet');
  }
  if (!status.exists) {
    return pending('RLUSD settlement rail &middot; funding the XRPL mainnet wallet');
  }
  if (!status.trustLineEstablished) {
    return pending('RLUSD settlement rail &middot; finalizing the RLUSD trust line');
  }
  return `<div class="rlusd-status-panel rlusd-status--live">
    <span class="rlusd-status-dot"></span>
    <span>RLUSD settlement rail &middot; live on XRPL ${esc(status.network)} &middot; ${Number(status.rlusdBalance).toLocaleString()} RLUSD
      &middot; <a href="${esc((status.explorerBase || '').replace('/transactions/', '/accounts/'))}${esc(status.address)}" target="_blank" rel="noopener">view wallet</a></span>
  </div>`;
}

// ── XRPL RLUSD Settlement Flow (the demo's headline XRPL surface) ─────────────
// Renders the full tenant-payment → on-chain-settlement journey:
//   Pay Now → RLUSD Settlement → Settled on XRPL → View Transaction
// It is driven entirely by a property's settlement record and NEVER fabricates a
// transaction hash.
//
// RLUSD settlement is LIVE on XRPL Mainnet. The pending state below is a
// statement about THIS charge — no settlement transaction has been recorded
// against it yet — and never about the capability, which the copy used to
// describe as forthcoming ("going live on mainnet", "goes live once the
// settlement wallet is funded"). Those two facts are independent and must stay
// worded that way: an unsettled charge is not evidence of an unbuilt feature,
// and a live capability is not evidence that this charge was paid.
//
// The moment a real settlement is recorded on `property.settlement`
// (status:'settled' + txHash), every place that calls this lights up with the
// real explorer link — no further code changes.
const XRPL_MAINNET_TX_EXPLORER = 'https://livenet.xrpl.org/transactions/';

// Settlement is executed out-of-band (the app's endpoint is read-only and holds
// no wallet seed), so the app never "completes" one — it observes it. Record it
// on the property's history the first time a settled txHash is seen. Idempotent
// by txHash, so re-rendering or reloading cannot duplicate it.
function _recordSettlementIfNew(property) {
  try {
    const s = property && property.settlement;
    if (!s || !s.txHash) return;
    appendPropertyTimelineEventOnce(property, 'settlement:' + s.txHash, {
      type: 'settlement_completed', severity: 'success',
      title: 'Settlement completed' + (s.amountUsd != null ? ' — ' + fmt(s.amountUsd) : ''),
      description: 'Settled in RLUSD on the XRP Ledger' + (s.network ? ' (' + s.network + ')' : '') + '.',
      metadata: { txHash: s.txHash, network: s.network || 'mainnet', settledAt: s.settledAt || null },
      actor: 'System',
    });
  } catch (_e) { console.warn('[timeline] settlement_completed skipped:', _e && _e.message); }
}

function _getSettlementState(property) {
  const s = property && property.settlement;
  if (s && s.txHash) {
    return {
      status:       'settled',
      amountUsd:    s.amountUsd ?? null,
      txHash:       s.txHash,
      explorerLink: s.explorerLink || (XRPL_MAINNET_TX_EXPLORER + s.txHash),
      network:      s.network || 'mainnet',
      settledAt:    s.settledAt || null,
    };
  }
  return { status: 'pending', amountUsd: (s && s.amountUsd) ?? null, txHash: null, explorerLink: null, network: 'mainnet', settledAt: null };
}

// Builds the 4-step settlement flow. opts.showPayButton renders the tenant-facing
// "Pay Now" affordance; opts.amountUsd overrides the displayed amount.
function _buildSettlementFlowHtml(state, opts = {}) {
  const settled = state.status === 'settled';
  const amount  = opts.amountUsd ?? state.amountUsd;
  const amtTxt  = (amount != null && !isNaN(amount)) ? fmt(amount) : null;

  const step = (n, label, cls, inner) =>
    `<div class="stl-step ${cls}"><div class="stl-step-num">${inner || n}</div><div class="stl-step-label">${label}</div></div>`;
  const connector = (done) => `<div class="stl-connector ${done ? 'stl-connector--done' : ''}"></div>`;

  // Step 1 — payment entry point
  const payInner = settled ? '&#x2713;' : '';
  const step1 = opts.showPayButton && !settled
    ? `<div class="stl-step stl-step--active">
         <button class="stl-paynow-btn" onclick="payRentNow()">Pay Now${amtTxt ? ' · ' + amtTxt : ''}</button>
         <div class="stl-step-label">Tenant pays</div>
       </div>`
    : step(1, settled ? 'Payment received' : 'Tenant pays', settled ? 'stl-step--done' : 'stl-step--active', payInner);

  // Step 2 — settled in RLUSD (a USD stablecoin)
  const step2 = step(2, 'Settled in RLUSD', settled ? 'stl-step--done' : 'stl-step--pending', settled ? '&#x2713;' : '');

  // Step 3 — recorded on the XRP Ledger (mainnet)
  const step3 = step(3, 'On the XRP Ledger', settled ? 'stl-step--done' : 'stl-step--pending', settled ? '&#x2713;' : '');

  // Step 4 — public, verifiable receipt
  const step4 = settled
    ? `<div class="stl-step stl-step--done">
         <a class="stl-viewtx" href="${esc(state.explorerLink)}" target="_blank" rel="noopener">View Transaction &#x2197;</a>
         <div class="stl-step-label">Verified on-ledger</div>
       </div>`
    : step(4, 'Verify on-ledger', 'stl-step--pending', '');

  const head = settled
    ? `<div class="stl-head stl-head--live"><span class="stl-dot"></span>Payment settled &amp; verified on the XRP Ledger (RLUSD)${amtTxt ? ' · ' + amtTxt : ''}</div>`
    : `<div class="stl-head stl-head--pending"><span class="stl-dot"></span>Verifiable payment settlement on the XRP Ledger (RLUSD) — live on XRPL Mainnet</div>`;

  // opts.hideNote suppresses the explanatory paragraph for callers that already print
  // their own (e.g. the tenant statement section header) — avoids duplicated copy.
  const note = opts.hideNote
    ? ''
    : settled
      ? `<p class="stl-note">This payment was settled in RLUSD (a US-dollar stablecoin) on the XRP Ledger — a public, permanent receipt that you and your tenant can each verify independently.</p>`
      : `<p class="stl-note">When a tenant pays, MainStreet settles the matching amount as RLUSD — a US-dollar stablecoin — on the XRP Ledger, creating a public receipt both you and your tenant can verify independently. RLUSD settlement is live on XRPL Mainnet; this charge has no settlement transaction yet.</p>`;

  return `<div class="stl-flow ${settled ? 'stl-flow--live' : 'stl-flow--pending'}">
    ${head}
    <div class="stl-steps">
      ${step1}${connector(settled)}${step2}${connector(settled)}${step3}${connector(settled)}${step4}
    </div>
    ${note}
  </div>`;
}

// Honest "Pay Now" handler. There is no live payment processor or funded wallet yet,
// so this explains the flow rather than faking a payment — clicking it must never
// imply a real charge occurred.
function payRentNow() {
  showToast(
    'RLUSD settlement on XRPL mainnet is launching soon. Once live, paying here settles on-chain instantly and posts a verifiable transaction link.',
    { color: '#0E2A3A', textColor: '#bae6fd', duration: 6000 }
  );
}

function _fmtKpiTimestamp(ts) {
  try {
    const d = new Date(ts);
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  } catch { return ts; }
}

function switchLeaseTab(tab) {
  document.getElementById('lTabBulk').classList.toggle('active', tab === 'bulk');
  document.getElementById('lTabSingle').classList.toggle('active', tab === 'single');
  document.getElementById('lTabCenter').classList.toggle('active', tab === 'center');
  document.getElementById('leasePanelBulk').style.display   = tab === 'bulk'   ? 'block' : 'none';
  document.getElementById('leasePanelSingle').style.display = tab === 'single' ? 'block' : 'none';
  document.getElementById('leasePanelCenter').style.display = tab === 'center' ? 'block' : 'none';
  if (tab === 'center') {
    const prop = currentProperty();
    if (prop?.id) renderLeaseCenter(prop.id);
  }
}

