function showErr(body, section, msg) {
  body.innerHTML = `<div class="err-banner">${esc(msg)}</div>`;
  section.style.display = 'block';
  section.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ─── Previous Runs ────────────────────────────────────────────────────────────
function _fmtRunTs(ts) {
  return (ts instanceof Date ? ts : new Date(ts)).toLocaleString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}

function _prevRunDetailHtml(run) {
  return run.results.map(r => `
    <div class="result-card" style="padding:10px 14px;margin-bottom:6px;">
      <div class="r-name" style="font-size:0.88rem;">${esc(r.name)}</div>
      <div class="result-grid">
        ${stat('Allocated', fmt(r.allocatedAmount))}
        ${stat('Pro-Rata',  (r.proRata * 100).toFixed(2) + '%')}
        ${stat('Invoices',  r.eligibleCount + ' of ' + run.invoiceCount)}
      </div>
    </div>`).join('');
}

function renderPrevRunCard(run, camIdx) {
  return `
    <div class="prev-run-card">
      <div class="prev-run-meta">${_fmtRunTs(run.timestamp)}</div>
      <div class="prev-run-title">${run.camYear ? `${run.camYear} CAM — ` : ''}${esc(run.propName)}<span class="prev-run-latest-badge">Latest</span></div>
      <div class="prev-run-stats">
        <div class="prev-run-stat">Expenses: <strong>${fmt(run.totalExpenses)}</strong></div>
        <div class="prev-run-stat">Tenants: <strong>${run.tenantCount}</strong></div>
        <div class="prev-run-stat">Invoices: <strong>${run.invoiceCount}</strong></div>
      </div>
      <button class="prev-run-view-btn" onclick="togglePrevRunDetail(${camIdx})">&#x25BC; View Results</button>
      <div class="prev-run-detail" id="prev-run-detail-${camIdx}">
        ${_prevRunDetailHtml(run)}
      </div>
    </div>`;
}

function renderPrevRunHistItem(run, camIdx) {
  return `
    <div class="prev-run-hist-item">
      <div class="prev-run-hist-meta">${run.camYear ? `${run.camYear} CAM · ` : ''}${_fmtRunTs(run.timestamp)}</div>
      <div class="prev-run-hist-stats">
        <div class="prev-run-hist-stat">Expenses: <strong>${fmt(run.totalExpenses)}</strong></div>
        <div class="prev-run-hist-stat">Tenants: <strong>${run.tenantCount}</strong></div>
        <div class="prev-run-hist-stat">Invoices: <strong>${run.invoiceCount}</strong></div>
      </div>
      <button class="prev-run-view-btn" style="font-size:0.72rem;padding:4px 10px;" onclick="togglePrevRunDetail(${camIdx})">&#x25BC; View Results</button>
      <div class="prev-run-detail" id="prev-run-detail-${camIdx}">
        ${_prevRunDetailHtml(run)}
      </div>
    </div>`;
}

function renderPreviousRuns() {
  const sec  = document.getElementById('previousRunsSection');
  const list = document.getElementById('previousRunsList');
  if (camRuns.length < 2) { sec.style.display = 'none'; return; }
  sec.style.display = 'block';

  // Group historical runs (all but camRuns[0]) by property name, preserving DESC order
  const grouped = new Map();
  camRuns.slice(1).forEach((run, sliceIdx) => {
    const key = (run.propName || '').trim();
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push({ run, camIdx: sliceIdx + 1 });
  });

  // Sort groups by each property's most recent run, newest first
  const groups = [...grouped.entries()].sort(
    (a, b) => new Date(b[1][0].run.timestamp) - new Date(a[1][0].run.timestamp)
  );

  list.innerHTML = groups.map(([, entries], groupIdx) => {
    const primary = entries[0];
    const older   = entries.slice(1);
    return `
      <div class="prev-run-group">
        ${renderPrevRunCard(primary.run, primary.camIdx)}
        ${older.length ? `
          <button class="prev-run-toggle-btn" onclick="togglePrevRunGroup(${groupIdx}, this)">
            &#x25BC; Show previous runs (${older.length})
          </button>
          <div class="prev-run-hist-list" id="prhist-${groupIdx}">
            ${older.map(e => renderPrevRunHistItem(e.run, e.camIdx)).join('')}
          </div>` : ''}
      </div>`;
  }).join('');
}

function togglePrevRunGroup(groupIdx, btn) {
  const el = document.getElementById(`prhist-${groupIdx}`);
  if (!el) return;
  const open = el.classList.toggle('open');
  const count = el.querySelectorAll('.prev-run-hist-item').length;
  btn.innerHTML = open
    ? `&#x25B2; Hide previous runs (${count})`
    : `&#x25BC; Show previous runs (${count})`;
}

function togglePrevRunDetail(idx) {
  const el  = document.getElementById(`prev-run-detail-${idx}`);
  const btn = el ? el.previousElementSibling : null;
  if (!el) return;
  const open = el.style.display === 'block';
  el.style.display = open ? 'none' : 'block';
  if (btn) btn.innerHTML = open ? '&#x25BC; View Results' : '&#x25B2; Hide Results';
}

function fmt(n) {
  if (n === null || n === undefined || n === '' || isNaN(n)) return '—';
  return '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Reuses the portfolio-level empty-state visual pattern (.ptf-empty-state,
// defined in index.html) for in-tab empty states (Phase 24).
function _workspaceEmptyStateHtml(icon, title, desc) {
  return `<div class="ptf-empty-state">
    <div class="ptf-empty-icon">${icon}</div>
    <div class="ptf-empty-title">${esc(title)}</div>
    <div class="ptf-empty-desc">${esc(desc)}</div>
  </div>`;
}

function cleanHTML(text) {
  if (text === null || text === undefined) return '';
  const div = document.createElement('div');
  div.innerHTML = String(text);
  return div.textContent || div.innerText || '';
}

function esc(v) {
  if (v === null || v === undefined) return '';
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;'); // also escape single quotes: keeps apostrophe names (O'Brien) from breaking single-quoted onclick handlers, and closes the injection gap
}

// Convert a subset of markdown to safe HTML (HTML-escapes first, then renders).
function renderMarkdown(rawText) {
  let s = String(rawText || '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  s = s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
  s = s.replace(/^#{1,3} +(.+)$/gm,'<span class="expl-hd">$1</span>');
  const lines = s.split('\n');
  const segs = [];
  let listItems = [];
  for (const line of lines) {
    const m = line.match(/^[-*] +(.+)$/);
    if (m) { listItems.push(`<li>${m[1]}</li>`); }
    else {
      if (listItems.length) { segs.push({ ul: true, html: `<ul class="expl-list">${listItems.join('')}</ul>` }); listItems = []; }
      segs.push({ ul: false, html: line });
    }
  }
  if (listItems.length) segs.push({ ul: true, html: `<ul class="expl-list">${listItems.join('')}</ul>` });
  let out = '';
  for (let i = 0; i < segs.length; i++) {
    const seg = segs[i];
    if (seg.ul) { out += seg.html; }
    else { if (i > 0 && !segs[i-1].ul) out += '<br>'; out += seg.html; }
  }
  return out;
}

function stat(label, value) {
  return `<div class="result-stat">
    <div class="stat-label">${label}</div>
    <div class="stat-value">${value}</div>
  </div>`;
}

// ─── Explain Charge Panel ─────────────────────────────────────────────────────

function openExplainPanel(tenantName) {
  console.log('[openExplainPanel] ENTER', {
    tenantName,
    lastResultsLen:  lastResults.length,
    lastTenantsLen:  lastTenants.length,
    tenantDataLen:   tenantData.filter(Boolean).length,
    lastTenantsNames: lastTenants.map(x => x.name),
    lastResultsNames: lastResults.map(x => x.name),
  });

  const r = lastResults.find(x => x.name === tenantName);
  const t = lastTenants.find(x => x.name === tenantName);

  if (!r || !t) {
    console.warn('[openExplainPanel] GUARD 1 FAILED — missing r or t', {
      tenantName,
      rFound:         !!r,
      tFound:         !!t,
      lastResultsLen: lastResults.length,
      lastTenantsLen: lastTenants.length,
      lastTenantsNames: lastTenants.map(x => x.name),
      lastResultsNames: lastResults.map(x => x.name),
    });
    return;
  }

  console.log('[openExplainPanel] GUARD 1 passed', { tenantName, r, t });

  const td = tenantData.find(x => x && x.tenant_name === tenantName);
  if (!t.leasedSqft || !t.totalSqft || !td?.lease_type) {
    console.warn('[openExplainPanel] GUARD 2 — missing lease data (showing error panel)', {
      tenantName,
      leasedSqft:  t.leasedSqft,
      totalSqft:   t.totalSqft,
      tdFound:     !!td,
      leaseType:   td?.lease_type,
    });
    const panel = document.getElementById('explainPanel');
    const body  = document.getElementById('explainPanelBody');
    if (body) body.innerHTML = `<div class="rc-flags"><div class="rc-flags-title">&#x26A0;&#xFE0F; Cannot Generate Explanation</div><div class="rc-flag-item">Cannot generate explanation — missing required lease data (leased sqft, property sqft, or lease type).</div></div>`;
    if (panel) { panel.classList.add('open'); document.body.style.overflow = 'hidden'; }
    return;
  }

  console.log('[openExplainPanel] GUARD 2 passed — proceeding to render', { tenantName, leasedSqft: t.leasedSqft, totalSqft: t.totalSqft, leaseType: td.lease_type });

  const leasedSqft  = parseFloat(t.leasedSqft) || 0;
  const totalSqft   = parseFloat(t.totalSqft)  || 0;
  const totalCamAll = lastInvoicesFull.reduce((s, inv) => s + (parseFloat(inv.amount) || 0), 0);

  // ONE authoritative source: the invoices runFullReconciliation actually
  // allocated, carrying the share it computed. Re-deriving from
  // lastInvoicesFull disagreed with the reconciliation three ways — it skipped
  // the camEligible filter (PW-3, script.js:9791), pro-rated directly-matched
  // invoices that are charged in full, and re-rounded from raw amounts.
  const eligible = r.includedInvoices || [];

  // Section 1 — Summary
  const adjHtml = r.capApplied
    ? `<div class="ep-adj">&#x26A0; Cap applied — your share reduced by ${fmt(r.capAdjustment)}</div>`
    : '';
  // F-02: list only what was actually filtered out of the pool, and say so when
  // the lease excludes more than the engine could apply. Printing the raw AI
  // phrases told the tenant seven categories were excluded when one was; simply
  // dropping the other six would replace one untruth with another.
  const _exUnapplied = (t.exclusionsNotApplied || []);
  const exclHtml = (t.excludedCategories.length || _exUnapplied.length)
    ? `<div class="ep-excl">${t.excludedCategories.length
          ? `Excluded from your CAM: ${esc(t.excludedCategories.join(', '))}`
          : 'No exclusions were applied to your CAM.'}${_exUnapplied.length
          ? `<br><span class="ep-excl-warn">&#x26A0; ${_exUnapplied.length} further exclusion${_exUnapplied.length !== 1 ? 's' : ''} in this lease could not be applied automatically and ${_exUnapplied.length !== 1 ? 'are' : 'is'} under review: ${esc(_exUnapplied.map(u => u.raw).join(', '))}</span>`
          : ''}</div>`
    : '';
  const narrativeHtml = (() => {
    if (!window.ReconciliationExplainer) return '';
    const narr = window.ReconciliationExplainer.buildReconciliationSummaryNarrative(r, td);
    return narr ? `<div class="ep-narrative">${esc(narr)}</div>` : '';
  })();

  const s1 = `
    <div class="ep-section-title">Summary</div>
    ${narrativeHtml}
    <div class="ep-stat-grid">
      <div class="ep-stat">
        <div class="ep-stat-label">Your Sqft</div>
        <div class="ep-stat-value">${leasedSqft.toLocaleString()}</div>
      </div>
      <div class="ep-stat">
        <div class="ep-stat-label">Building Sqft</div>
        <div class="ep-stat-value">${totalSqft.toLocaleString()}</div>
      </div>
      <div class="ep-stat">
        <div class="ep-stat-label">Your % Share</div>
        <div class="ep-stat-value">${(r.proRata * 100).toFixed(2)}%</div>
      </div>
      <div class="ep-stat">
        <div class="ep-stat-label">Total CAM Pool</div>
        <div class="ep-stat-value">${fmt(totalCamAll)}</div>
      </div>
      <div class="ep-stat">
        <div class="ep-stat-label">Eligible Expenses</div>
        <div class="ep-stat-value">${fmt(eligible.reduce((s,i)=>s+(parseFloat(i.amount)||0),0))}</div>
      </div>
      <div class="ep-stat">
        <div class="ep-stat-label">Your CAM Charge</div>
        <div class="ep-stat-value highlight">${fmt(r.allocatedAmount)}</div>
      </div>
    </div>
    ${adjHtml}${exclHtml}`;

  // Section 2 — Category Breakdown
  const catMap = {};
  eligible.forEach(inv => {
    const cat = (inv.category || 'other').toLowerCase();
    if (!catMap[cat]) catMap[cat] = { total: 0, count: 0, share: 0, invs: [] };
    const amt = parseFloat(inv.amount) || 0;
    catMap[cat].total += amt;
    catMap[cat].share += parseFloat(inv.share) || 0;   // engine's share, not amount * proRata
    catMap[cat].count++;
    catMap[cat].invs.push(inv);
  });

  const s2rows = Object.entries(catMap)
    .sort((a, b) => b[1].total - a[1].total)
    .map(([cat, data]) => {
      const yourShare = parseFloat(data.share.toFixed(2));   // sums the engine's per-invoice shares
      return `
        <div class="ep-cat-row" id="epcat-${esc(cat.replace(/\s+/g,'-'))}"
          onclick="epToggleDrill('${esc(cat)}','${esc(tenantName)}')">
          <div>
            <div class="ep-cat-name">${esc(cat)}</div>
            <div class="ep-cat-meta">${data.count} invoice${data.count !== 1 ? 's' : ''}</div>
          </div>
          <div style="display:flex;align-items:center;">
            <div class="ep-cat-right">
              <div class="ep-cat-total">${fmt(data.total)}</div>
              <div class="ep-cat-share">Your CAM charge: ${fmt(yourShare)}</div>
            </div>
            <span class="ep-cat-chevron" id="epchev-${esc(cat.replace(/\s+/g,'-'))}">&#x25BC;</span>
          </div>
        </div>
        <div id="epdrill-${esc(cat.replace(/\s+/g,'-'))}" style="display:none;"></div>`;
    }).join('');

  const s2 = `<div class="ep-section-title">Category Breakdown — click to drill down</div>${s2rows}`;

  // Populate and open panel
  document.getElementById('explainPanelTitle').textContent    = tenantName;
  document.getElementById('explainPanelSubtitle').textContent = `CAM Charge Breakdown — ${lastPropName}`;
  document.getElementById('explainPanelBody').innerHTML = s1 + s2;
  document.getElementById('explainPanel').classList.add('open');
  document.body.style.overflow = 'hidden';
  console.log('[openExplainPanel] PANEL OPENED', { tenantName, panelClasses: document.getElementById('explainPanel').className });
}

function epToggleDrill(category, tenantName) {
  console.log('[epToggleDrill] ENTER', { category, tenantName, lastTenantsLen: lastTenants.length, lastResultsLen: lastResults.length });

  const t = lastTenants.find(x => x.name === tenantName);
  const r = lastResults.find(x => x.name === tenantName);

  if (!t || !r) {
    console.warn('[epToggleDrill] GUARD 1 FAILED — missing t or r', {
      category, tenantName,
      tFound: !!t, rFound: !!r,
      lastTenantsLen: lastTenants.length,
      lastResultsLen: lastResults.length,
    });
    return;
  }

  const slug    = category.replace(/\s+/g, '-');
  const drillEl = document.getElementById(`epdrill-${slug}`);
  const chevEl  = document.getElementById(`epchev-${slug}`);
  const rowEl   = document.getElementById(`epcat-${slug}`);

  if (!drillEl) {
    console.warn('[epToggleDrill] GUARD 2 FAILED — drillEl not found', { slug, id: `epdrill-${slug}` });
    return;
  }

  const open = drillEl.style.display === 'block';
  drillEl.style.display = open ? 'none' : 'block';
  if (chevEl) chevEl.innerHTML = open ? '&#x25BC;' : '&#x25B2;';
  if (rowEl)  rowEl.classList.toggle('active', !open);
  if (open)   return;

  // Build drill-down invoice list for this category
  const invs = (r.includedInvoices || []).filter(inv =>
    (inv.category || 'other').toLowerCase() === category.toLowerCase()
  );

  console.log('[epToggleDrill] building drill for', { category, tenantName, invCount: invs.length, sampleInv: invs[0], invoiceDataLen: invoiceData.length });

  drillEl.innerHTML = `<div class="ep-drill">${
    invs.map(inv => {
      const vendorKey = (inv.vendor || inv.vendorName || '').toLowerCase();
      const stored = invoiceData.find(d =>
        d.vendorName && d.vendorName.toLowerCase() === vendorKey
      );
      console.log('[epToggleDrill] inv match', { vendor: inv.vendor, vendorName: inv.vendorName, vendorKey, storedFound: !!stored, fileUrl: stored?.fileUrl ? 'PRESENT' : 'MISSING' });
      const viewBtn = stored && stored.fileUrl
        ? `<button class="ep-view-inv-btn" onclick="viewInvFile(${invoiceData.indexOf(stored)})">&#x1F4C4; View Source Invoice</button>`
        : '';
      return `
      <div class="ep-inv-row">
        <div>
          <div class="ep-inv-vendor">${esc(inv.vendor || inv.vendorName || '—')}</div>
          <div class="ep-inv-date">${esc(inv.invoiceDate || '—')}</div>
          ${viewBtn}
        </div>
        <div class="ep-inv-amount">${fmt(parseFloat(inv.amount) || 0)}</div>
      </div>`;
    }).join('')
  }</div>`;
}

function closeExplainPanel() {
  document.getElementById('explainPanel').classList.remove('open');
  document.body.style.overflow = '';
  document.body.classList.remove('modal-open');
}

// ─── Reconciliation Calculation Engine Helpers ────────────────────────────────

// Derives calculation state from a ReconciliationResult + live tenant record.
// Returns { state, label, cls } used for calc state badges in panels and reports.
// ── Reconciliation engine shims ───────────────────────────────────────────────
// Business logic lives in reconciliation-engine.js (pure, no global deps).
// evalDate is computed here using getCamYear() so the engine stays pure.
function _deriveCalcState(result, liveT) {
  return ReconciliationEngine.deriveCalcState(result, liveT);
}
function _detectReconciliationIssues(results, property, evaluationDate) {
  return ReconciliationEngine.detectReconciliationIssues(results, property, evaluationDate || `${getCamYear()}-12-31`);
}

function _resultCardAnchorId(name) {
  return 'result-card-' + String(name || '').replace(/[^a-zA-Z0-9]/g, '-');
}

// The breakdown behind whichever variance banner is currently on screen, kept so
// the panel opens from the same numbers the banner was rendered from rather than
// re-deriving against globals that may since have moved.
let _lastVarianceBreakdown = null;
// The invoice records the engine last ran on, captured for the same reason.
// `_lastEngineInvoices` is everything behind the pool total; the second is the
// subset that survived the CAM-year filter, so the panel can tell an out-of-year
// invoice apart from one that simply reached no tenant.
let _lastEngineInvoices     = [];
let _lastReconciledInvoices = [];

// One sentence naming what the gap is mostly made of, for the banner. Reads off
// the buckets; asserts nothing the panel would not also show.
function _varianceCauseSentence(bk) {
  if (!bk) return '';
  const top = (bk.lines || []).filter(l => l.key !== 'residual')[0];
  if (!top) return 'the panel below shows how it is made up.';
  const share = bk.difference ? Math.round((Math.abs(top.amount) / Math.abs(bk.difference)) * 100) : 0;
  const most  = share >= 60 ? 'most of it' : share >= 30 ? 'the largest part of it' : 'the largest single part of it';
  const lead  = {
    out_of_year:  `${most} is ${fmt(top.amount)} of invoices dated outside the CAM year`,
    not_eligible: `${most} is ${fmt(top.amount)} of invoices marked not CAM-eligible`,
    uncovered:    `${most} is ${fmt(top.amount)} sitting outside the covered share`,
    claim:        `${most} is ${fmt(top.amount)} that no lease claimed — excluded categories, or invoices matched to no tenant`,
    caps:         `${most} is ${fmt(top.amount)} withheld by CAM caps`,
  }[top.key];
  return lead ? lead + '.' : 'the panel below shows how it is made up.';
}

/**
 * Explain the pool-vs-billed difference. NAVIGATION AND EXPLANATION ONLY.
 *
 * Nothing here changes a figure, a finding, an eligibility flag or a billing
 * gate. It re-adds what the run already produced into named buckets and lists
 * the invoices behind them, which is what the banner was asserting without
 * evidence. If a manager decides an invoice is wrongly marked, the place that
 * changes is the invoice register — this panel points there and stops.
 */
function openVarianceDetails() {
  const VB = window.VarianceBreakdown;
  const bk = _lastVarianceBreakdown || (VB && lastResults && lastResults.length
    ? VB.derive({
        results:    lastResults,
        invoices:   _lastEngineInvoices || [],
        reconciled: _lastReconciledInvoices && _lastReconciledInvoices.length
          ? _lastReconciledInvoices : undefined,
        pool:     lastTotal || 0,
        billed:   lastResults.reduce((s, r) => s + (Number(r.totalAllocated) || 0), 0),
      })
    : null);
  if (!bk) {
    showToast('Run a reconciliation first — there is no allocation to explain yet.',
      { color: '#92400e', textColor: '#fef3c7' });
    return;
  }

  const lineRows = bk.lines.map(l => `<tr${l.key === 'residual' ? ' style="background:rgba(239,68,68,0.06)"' : ''}>
    <td>${esc(l.label)}</td>
    <td style="text-align:right;white-space:nowrap"><strong>${fmt(l.amount)}</strong></td>
    <td style="white-space:normal;color:#94a3b8">${esc(l.detail)}</td>
  </tr>`).join('');

  const RL = (VB && VB.REASON_LABEL) || {};
  // Every invoice, sorted by how much of it never reached a tenant — the reader
  // opened this panel to find the difference, so the rows that make it up come
  // first. Fully-allocated invoices stay in the table rather than being filtered
  // out, because "13 invoices, 5 of them billed" is the fact that answers the
  // question, and it cannot be read off a table that only lists 8.
  const invRows = bk.invoices.slice()
    .sort((a, b) => b.unallocated - a.unallocated)
    .map(r => `<tr${r.unallocated > 0.005 ? '' : ' style="color:#64748b"'}>
      <td>${esc(r.vendor)}</td>
      <td style="white-space:normal;color:#94a3b8">${esc(r.category)}</td>
      <td style="text-align:right;white-space:nowrap">${fmt(r.amount)}</td>
      <td style="text-align:right;white-space:nowrap">${fmt(r.allocated)}</td>
      <td style="text-align:right;white-space:nowrap">${r.unallocated > 0.005 ? `<strong>${fmt(r.unallocated)}</strong>` : '—'}</td>
      <td style="white-space:normal;color:#94a3b8">${esc(RL[r.reason] || r.reason)}</td>
    </tr>`).join('');

  const step = VB ? VB.nextStep(bk) : null;
  // Where each next step actually goes. Navigation only — none of these is a
  // state change, and none of the destinations is invented for this panel: the
  // invoice register on the Property tab and the lease cards on Spaces are where
  // a manager already edits eligibility, exclusions and caps.
  const stepBtn = step ? {
    out_of_year:  `<button class="rpt-action-btn" onclick="openVarianceFix('out_of_year')">Open the invoice register</button>`,
    not_eligible: `<button class="rpt-action-btn" onclick="openVarianceFix('not_eligible')">Open the invoice register</button>`,
    uncovered:    `<button class="rpt-action-btn" onclick="openVarianceFix('uncovered')">Open Spaces to upload the remaining leases</button>`,
    claim:        `<button class="rpt-action-btn" onclick="openVarianceFix('claim')">Open Spaces to review exclusion schedules</button>`,
    caps:         `<button class="rpt-action-btn" onclick="openVarianceFix('caps')">Open Spaces to review the CAM caps</button>`,
    residual:     `<button class="rpt-action-btn" onclick="openVarianceFix('residual')">Open the invoice register</button>`,
  }[step.key] || '' : '';

  openReport('Variance details', `
    <div class="rpt-section-title">Where the difference went</div>
    <table class="rpt-table">
      <tbody>
        <tr><td>Expense pool</td><td style="text-align:right;white-space:nowrap"><strong>${fmt(bk.pool)}</strong></td></tr>
        <tr><td>Allocated to tenants</td><td style="text-align:right;white-space:nowrap"><strong>${fmt(bk.billed)}</strong></td></tr>
        <tr><td>Difference</td><td style="text-align:right;white-space:nowrap"><strong>${fmt(bk.difference)}</strong></td></tr>
        <tr><td>Share of the pool that reached a tenant</td><td style="text-align:right;white-space:nowrap"><strong>${bk.billedPct == null ? '—' : bk.billedPct.toFixed(1) + '%'}</strong></td></tr>
        <tr><td>Property covered by loaded leases</td><td style="text-align:right;white-space:nowrap"><strong>${bk.proRataSum.toFixed(1)}%</strong></td></tr>
      </tbody>
    </table>
    <p class="rpt-helper-text">
      ${bk.unbilledCount > 0
        ? `<strong>${bk.unbilledCount} of the ${bk.invoiceCount} invoice${bk.invoiceCount !== 1 ? 's' : ''} in this pool contributed nothing to any tenant allocation</strong>
           (${fmt(bk.unbilledTotal)}). The rest of the difference comes from invoices that were allocated in part.`
        : `Every invoice in this pool reached at least one tenant; the difference is made up of partial allocations.`}
      ${bk.explained
        ? ' Every dollar of the difference is accounted for below, so nothing here indicates the reconciliation is wrong.'
        : ` <strong>${fmt(Math.abs(bk.residual))} of the difference is not accounted for below</strong> — that part is worth checking against the invoice register.`}
    </p>
    <div class="rpt-section-title">Made up of</div>
    <table class="rpt-table">
      <thead><tr><th>Reason</th><th style="text-align:right">Amount</th><th>What it means</th></tr></thead>
      <tbody>${lineRows}</tbody>
    </table>
    <div class="rpt-section-title">Invoice by invoice</div>
    <table class="rpt-table">
      <thead><tr><th>Vendor</th><th>Category</th><th style="text-align:right">Invoice</th><th style="text-align:right">Allocated</th><th style="text-align:right">Not allocated</th><th>Why</th></tr></thead>
      <tbody>${invRows}</tbody>
    </table>
    <div class="rpt-scope-note">
      No tenant charge changes because of anything on this page. Each tenant is billed its own
      pro-rata share of the expenses its lease allows; the difference above is pool the
      reconciliation did not pass through to anyone.
    </div>
    ${step ? `<div class="rpt-section-title">Next step</div>
    <p class="rpt-helper-text">${esc(step.cta)}.</p>
    ${stepBtn}` : ''}`);
}

// The destinations behind the Variance details next step. Same navigate-and-
// flash shape as openReviewItemFix: close the report, switch to the pane that
// holds the control, put the control on screen. It changes nothing.
const _VARIANCE_FIX_TARGET = {
  out_of_year:  { tab: 'property', sel: '.pos-reg' },
  not_eligible: { tab: 'property', sel: '.pos-reg' },
  residual:     { tab: 'property', sel: '.pos-reg' },
  uncovered:    { tab: 'spaces',   sel: null },
  claim:        { tab: 'spaces',   sel: null },
  caps:         { tab: 'spaces',   sel: null },
};

function openVarianceFix(key) {
  const target = _VARIANCE_FIX_TARGET[key];
  if (!target) return;
  try { closeReport(); } catch (_) {}
  if (window.TenantSpace && typeof window.TenantSpace.closeSpace === 'function') {
    try { window.TenantSpace.closeSpace(); } catch (_) {}
  }
  if (typeof switchWorkspaceTab === 'function') switchWorkspaceTab(target.tab);
  if (target.tab === 'spaces') {
    if (typeof switchLeaseTab === 'function') switchLeaseTab('bulk');
    if (typeof renderBulkResults === 'function') renderBulkResults();
  }
  // The pane is populated on switch, so the target does not exist until after it.
  setTimeout(() => {
    const tgt = document.querySelector(target.sel || '#wsPane-' + target.tab)
             || document.getElementById('wsPane-' + target.tab);
    if (!tgt) return;
    tgt.scrollIntoView({ behavior: 'smooth', block: 'start' });
    tgt.classList.add('lease-blocker-flash');
    setTimeout(() => tgt.classList.remove('lease-blocker-flash'), 2200);
  }, 60);
}

// Builds the dominant "Needs Review" rollup shown at the very top of CAM
// results, above the Reconciliation Summary — so problems surface before
// the landlord has to scroll past financial details to find them.
function _buildNeedsReviewRollupHtml(results) {
  const flagged = (results || []).filter(r => (r.ambiguityFlags || []).length > 0);
  if (!flagged.length) return '';
  const totalFlags = flagged.reduce((s, r) => s + r.ambiguityFlags.length, 0);
  const items = flagged.map(r => {
    const anchorId = _resultCardAnchorId(r.name);
    const msgs = r.ambiguityFlags.map(f => esc(f.message)).join(' &middot; ');
    return `<button class="nrr-item" onclick="document.getElementById('${anchorId}')?.scrollIntoView({behavior:'smooth',block:'center'})">
      <span class="nrr-item-tenant">${esc(r.name)}</span>
      <span class="nrr-item-count">${r.ambiguityFlags.length}</span>
      <span class="nrr-item-msg">${msgs}</span>
    </button>`;
  }).join('');
  return `<div class="needs-review-rollup">
    <div class="nrr-head">
      <span class="nrr-icon">&#x26A0;&#xFE0F;</span>
      <span class="nrr-title">Needs Review</span>
      <span class="nrr-count-badge">${flagged.length} tenant${flagged.length !== 1 ? 's' : ''} &middot; ${totalFlags} issue${totalFlags !== 1 ? 's' : ''}</span>
    </div>
    <div class="nrr-body">${items}</div>
  </div>`;
}

// Builds the in-app Reconciliation Summary HTML panel displayed above result cards.
//
// `engineInvoices` is the Invoice[] the reconciliation engine was actually
// handed. It is a fourth, optional argument rather than a replacement for
// `invoices` because `invoices` is what totalPool is struck from and that must
// not move — but it is a stripped shape that dropped `camEligible` and `id`, so
// it cannot say which invoices were held out of the allocation. The variance
// panel needs both: the pool the screen shows, and the records behind it.
function _buildReconciliationSummaryHtml(results, invoices, propName, engineInvoices, reconciledInvoices) {
  if (!results || !results.length) return '';

  const totalPool   = invoices.reduce((s, inv) => s + (parseFloat(inv.amount) || 0), 0);
  // The KPI beside this one is LABELLED "CAM Pool" and showed totalPool — every
  // invoice loaded, including ones the manager had removed from CAM. Two numbers
  // now, each matching its own label: the variance banner keeps the gross figure
  // (its words say "expense pool"), and the KPI shows what tenants can actually
  // be billed from.
  const camPoolTotal = window.CamPool.total(invoices);
  const totalBilled = results.reduce((s, r) => s + r.totalAllocated, 0);
  const proRataSum  = results.reduce((s, r) => s + (r.proRataPercent || 0), 0);
  const proRataGap  = parseFloat((100 - proRataSum).toFixed(2));
  const capsCount   = results.filter(r => r.capApplied).length;
  const capTotal    = results.filter(r => r.capApplied).reduce((s, r) => s + (r.capAdjustment || 0), 0);
  const flaggedCnt  = results.filter(r => (r.ambiguityFlags || []).length > 0).length;

  // THE CANONICAL BILLING STATE, read from the one model that decides it.
  //
  // AuditExposure.billingReadiness is what gates every tenant statement. The
  // reconciliation screen showed none of it, so "Total Billed $25,090.78" sat at
  // the top of a run on which no statement could be issued — the same word used
  // as a completed fact that was fixed on the statement itself. Reading the same
  // model here keeps one source of truth: this screen reports the state, it does
  // not compute it.
  // The exposure is kept, not just the verdict: I-12 asks it the same question
  // once per tenant, through the one derivation the statement path uses.
  const _exposure = (() => {
    try {
      const AXs = window.AuditExposure;
      if (!AXs || !results.length) return null;
      return AXs.deriveExposure(buildAuditSummary(), totalPool || 0);
    } catch (_) { return null; }
  })();
  const _billing = (() => {
    try {
      const AXs = window.AuditExposure;
      if (!AXs || !_exposure) return null;
      return AXs.billingReadiness(_exposure);
    } catch (_) { return null; }
  })();
  const _billable = !!(_billing && _billing.canBill);
  // Per-tenant billing state, derived once and used by the rows and the roster
  // line above them so the two can never report different counts.
  const _tenantBilling = {};
  results.forEach(r => { _tenantBilling[r.name] = _tenantBillingState(r.name, _exposure); });
  const _billableNames = results.map(r => r.name).filter(n => _tenantBilling[n].state === 'billable');

  const issues   = _detectReconciliationIssues(results, currentProperty());
  _lastReconIssues = issues; // capture for openDisputeFromFlag()
  const reds     = issues.filter(f => f.severity === 'red');
  const yellows  = issues.filter(f => f.severity === 'yellow');
  const panelCls = reds.length > 0 ? 'rcs-panel--alert' : yellows.length > 0 ? 'rcs-panel--warn' : 'rcs-panel--ok';

  // Allocation integrity badge (Phase 5H) — validate the allocation set produced
  // by this run against the invariant engine. Pure derivation, no side effects.
  const _allocSet = results.map(r => ({
    tenantId:   r.tenantId || r.name,
    tenantName: r.name,
    percent:    r.proRataPercent ?? (r.proRata != null ? r.proRata * 100 : 0),
    amount:     r.totalAllocated ?? r.allocatedAmount ?? 0,
  }));
  const _integrity = AllocationIntegrity.buildIntegritySummary(_allocSet, {
    method: 'leased square footage',
    excludedCount: 0,
  });
  const _balBadgeCls = _integrity.criticalIssueCount > 0 ? 'rcs-balance-badge--critical'
    : !_integrity.balanced                               ? 'rcs-balance-badge--warn'
    :                                                      'rcs-balance-badge--ok';
  const _balBadgeTxt = _integrity.criticalIssueCount > 0 ? '✕ Critical Allocation Error'
    : !_integrity.balanced                               ? '⚠ Needs Review'
    :                                                      '✓ Balanced';
  const _balBadgeHtml = `<span class="rcs-balance-badge ${_balBadgeCls}" title="${esc(_integrity.explainability)}">${_balBadgeTxt}</span>`;

  const proCls   = Math.abs(proRataGap) > 5 ? 'rcs-kpi--alert' : Math.abs(proRataGap) > 2 ? 'rcs-kpi--warn' : '';
  const capsCls  = capsCount > 0 ? 'rcs-kpi--warn' : '';
  const flagCls  = flaggedCnt > 0 ? 'rcs-kpi--warn' : '';

  // Overall confidence rollup — surfaced prominently so a skeptical reviewer
  // sees "how sure are we" before drilling into per-field detail.
  const _confResults  = results.filter(r => r.averageConfidence > 0);
  const avgConfidence = _confResults.length
    ? Math.round(_confResults.reduce((s, r) => s + r.averageConfidence, 0) / _confResults.length)
    : null;
  const reviewFieldCount = results.reduce((s, r) => s + (r.ambiguityFlags || []).length, 0);
  const confCls = avgConfidence === null ? ''
    : avgConfidence < 70 ? 'rcs-confidence-badge--warn'
    : avgConfidence < 90 ? 'rcs-confidence-badge--ok'
    : 'rcs-confidence-badge--high';
  const confidenceBadgeHtml = avgConfidence !== null
    ? `<span class="rcs-confidence-badge ${confCls}" title="Average extraction confidence across all tenants in this run">
        ${avgConfidence}% confidence${reviewFieldCount > 0 ? ` &middot; ${reviewFieldCount} item${reviewFieldCount !== 1 ? 's' : ''} need review` : ''}
      </span>`
    : '';

  // A finding that is not disputable gets no dispute button. The property
  // coverage gap has no counterparty — offering "Open Dispute" there raised an
  // allocation_mismatch dispute against a tenant whose allocation is correct.
  // It is also labelled so it reads as incomplete coverage, not an exception.
  const issueHtml = issues.length > 0 ? `<div class="rcs-issues">${
    issues.map((f, fi) => `<div class="rcs-issue rcs-issue--${f.severity}${f.kind === 'coverage' ? ' rcs-issue--coverage' : ''}">
      <span class="rcs-issue-main">${f.kind === 'coverage' ? '&#x1F4D0;' : f.severity === 'red' ? '&#x26D4;' : '&#x26A0;'} ${f.kind === 'coverage' ? '<span class="rcs-issue-kind">Property coverage</span> ' : ''}${esc(f.title)}</span>
      ${f.disputable === false ? '' : `<button class="rcs-dispute-btn" onclick="openDisputeFromFlag(${fi})">Open Dispute</button>`}
    </div>`).join('')
  }</div>` : '';

  // totalBilled and totalPool are structurally different quantities and are only
  // expected to agree when the property is fully covered by loaded leases.
  // totalPool is the gross invoice total; totalBilled is what the engine
  // allocated AFTER four legitimate reductions: property coverage below 100%,
  // invoices marked not CAM-eligible (PW-3 — note the summary's invoice list is
  // built without the camEligible flag, so those sit in totalPool and never in
  // totalBilled), per-tenant category exclusions, and cap adjustments.
  //
  // Comparing them unconditionally meant a landlord validating on a subset of
  // leases was told to "re-check invoice amounts or re-run allocation" — advice
  // that would change nothing, because nothing was wrong. Same mistake the
  // coverage flag made: a completeness signal presented as a defect.
  //
  // The diagnostic case is variance WITH complete coverage: the shares add up,
  // and the pool still does not reconcile. That one keeps the original warning.
  // Threshold matches reconciliation-engine.js section 3 (gap > 2 = incomplete).
  //
  // No arithmetic changed: totalPool, totalBilled and variance are as they were.
  const variance = Math.abs(totalBilled - totalPool);
  const _coverageIncomplete = proRataSum < 98;

  // WHERE THE DIFFERENCE WENT, not just how big it is.
  //
  // Both branches below used to end at a full stop. The reader was told a
  // five-figure sum was unallocated and given nowhere to go: the amber branch
  // said "re-check invoice amounts", which is wrong advice in the ordinary case,
  // and the grey branch named property coverage as the cause when coverage is
  // only ever one of four. So the banner now carries the same "Next step ›"
  // affordance the lease review flow uses, opening a panel that decomposes the
  // gap. Derivation only — see variance-breakdown.js; no CAM arithmetic here or
  // there changes, and the panel cannot state a figure the run did not produce.
  _lastVarianceBreakdown = (() => {
    try {
      const VB = window.VarianceBreakdown;
      if (!VB) return null;
      return VB.derive({
        results, invoices: engineInvoices || [], reconciled: reconciledInvoices,
        pool: totalPool, billed: totalBilled,
      });
    } catch (_) { return null; }
  })();
  const _vbStep = (() => {
    try { return window.VarianceBreakdown ? window.VarianceBreakdown.nextStep(_lastVarianceBreakdown) : null; }
    catch (_) { return null; }
  })();
  // No breakdown module, or nothing it can attribute → no CTA rather than a
  // button that opens an empty panel. A dead-end is what this change exists to
  // remove; offering one on the failure path would reintroduce it.
  const _vbCta = (_lastVarianceBreakdown && _vbStep)
    ? `<button type="button" class="rcs-variance-cta" onclick="event.stopPropagation();openVarianceDetails()">Next step: ${esc(_vbStep.cta)} &rsaquo;</button>`
    : '';
  const _vbOpen = _lastVarianceBreakdown
    ? ` role="button" tabindex="0" class="rcs-variance-banner" onclick="openVarianceDetails()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openVarianceDetails();}" title="See how this difference is made up"`
    : '';

  const varianceBanner = variance <= 0.05
    ? ''
    : _coverageIncomplete
      ? `<div${_vbOpen} style="background:var(--theme-surface);border:1px solid rgba(148,163,184,0.28);color:var(--text-3);padding:10px 14px;border-radius:8px;margin-bottom:12px;font-size:0.85rem;">
        <!-- Was "Expected — partial property coverage ... no action needed."
             The arithmetic was right and the certainty was not. At 37.3%
             coverage the system has NOT established what the remaining 62.7%
             is: the coverage finding says so explicitly and asks the reader to
             upload the remaining leases and re-run, because the answer decides
             whether that share is vacant space the landlord absorbs or a
             tenant obligation missing from the reconciliation. A banner
             calling the same figure expected and closing with "no action
             needed" contradicts that finding on the same screen, and quietly
             assigns the whole variance to the landlord.
             The numbers are untouched — totalBilled, totalPool, variance and
             proRataSum are exactly as they were. Only the claim about what
             they mean has changed. -->
        &#x1F4D0; <strong>Partial property coverage — ${fmt(variance)} currently unallocated.</strong> Total billed (${fmt(totalBilled)}) is less than the expense pool (${fmt(totalPool)}) because the loaded leases cover ${proRataSum.toFixed(1)}% of the property. Whether that remainder is vacant space the landlord absorbs, or space under a lease not yet uploaded, has not been established — upload any remaining leases and re-run to resolve it. Invoices marked not CAM-eligible, excluded by a lease, or reduced by a cap are also outside the billed total. No tenant charge changes when this is resolved: each is billed only its own share.
        ${_vbCta}
      </div>`
      : `<div${_vbOpen} style="background:var(--bgc-431407);border:1px solid #f97316;color:var(--c-fed7aa);padding:10px 14px;border-radius:8px;margin-bottom:12px;font-size:0.85rem;">
        <!-- Was ". Re-check invoice amounts or re-run allocation."
             The shares add up here, so coverage is not the explanation — but
             "re-check the invoice amounts" was only ever right for the one cause
             the panel now calls the unattributed residual, and wrong for the
             three that actually produce most of these gaps. It sent a manager
             looking for a typo in a register that was correct. The sentence now
             states the composition instead, and the CTA names the largest
             bucket. -->
        ⚠️ <strong>Reconciliation variance detected</strong> — total billed (${fmt(totalBilled)}) differs from total expense pool (${fmt(totalPool)}) by <strong>${fmt(variance)}</strong>.${
          _lastVarianceBreakdown
            ? ` The loaded leases cover ${proRataSum.toFixed(1)}% of the property, so this is not a coverage gap: ${esc(_varianceCauseSentence(_lastVarianceBreakdown))}`
            : ' Re-check invoice amounts or re-run allocation.'}
        ${_vbCta}
      </div>`;

  const rows = results.map(r => {
    const liveT  = tenantData.find(t => t && t.id === r.tenantId);
    const calcSt = _deriveCalcState(r, liveT);
    const capCell = r.capApplied
      ? `<td class="rcs-td rcs-num rcs-cap-cell">−${fmt(r.capAdjustment)}</td>`
      : `<td class="rcs-td rcs-muted">—</td>`;
    return `<tr class="rcs-row">
      <td class="rcs-td rcs-name-cell">${esc(r.name)}${r.unitNumber ? `<span class="rcs-unit"> · ${esc(r.unitNumber)}</span>` : ''}</td>
      <td class="rcs-td rcs-num">${r.sqFt ? Number(r.sqFt).toLocaleString() : '—'}</td>
      <td class="rcs-td rcs-num">${(r.proRata * 100).toFixed(2)}%</td>
      ${capCell}
      <td class="rcs-td rcs-num rcs-alloc-total">${fmt(r.totalAllocated)}</td>
      <td class="rcs-td"><span class="rc-calc-state ${calcSt.cls}" title="Describes the CAM calculation for this row, not the tenant's standing. Audit exceptions are listed in the AI Audit Summary.">${calcSt.label}</span></td>
      <td class="rcs-td">${(() => {
        // BILLING STATUS. Distinct from the CAM calculation state beside it: that
        // column says how much to trust the number, this one says whether it may
        // be sent. A row can read "Calc verified" and still be unbillable, which
        // is exactly the pairing a manager needs to see rather than infer.
        const b = _tenantBilling[r.name];
        if (!b) return '<span class="rcs-muted">—</span>';
        const nm = esc(r.name).replace(/'/g, "\\'");
        return `<button type="button" class="rcs-bill rcs-bill--${b.state}"
          onclick="generateTenantStatement('${nm}')"
          title="${esc(b.reason)}">${esc(b.label)}</button>`;
      })()}</td>
    </tr>`;
  }).join('');

  return varianceBanner + `
    <div class="rcs-panel ${panelCls}">
      <div class="rcs-panel-head">
        <span class="rcs-panel-title">&#x1F4CA; Reconciliation Summary</span>
        ${confidenceBadgeHtml}
        <span class="rcs-coverage-badge">${totalPool > 0 ? (totalBilled / totalPool * 100).toFixed(1) : '—'}% coverage</span>
        ${/* THE ROSTER LINE. On a phone the results table is several screens down
             and scrolls sideways, so the count that answers "who can I bill?"
             is stated here in words, beside the property verdict it qualifies.
             Reading _tenantBilling means it can never disagree with the column. */''}
        ${_exposure ? `<span class="rcs-bill-roster rcs-bill-roster--${
            _billableNames.length === results.length ? 'all'
          : _billableNames.length === 0              ? 'none' : 'some'}"
          title="${esc(_billableNames.length ? _billableNames.join(', ') : 'No tenant can be billed from this reconciliation yet.')}"
          >${_billableNames.length} of ${results.length} tenant${results.length === 1 ? '' : 's'} billable</span>` : ''}
        <!-- The same two words the tenant statement, the blocked screen and the
             Lender Summary use, from the same model. A manager should learn
             whether this run can be billed on the screen that produces it, not
             by trying to issue a statement and being refused. -->
        ${_billing ? `<span class="rcs-readiness-badge ${_billable ? 'rcs-readiness--ok' : 'rcs-readiness--blocked'}" title="${esc(_billing.reason || '')}">${_billable ? '&#x2713; Ready to bill' : '&#x26D4; Not ready to bill'}</span>` : ''}
        ${_balBadgeHtml}
      </div>
      ${(() => {
        // A REBUILT RECORD SAYS SO, ABOVE THE FIGURES IT QUALIFIES.
        //
        // When the snapshot blob is missing, the reconciliation is rebuilt from
        // the normalized cam_reconciliations rows, which carry the amount and
        // the share and nothing else. Rendered without a word, that record is
        // indistinguishable from a full run: "0 Caps Applied" and a per-tenant
        // invoice count read as findings about the reconciliation rather than as
        // data the rows never held.
        const _rec = (typeof currentProperty === 'function' && currentProperty()) || null;
        const _cr  = _rec && _rec.camReconciliation;
        if (!_cr || _cr.fidelity !== 'reduced') return '';
        const _why = (_cr.fidelityReasons || []).map(r => `<li>${esc(r)}</li>`).join('');
        return `<div class="rcs-fidelity" role="note">
          <strong>Rebuilt from saved summary rows.</strong>
          The amount billed to each tenant and its pro-rata share are as recorded. The detail below them is not:
          <ul class="rcs-fidelity-list">${_why}</ul>
          <span class="rcs-fidelity-cta">Re-run the reconciliation to restore the full breakdown.</span>
        </div>`;
      })()}
      <div class="rcs-kpis">
        ${avgConfidence !== null ? `<div class="rcs-kpi ${avgConfidence < 70 ? 'rcs-kpi--warn' : ''}"><div class="rcs-kpi-val">${avgConfidence}%</div><div class="rcs-kpi-lbl">Confidence</div></div>` : ''}
        <div class="rcs-kpi"><div class="rcs-kpi-val">${fmt(camPoolTotal)}</div><div class="rcs-kpi-lbl">CAM Pool${
          // When some invoices are held out of CAM the two figures differ, and a
          // reader seeing "CAM Pool $90,500" beside a banner that says "expense
          // pool $160,500" needs the two related on the spot rather than inferred.
          camPoolTotal < totalPool
            ? `<span class="rcs-kpi-sub"> of ${fmt(totalPool)} invoiced</span>` : ''
        }</div></div>
        <!-- "Total Billed" is a claim that money was billed. Until the audit
             clears this reconciliation, nothing has been: every statement is
             refused. The figure is identical either way; only the claim changes. -->
        <div class="rcs-kpi"><div class="rcs-kpi-val">${fmt(totalBilled)}</div><div class="rcs-kpi-lbl">${
          _billable ? 'Total Billed' : 'Calculated Tenant Allocation'}</div></div>
        <div class="rcs-kpi ${proCls}"><div class="rcs-kpi-val">${proRataSum.toFixed(1)}%</div><div class="rcs-kpi-lbl">Pro-Rata Sum</div></div>
        <div class="rcs-kpi ${capsCls}"><div class="rcs-kpi-val">${capsCount > 0 ? capsCount + ' (−' + fmt(capTotal) + ')' : '0'}</div><div class="rcs-kpi-lbl">Caps Applied</div></div>
        <!-- "Flagged" counted ONLY per-row allocation ambiguity (approximate
             sqft, unknown NNN/Gross, sqft overflow, base-year mismatch). It
             says nothing about audit exceptions, so "0 Flagged" sat beside 3
             critical exceptions and read as "no problems". The scope is now in
             the label, and the readiness chip above states the real verdict. -->
        <div class="rcs-kpi ${flagCls}" title="Per-tenant allocation ambiguity only — approximate square footage, unknown lease type, square-footage overflow or a base-year mismatch. Audit exceptions are counted separately in the AI Audit Summary."><div class="rcs-kpi-val">${flaggedCnt}</div><div class="rcs-kpi-lbl">Allocation Flags</div></div>
      </div>
      ${issueHtml}
      <div class="rcs-table-wrap">
        <table class="rcs-table">
          <thead><tr>
            <th class="rcs-th">Tenant</th>
            <th class="rcs-th rcs-num">Sqft</th>
            <th class="rcs-th rcs-num">Pro-Rata</th>
            <th class="rcs-th rcs-num">Cap Adj</th>
            <th class="rcs-th rcs-num">Allocated</th>
            <th class="rcs-th" title="Whether the CAM arithmetic for this row used sound inputs. It is not a statement about the lease or the tenant — audit exceptions are reported in the AI Audit Summary.">CAM calculation</th>
            <th class="rcs-th" title="Whether a statement may be issued to this tenant. Read from the same billing readiness the statement itself applies — the two cannot disagree.">Billing status</th>
          </tr></thead>
          <tbody>${rows}</tbody>
          <tfoot><tr class="rcs-total-row">
            <td class="rcs-td rcs-total-label" colspan="2">TOTAL</td>
            <td class="rcs-td rcs-num">${proRataSum.toFixed(1)}%</td>
            <td class="rcs-td rcs-num">${capsCount > 0 ? '−' + fmt(capTotal) : '—'}</td>
            <td class="rcs-td rcs-num rcs-alloc-total">${fmt(totalBilled)}</td>
            <td class="rcs-td"></td>
            <td class="rcs-td rcs-bill-total">${_billableNames.length} of ${results.length} billable</td>
          </tr></tfoot>
        </table>
      </div>
    </div>`;
}

// ─── Tenant Detail Panel ──────────────────────────────────────────────────────

function _tdpDisputeBadge(status) {
  const map = {
    open:           { cls: 'open',     label: 'Open' },
    docs_requested: { cls: 'review',   label: 'Under Review' },
    accepted:       { cls: 'resolved', label: 'Resolved' },
    rejected:       { cls: 'rejected', label: 'Rejected' },
  };
  const cfg = map[status] || { cls: 'open', label: status || 'Open' };
  return `<span class="tdp-dispute-badge ${cfg.cls}">${cfg.label}</span>`;
}

function _tdpDisputesHtml(tenantName) {
  if (!tenantName) return `<div class="tdp-empty-disputes">No disputes for this tenant.</div>`;

  const tenantDisputes = disputes.filter(d => d.tenantName === tenantName);
  if (!tenantDisputes.length) {
    return `<div class="tdp-empty-disputes">No disputes for this tenant.</div>`;
  }

  function _ts(iso) {
    if (!iso) return '';
    try {
      return new Date(iso).toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });
    } catch (e) { return ''; }
  }

  return tenantDisputes.map(d => {
    const isResolved = d.status === 'accepted';
    const isRejected = d.status === 'rejected';
    const cardCls    = isResolved ? ' is-resolved' : isRejected ? ' is-rejected' : '';

    const amountStr  = (d.tenantShare !== null && d.tenantShare !== undefined && !isNaN(d.tenantShare))
      ? fmt(parseFloat(d.tenantShare))
      : '—';
    const vendor     = d.vendor   || 'Unknown vendor';
    const category   = d.category || 'Unknown category';
    const reason     = d.reason   || '(no reason given)';
    const docHtml    = d.docName
      ? `<div style="font-size:0.73rem;color:var(--c-4ade80);margin:4px 0 8px;font-family:'DM Mono',monospace;">&#x1F4CE; ${esc(d.docName)}</div>`
      : '';

    const resolvedTs = (d.resolvedAt && (isResolved || isRejected))
      ? `<div style="font-size:0.73rem;color:var(--text-4);margin-top:4px;">${isResolved ? 'Resolved' : 'Rejected'} · ${_ts(d.resolvedAt)}</div>`
      : '';

    const actionHtml = '';

    return `
      <div class="tdp-dispute-card${cardCls}">
        <div class="tdp-dc-header">
          <div class="tdp-dc-title">${esc(vendor)} &middot; ${esc(category)}</div>
          ${_tdpDisputeBadge(d.status)}
        </div>
        <div class="tdp-dc-meta">${amountStr}${d.timestamp ? ' &middot; Opened ' + _ts(d.timestamp) : ''}</div>
        <div class="tdp-dc-reason">&ldquo;${esc(reason)}&rdquo;</div>
        ${docHtml}
        ${resolvedTs}
        ${actionHtml}
      </div>`;
  }).join('');
}

function openTenantDetailPanel(i) {
  const d = tenantData[i];
  if (!d || d.status === 'pending') return;

  const panel    = document.getElementById('tenantDetailPanel');
  const titleEl  = document.getElementById('tdpTitle');
  const subEl    = document.getElementById('tdpSubtitle');
  const bodyEl   = document.getElementById('tdpBody');
  if (!panel || !bodyEl) return;

  // Match by tenantId (stable) if reconciliation has run, else no recon data
  const recon = lastResults.find(r => r.tenantId === d.id) || null;

  const _v  = (val, fallback = '—') => (val !== null && val !== undefined && val !== '') ? val : fallback;
  const _pct = (val) => (val !== null && val !== undefined && !isNaN(val))
    ? parseFloat(val).toFixed(2) + '%' : '—';
  const _fmt = (n) => (n !== null && n !== undefined && !isNaN(n))
    ? '$' + parseFloat(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : '—';

  const confLevel = _tenantConfLevel(d);
  const badgeHtml = _confidenceBadgeHtml(confLevel);

  const name    = d.tenant_name || '(unknown)';
  const sqft    = d.leased_sqft ? Number(d.leased_sqft).toLocaleString('en-US') + ' sqft' : null;
  const capPct  = d.cap ?? null;

  // Pro-rata: prefer live recon value (most accurate), fall back to lease-level cap
  const proRataPct = recon
    ? _pct(recon.proRataPercent)
    : '—';

  const allocatedCam  = recon ? _fmt(recon.totalAllocated) : null;
  const invoiceCount  = recon ? recon.includedInvoices.length : null;

  titleEl.textContent = name;
  subEl.textContent   = d.lease_type || '';

  bodyEl.innerHTML = `
    <div class="tdp-name-row">
      <span class="tdp-tenant-name">${esc(name)}</span>
      ${badgeHtml}
    </div>

    <div class="tdp-section">Lease Info</div>
    <div class="tdp-grid">
      <div class="tdp-stat">
        <div class="tdp-stat-label">Lease Type</div>
        <div class="tdp-stat-value${!d.lease_type ? ' tdp-null' : ''}">${esc(_v(d.lease_type))}</div>
        ${_citationChip(d, 'lease_type')}
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">Leased Sqft</div>
        <div class="tdp-stat-value${!d.leased_sqft ? ' tdp-null' : ''}">${esc(sqft || '—')}</div>
        ${_citationChip(d, 'leased_sqft')}
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">Start Date</div>
        <div class="tdp-stat-value${!d.start_date ? ' tdp-null' : ''}">${esc(_v(d.start_date))}</div>
        ${_citationChip(d, 'start_date')}
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">End Date</div>
        <div class="tdp-stat-value${!d.end_date ? ' tdp-null' : ''}">${esc(_v(d.end_date))}</div>
        ${_citationChip(d, 'end_date')}
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">CAM Cap</div>
        <div class="tdp-stat-value${capPct === null ? ' tdp-null' : ''}">${capPct !== null ? capPct + '%' : '—'}</div>
        ${_citationChip(d, 'cap')}
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">Pro-Rata %</div>
        <div class="tdp-stat-value tdp-highlight">${proRataPct}</div>
      </div>
    </div>

    ${recon ? `
    <div class="tdp-section">CAM Reconciliation</div>
    <div class="tdp-grid">
      <div class="tdp-stat">
        <div class="tdp-stat-label">Allocated CAM</div>
        <div class="tdp-stat-value tdp-highlight">${allocatedCam}</div>
      </div>
      <div class="tdp-stat">
        <div class="tdp-stat-label">Invoice Count</div>
        <div class="tdp-stat-value">${invoiceCount}</div>
      </div>
      ${recon.capApplied ? `
      <div class="tdp-stat tdp-wide">
        <div class="tdp-stat-label">Cap Applied</div>
        <div class="tdp-stat-value">Cap reduced charge by ${_fmt(recon.capAdjustment)}</div>
      </div>` : ''}
    </div>` : `
    <div class="tdp-section">CAM Reconciliation</div>
    <div class="tdp-no-recon">Run reconciliation to see CAM totals and invoice breakdown.</div>`}

    <div class="tdp-section">Disputes</div>
    ${_tdpDisputesHtml(d.tenant_name)}

    ${_tdpFieldEvidenceHtml(d)}
  `;

  document.body.style.overflow = 'hidden';
  panel.classList.add('open');
}

// Renders an expandable "Source Evidence" section in the tenant detail panel.
// Shows only fields that have an extracted quote — fields with no evidence are
// omitted so the section only appears when there is something useful to show.
function _tdpFieldEvidenceHtml(t) {
  const FIELDS = [
    'lease_type', 'leased_sqft', 'start_date', 'end_date',
    'cap', 'admin_fee_pct', 'gross_up_pct', 'expense_stop',
    'audit_rights', 'excluded_categories',
  ];

  const rows = FIELDS
    .map(key => {
      const ev = getFieldEvidence(key, t);
      if (!ev?.source?.quote && !ev?.source?.page && !ev?.source?.section) return null;
      const label = _LEV_FIELD_LABELS[key] || key;
      const src   = ev.source;
      const meta  = [
        src.section ? 'Section: ' + src.section : '',
        src.page    ? 'Page ' + src.page         : '',
        src.fileName ? src.fileName               : '',
      ].filter(Boolean).join(' · ');
      const quoteHtml = src.quote
        ? `<blockquote class="tdp-ev-quote">${esc(src.quote)}</blockquote>`
        : '';
      return `<div class="tdp-ev-row">
          <div class="tdp-ev-field">${esc(label)}</div>
          ${meta ? `<div class="tdp-ev-meta">${esc(meta)}</div>` : ''}
          ${quoteHtml}
        </div>`;
    })
    .filter(Boolean);

  if (!rows.length) return '';

  return `
    <details class="tdp-ev-details">
      <summary class="tdp-section tdp-ev-summary">Source Evidence <span class="tdp-ev-count">${rows.length} field${rows.length !== 1 ? 's' : ''}</span></summary>
      <div class="tdp-ev-body">${rows.join('')}</div>
    </details>`;
}

function closeTenantDetailPanel() {
  const panel = document.getElementById('tenantDetailPanel');
  if (panel) panel.classList.remove('open');
  document.body.style.overflow = '';
}

// ─── Lease Viewer ─────────────────────────────────────────────────────────────

// Primary: open lease in the in-app modal viewer.
function openLease(file) {
  openLeaseModal(file);
}

// Entry point for all inline onclick buttons.
function openLeaseModalFromFile(index) {
  const d = tenantData[index];
  if (!d) return;
  if (d.leaseFile instanceof File) {
    openLeaseModal(d.leaseFile);
  } else if (d.leaseUrl) {
    if (d.leaseUrl.startsWith('blob:')) {
      // Blob URLs are session-only and cannot survive a page reload
      showToast('Lease document no longer in memory — please re-upload the lease to view it', { color: '#92400e', textColor: '#fef3c7', duration: 5000 });
    } else {
      openLeaseModal(d.leaseUrl);
    }
  } else {
    showToast('Lease document not attached — please re-upload the lease to view it', { color: '#92400e', textColor: '#fef3c7', duration: 5000 });
  }
}

// Modal viewer — accepts a File object (local) or a URL string (persisted).
async function openLeaseModal(fileOrUrl) {
  if (!fileOrUrl) return;
  // SEC-1 — a stored /object/public/ URL will not load in the iframe once the
  // bucket is private. Resolve it to a signed URL first; a File object is a
  // local blob and needs nothing.
  if (typeof fileOrUrl === 'string') {
    const _readable = await resolveDocumentUrl(fileOrUrl);
    if (!_readable) {
      showToast('⚠️ That lease could not be opened — you may not have access, or it is no longer stored.',
        { color: '#92400e', textColor: '#fef3c7', duration: 8000 });
      return;
    }
    fileOrUrl = _readable;
  }
  const modal = document.getElementById('leaseViewerModal');
  const frame = document.getElementById('leaseViewerFrame');
  const title = document.getElementById('leaseViewerTitle');

  let url, titleText, isBlob;
  if (typeof fileOrUrl === 'string') {
    url       = fileOrUrl;
    titleText = 'Lease Document';
    isBlob    = false;
  } else {
    url       = URL.createObjectURL(fileOrUrl);
    titleText = fileOrUrl.name || 'Lease Document';
    isBlob    = true;
  }

  modal._leaseUrl = url;
  modal._isBlob   = isBlob;
  if (title) title.textContent = titleText;
  frame.src = url;
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

function closeLeaseModal() {
  const modal = document.getElementById('leaseViewerModal');
  const frame = document.getElementById('leaseViewerFrame');
  if (frame) { frame.onload = null; frame.src = ''; }
  if (modal) {
    modal.style.display = 'none';
    if (modal._leaseUrl && modal._isBlob) {
      URL.revokeObjectURL(modal._leaseUrl);
    }
    modal._leaseUrl = null;
    modal._isBlob   = false;
  }
  document.body.style.overflow = '';
}

function leaseViewerOpenExternal() {
  const modal = document.getElementById('leaseViewerModal');
  if (!modal?._leaseUrl) return;
  // The modal holds an already-resolved URL, but this opens whatever is in it —
  // and a blob: or javascript: value must never reach window.open from a field
  // that other code writes. Allow only what can legitimately be here.
  let u;
  try { u = new URL(modal._leaseUrl, window.location.origin); } catch (_) { return; }
  if (u.protocol !== 'https:' && u.protocol !== 'blob:' && u.protocol !== 'http:') return;
  window.open(u.href, '_blank', 'noopener');
}

// ESC key always closes modal — user can never be trapped
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (document.getElementById('reviewWorkspace')?.classList.contains('open')) {
      closeReviewWorkspace();
    } else {
      closeLeaseModal();
    }
  }
});

// Global click diagnostic — reports what element received the click and any blocking overlays
document.addEventListener('click', (e) => {
  const path = e.composedPath ? e.composedPath() : [];
  const topEl = path[0] || e.target;

  // Check every fixed/absolute overlay that could be covering content
  const overlayIds = ['explainPanel','leaseViewerModal','allocModal','reportOverlay','invFileViewer','loginScreen'];
  const overlayState = overlayIds.map(id => {
    const el = document.getElementById(id);
    if (!el) return `${id}:MISSING`;
    const s = window.getComputedStyle(el);
    return `${id}:display=${s.display},vis=${s.visibility},pe=${s.pointerEvents}`;
  });

  console.log('[CLICK PROBE]', {
    target:          e.target?.id || e.target?.className || e.target?.tagName,
    composedPath0:   topEl?.id || topEl?.className || topEl?.tagName,
    composedPathLen: path.length,
    pathIds:         path.slice(0,8).map(el => el.id || el.className || el.tagName || '?'),
    clientXY:        `${e.clientX},${e.clientY}`,
    elementAtPoint:  document.elementFromPoint(e.clientX, e.clientY)?.id
                     || document.elementFromPoint(e.clientX, e.clientY)?.className
                     || document.elementFromPoint(e.clientX, e.clientY)?.tagName,
    overlays:        overlayState,
    bodyOverflow:    document.body.style.overflow,
    bodyPE:          window.getComputedStyle(document.body).pointerEvents,
  });
}, true); // capture phase so we see it before any stopPropagation

// Delegated retry handler — survives innerHTML re-renders.
// Uses retryLeaseJob (in-memory file) when available; falls back to file picker.
document.addEventListener('click', (e) => {
  const retryEl = e.target.closest('[data-retry]');
  if (!retryEl) return;
  e.stopPropagation();
  const i     = parseInt(retryEl.dataset.index, 10);
  const jobId = retryEl.dataset.jobId;
  if (jobId && _leaseJobs.get(jobId)?._file) {
    retryLeaseJob(jobId);
  } else {
    retryUploadForSlot(i);
  }
});

// Mousedown diagnostic — fires before click; confirms the pointer event is reaching the DOM
document.addEventListener('mousedown', (e) => {
  const el = document.elementFromPoint(e.clientX, e.clientY);
  console.log('[MOUSEDOWN PROBE]', {
    target:         e.target?.id || e.target?.className || e.target?.tagName,
    elementAtPoint: el?.id || el?.className || el?.tagName,
    clientXY:       `${e.clientX},${e.clientY}`,
  });
}, true);

// Clicking the dark backdrop closes modal
document.getElementById('leaseViewerModal')?.addEventListener('click', (e) => {
  if (e.target.id === 'leaseViewerModal') closeLeaseModal();
});

// ─── Report State ─────────────────────────────────────────────────────────────
const camRuns    = []; // previous run history
let lastResults  = []; // ReconciliationResult[] — unified with lastFullResults
let lastResultsYear = null; // CAM year of the most recent runAllocation() call
let _resultsStale = false; // true when field edits happen after a reconciliation run

// ─── CAM Year ─────────────────────────────────────────────────────────────────
let _camYear = new Date().getFullYear(); // hydrated from scoped key in _lsMigrateAncillaryKeys()
// Top-level `let` in a classic script is NOT a window property, so other
// modules cannot read it. property-os.js needs the active CAM year to scope the
// Financials panel; expose a reader rather than the binding.
window.currentCamYear = function () { return _camYear != null ? _camYear : null; };
function getCamYear() { return _camYear; }
function setCamYear(y) {
  _camYear = parseInt(y, 10) || new Date().getFullYear();
  localStorage.setItem(_camYearKey(), _camYear);
  const glLbl = document.getElementById('glUploadLabel');
  if (glLbl) glLbl.textContent = `Upload ${_camYear} GL Excel File (.xlsx only)`;
  const _cyb = document.getElementById('camYearBadge');
  if (_cyb) _cyb.textContent = _camYear + ' CAM';
  const _cybm = document.getElementById('wsMobileCamYear');
  if (_cybm) _cybm.textContent = _camYear + ' CAM';
  // Keep the Property Setup dropdown in sync when the year changes (e.g. a loaded
  // reconciliation restores a prior year) so it can't disagree with the breadcrumb.
  const _cys = document.getElementById('camYearSelect');
  if (_cys && _cys.value !== String(_camYear)) _cys.value = String(_camYear);
}
function initCamYearSelect() {
  const sel = document.getElementById('camYearSelect');
  if (!sel) return;
  const cur = new Date().getFullYear();
  sel.innerHTML = '';
  for (let yr = cur - 3; yr <= cur + 1; yr++) {
    const opt = document.createElement('option');
    opt.value = yr;
    opt.textContent = `${yr} CAM`;
    if (yr === _camYear) opt.selected = true;
    sel.appendChild(opt);
  }
  const glLbl = document.getElementById('glUploadLabel');
  if (glLbl) glLbl.textContent = `Upload ${_camYear} GL Excel File (.xlsx only)`;
  const _cyb2 = document.getElementById('camYearBadge');
  if (_cyb2) _cyb2.textContent = _camYear + ' CAM';
}
let sqftMismatch   = false;
let isEditingField = false; // true while a text/number/date input has focus
let isRunning      = false; // guard against concurrent runAllocation() calls

function applySqftMismatchUI(mismatch) {
  sqftMismatch = mismatch;
  if (mismatch && window.innerWidth < 768) {
    const banner = document.querySelector('.sqft-mismatch-banner');
    if (banner) setTimeout(() => banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 100);
  }
}

function fixSqftToMatch(leaseTotalSqft) {
  const sqftInput = document.getElementById('totalSqft');
  if (sqftInput) {
    sqftInput.value = leaseTotalSqft;
    updatePropertySqft(leaseTotalSqft);
  }
  showToast(`Property sqft updated to ${Number(leaseTotalSqft).toLocaleString()} sqft`);
  rerunAfterWarning();
}

function rerunAfterWarning() {
  document.querySelectorAll('.sqft-mismatch-banner').forEach(el => el.remove());
  setTimeout(() => runAllocation(), 50);
}
let lastPropName = '';
let lastTotal    = 0;   // gross: every invoice loaded
let lastCamPool  = 0;   // the subset tenants can be billed from
let lastInvoicesFull = []; // full invoice list with category sums
let lastFullResults  = []; // ReconciliationResult[] from runFullReconciliation

// ─── Dispute Types + Severity ─────────────────────────────────────────────────
const _DISPUTE_TYPES = {
  cam_cap_violation:     { label: 'CAM Cap Violation'     },
  excluded_expense:      { label: 'Excluded Expense'      },
  duplicate_billing:     { label: 'Duplicate Billing'     },
  allocation_mismatch:   { label: 'Allocation Mismatch'   },
  expired_lease_billing: { label: 'Expired Lease Billing' },
  admin_fee_violation:   { label: 'Admin Fee Violation'   },
  unsupported_invoice:   { label: 'Unsupported Invoice'   },
};
const _DISPUTE_SEV = {
  low:      { label: 'Low',      cls: 'dsev-low'  },
  medium:   { label: 'Medium',   cls: 'dsev-med'  },
  high:     { label: 'High',     cls: 'dsev-high' },
  critical: { label: 'Critical', cls: 'dsev-crit' },
};
let _lastReconIssues = []; // last _detectReconciliationIssues() output — used by openDisputeFromFlag
let _dwActiveDid     = null; // active dispute ID in workspace overlay

// ─── Dispute State ────────────────────────────────────────────────────────────
let lastInvoices = []; // [{ id, vendor, category, amount }]
let lastTenants  = []; // [{ name, excludedCategories }]
const disputes   = []; // [{ id, tenantName, invoiceId, vendor, category, tenantShare, reason, timestamp, status, resolution, resolvedAt, hash, disputeType, severity, reviewerNote, leaseClause, history[] }]
let nextDisputeId = 0;

// ─── Activity Log ─────────────────────────────────────────────────────────────
const activityLog = []; // { type, title, detail, severity, timestamp, actor, relatedEntity, financialImpact }

function logActivity(type, title, opts = {}) {
  // Event shaping delegated to AuditService — ensures canonical field set,
  // valid severity, and automatic propertyId tagging on every entry.
  activityLog.unshift(AuditService.shapeEvent(type, title, { ...opts, propertyId: activePropId }));
  if (activityLog.length > 200) activityLog.length = 200;
  savePropertyData(); // persist change — debounced, so rapid events collapse
}

// Direct audit push — bypasses savePropertyData() to avoid re-entrancy during
// save/load callbacks. Use only for migration_applied, snapshot_restored,
// malformed_state_recovered events where the caller already holds the save lock.
function _auditDirect(type, title, opts = {}) {
  activityLog.unshift(AuditService.shapeEvent(type, title, { ...opts, propertyId: activePropId }));
  if (activityLog.length > 200) activityLog.length = 200;
}

// ─── Checkpoint System ────────────────────────────────────────────────────────
// _cpKey() defined near _lsUserKey() — returns uid-scoped localStorage key
const _checkpoints = {};

function _loadCheckpoints() {
  try {
    const raw = localStorage.getItem(_cpKey());
    if (raw) Object.assign(_checkpoints, JSON.parse(raw));
  } catch (e) { }
}

function _saveCheckpoints() {
  try {
    localStorage.setItem(_cpKey(), JSON.stringify(_checkpoints));
  } catch (e) {
    // quota exceeded — trim to 2 per property and retry
    Object.keys(_checkpoints).forEach(id => {
      if (_checkpoints[id].length > 2) _checkpoints[id].length = 2;
    });
    try { localStorage.setItem(_cpKey(), JSON.stringify(_checkpoints)); } catch (_innerE) {
      logError('_saveCheckpoints', _innerE, { checkpointCount: Object.keys(_checkpoints || {}).length });
      showToast('⚠️ Checkpoint save failed — recovery history may be incomplete.', { color: '#92400e', textColor: '#fef3c7', duration: 5000 });
    }
  }
}

function captureCheckpoint(propId, label) {
  if (!propId) return;
  const prop = _props.find(p => p.id === propId);
  if (!prop) return;
  if (!_checkpoints[propId]) _checkpoints[propId] = [];
  try {
    const snap = _stripBlobs({
      ...prop,
      tenants:     [...(prop.tenants     || [])],
      invoices:    [...(prop.invoices    || [])],
      disputes:    [...(prop.disputes    || [])],
      activityLog: [...activityLog],
    });
    _checkpoints[propId].unshift({ ts: new Date().toISOString(), label, snapshot: snap });
    if (_checkpoints[propId].length > 5) _checkpoints[propId].length = 5;
    _saveCheckpoints();
  } catch (e) { console.warn('[captureCheckpoint] failed:', e.message); }
}

// ─── Sync Status ──────────────────────────────────────────────────────────────
let _syncStatus = 'idle';
let _lastSyncAt = null;

function _setSyncStatus(status, errorMsg) {
  _syncStatus = status;
  if (!window.ms_syncState) window.ms_syncState = { status: 'idle', lastSavedAt: null, lastCloudSyncAt: null, lastError: null };
  window.ms_syncState.status = status;
  const _now = new Date().toISOString();
  if (status === 'local')  window.ms_syncState.lastSavedAt     = _now;
  if (status === 'synced') { _lastSyncAt = new Date(); window.ms_syncState.lastCloudSyncAt = _now; }
  if (status === 'error')  window.ms_syncState.lastError       = { ts: _now, message: errorMsg || 'Unknown error' };
  _renderSyncIndicator();
}

function _renderSyncIndicator() {
  const el = document.getElementById('syncIndicator');
  if (!el) return;
  const cfgMap = {
    idle:     { cls: '',            icon: '',  label: '' },
    pending:  { cls: 'si-pending',  icon: '◌', label: 'Saving…' },
    local:    { cls: 'si-local',    icon: '◎', label: 'Saved locally' },
    synced:   { cls: 'si-synced',   icon: '✓', label: 'Synced to cloud ✓' },
    error:    { cls: 'si-error',    icon: '⚠', label: 'Error saving' },
    conflict: { cls: 'si-conflict', icon: '⚡', label: 'Conflict' },
    recovery: { cls: 'si-recovery', icon: '↩', label: 'Recovery available' },
  };
  const cfg = cfgMap[_syncStatus] || { cls: '', icon: '', label: '' };
  const ts = _lastSyncAt
    ? `Last synced ${_lastSyncAt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}`
    : '';
  el.className = `sync-indicator${cfg.cls ? ' ' + cfg.cls : ''}`;
  el.title = ts;
  el.innerHTML = cfg.label
    ? `<span class="si-icon">${cfg.icon}</span><span class="si-label">${cfg.label}</span>`
    : '';
}

// ─── Integrity Checks ────────────────────────────────────────────────────────
function checkIntegrity(prop) {
  const issues = [];
  if (!prop) return issues;

  const results  = (prop.camReconciliation ?? prop.results)?.results || [];
  const invoices = prop.invoices || [];
  const tenants  = prop.tenants  || [];
  const disps    = prop.disputes || [];

  // 1. Allocation sums — the allocated total must never EXCEED the expense pool.
  //
  // This check was wrong twice, and both were visible on every reconciled
  // property. It summed `tenantShare`, which no reconciliation row has ever
  // carried — the field is `totalAllocated` — so the sum was always 0. And it
  // tested EQUALITY against the snapshot's `total`, which is the GROSS expense
  // pool: allocations fall short of it whenever a suite is vacant, an invoice
  // is not CAM-eligible, or a cap bites, all of them normal and all of them
  // already accounted for, line by line, in the variance breakdown. So a clean
  // run reported "Allocated total ($0.00) differs from declared total
  // ($40,000.00)" as a data-integrity ERROR, permanently, and the only recovery
  // action on the panel sat under a finding that was never true.
  //
  // The inequality in the comment above is the invariant worth keeping: money
  // may go unallocated, but more money may never be allocated than came in.
  if (results.length) {
    const allocated = results.reduce(
      (s, r) => s + (parseFloat(r.totalAllocated ?? r.allocatedAmount ?? r.tenantShare) || 0), 0);
    const pool = (prop.camReconciliation ?? prop.results)?.total || 0;
    if (pool && allocated - pool > 1) {
      issues.push({
        type:    'allocation_mismatch',
        level:   'error',
        message: `Allocated total (${fmt(allocated)}) exceeds the expense pool (${fmt(pool)}) by ${fmt(allocated - pool)}`,
      });
    }
  }

  // 2. Invoice total integrity — sum of amounts should be positive
  const invoiceTotal = invoices.reduce((s, inv) => s + (parseFloat(inv.amount) || 0), 0);
  if (invoices.length && invoiceTotal <= 0) {
    issues.push({ type: 'invalid_invoice_total', level: 'error', message: 'Invoice total is zero or negative — check uploaded amounts.' });
  }

  // 3. Orphaned invoices — invoices with no category assignment
  const orphaned = invoices.filter(inv => !inv.category || inv.category === 'Uncategorized');
  if (orphaned.length) {
    issues.push({ type: 'orphaned_invoices', level: 'warning', message: `${orphaned.length} invoice${orphaned.length > 1 ? 's' : ''} have no category assignment.` });
  }

  // 4. Missing tenant mappings — results rows with no matching tenant
  if (results.length && tenants.length) {
    const tenantNames = new Set(tenants.map(t => (t.tenant_name || '').toLowerCase()));
    const unmapped = results.filter(r => !tenantNames.has((r.tenantName || '').toLowerCase()));
    if (unmapped.length) {
      issues.push({ type: 'missing_tenant_mapping', level: 'warning', message: `${unmapped.length} reconciliation row${unmapped.length > 1 ? 's' : ''} have no matching tenant record.` });
    }
  }

  // 5. Duplicate tenant IDs
  if (tenants.length) {
    const ids = tenants.map(t => t.id).filter(Boolean);
    const dups = ids.filter((id, i) => ids.indexOf(id) !== i);
    if (dups.length) {
      issues.push({ type: 'duplicate_tenant_ids', level: 'error', message: `${dups.length} duplicate tenant ID${dups.length > 1 ? 's' : ''} detected.` });
    }
  }

  // 6. Invalid pro-rata (any tenant with leased_sqft > property sqft)
  if (prop.totalSqft) {
    const oversized = tenants.filter(t => (parseFloat(t.leased_sqft) || 0) > (prop.totalSqft || Infinity));
    if (oversized.length) {
      issues.push({ type: 'invalid_prorata', level: 'error', message: `${oversized.length} tenant${oversized.length > 1 ? 's have' : ' has'} leased sqft exceeding property total.` });
    }
  }

  // 7. Open disputes with no resolution path
  const openDisps = disps.filter(d => d.status === 'open');
  if (openDisps.length) {
    issues.push({ type: 'open_disputes', level: 'warning', message: `${openDisps.length} open dispute${openDisps.length > 1 ? 's' : ''} require resolution.` });
  }

  // 8. Partial reconciliation state — invoices exist but no CAM run
  if (invoices.length && !results.length && tenants.length) {
    issues.push({ type: 'partial_reconciliation', level: 'warning', message: 'Invoices and tenants are loaded but no CAM reconciliation has been run.' });
  }

  return issues;
}

// ─── Recovery Modal ──────────────────────────────────────────────────────────
function openRecoveryModal() {
  const prop = _props.find(p => p.id === activePropId);
  let modal = document.getElementById('recoveryModal');
  if (!modal) return;
  _buildRecoveryModalBody(prop);
  modal.style.display = 'flex';
}

function closeRecoveryModal() {
  const modal = document.getElementById('recoveryModal');
  if (modal) modal.style.display = 'none';
}

function _buildRecoveryModalBody(prop) {
  const body = document.getElementById('recoveryModalBody');
  if (!body) return;

  const cpList = _checkpoints[prop?.id] || [];
  const issues = prop ? checkIntegrity(prop) : [];
  const errors  = issues.filter(i => i.level === 'error');
  const warnings = issues.filter(i => i.level === 'warning');

  // ── Sync status section ──
  const syncHtml = `
    <div class="rc-section">
      <div class="rc-section-title">Sync Status</div>
      <div class="rc-sync-row">
        <span class="rc-sync-dot rc-sync-dot--${_syncStatus}"></span>
        <span class="rc-sync-label">${{
          idle:     'Idle',
          pending:  'Save in progress…',
          synced:   'Cloud synced' + (_lastSyncAt ? ` · ${_lastSyncAt.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}` : ''),
          error:    'Sync failed — data saved locally only',
          conflict: 'Conflict detected',
          recovery: 'Recovery available',
        }[_syncStatus] || _syncStatus}</span>
      </div>
    </div>`;

  // ── Integrity section ──
  let integrityRows = '';
  if (issues.length === 0) {
    integrityRows = '<div class="rc-integrity-ok">✓ No integrity issues found</div>';
  } else {
    integrityRows = issues.map(iss => `
      <div class="rc-issue rc-issue--${iss.level}">
        <span class="rc-issue-icon">${iss.level === 'error' ? '✕' : '⚠'}</span>
        <span class="rc-issue-msg">${iss.message}</span>
      </div>`).join('');
  }
  const integrityHtml = `
    <div class="rc-section">
      <div class="rc-section-title">Data Integrity
        <span class="rc-badge ${errors.length ? 'rc-badge--error' : warnings.length ? 'rc-badge--warn' : 'rc-badge--ok'}">
          ${errors.length ? errors.length + ' error' + (errors.length > 1 ? 's' : '') : warnings.length ? warnings.length + ' warning' + (warnings.length > 1 ? 's' : '') : 'Clean'}
        </span>
      </div>
      ${integrityRows}
      ${issues.length ? `<button class="rc-action-btn" onclick="rebuildReconciliationState()">↺ Rebuild Reconciliation State</button>` : ''}
    </div>`;

  // ── Checkpoints section ──
  let cpRows = '';
  if (cpList.length === 0) {
    cpRows = '<div class="rc-no-cp">No checkpoints saved yet. Checkpoints are captured automatically before major operations.</div>';
  } else {
    cpRows = cpList.map((cp, i) => {
      const d = new Date(cp.ts);
      const label = cp.label || 'Checkpoint';
      const ts = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
               + ' ' + d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
      return `
        <div class="rc-cp-row">
          <div class="rc-cp-info">
            <span class="rc-cp-label">${label}</span>
            <span class="rc-cp-ts">${ts}</span>
          </div>
          <button class="rc-restore-btn" onclick="restoreCheckpoint(${i})">Restore</button>
        </div>`;
    }).join('');
  }
  const cpHtml = `
    <div class="rc-section">
      <div class="rc-section-title">Checkpoint History <span class="rc-cp-count">${cpList.length}/5</span></div>
      ${cpRows}
    </div>`;

  // ── Export section ──
  const exportHtml = `
    <div class="rc-section">
      <div class="rc-section-title">Export Backup</div>
      <p class="rc-export-desc">Download a full JSON backup of this property's data (invoices, tenants, reconciliation, disputes, activity log).</p>
      <button class="rc-action-btn rc-export-btn" onclick="exportPropertyBackup()">⬇ Export Property Backup</button>
    </div>`;

  // ── Property Lifecycle ──
  // Archive is the NORMAL end of a property's life, so it needs its own way in.
  // It shipped reachable only from inside the Delete modal's "Archive Instead"
  // button — which made the normal path a subordinate of the exceptional one,
  // and meant the only route to a non-destructive action was through the
  // destructive dialog. ARCHITECTURE_PRINCIPLES §4.
  //
  // No confirmation: archiving destroys nothing and Restore is one click from
  // the portfolio. Ceremony belongs to the irreversible action, not this one.
  const lifecycleHtml = `
    <div class="rc-section">
      <div class="rc-section-title">Property Lifecycle</div>
      <p class="rc-export-desc">No longer managing this building? Archive keeps every lease, timeline entry, document and reconciliation, removes it from your active portfolio, and can be undone at any time.</p>
      <button class="rc-action-btn" onclick="closeRecoveryModal(); archiveActiveProperty();">&#x1F4E6; Archive Property — keep the history, clear it from the portfolio</button>
    </div>`;

  // ── Danger Zone (moved here from the property breadcrumb so destructive actions
  //    aren't one stray click away in the primary bar) ──
  const dangerHtml = `
    <div class="rc-section">
      <div class="rc-section-title" style="color:var(--c-fca5a5);">Danger Zone</div>
      <p class="rc-export-desc">These affect this property's data and can't be undone.</p>
      <button class="rc-action-btn" style="border-color:rgba(239,68,68,0.35);color:var(--c-fca5a5);" onclick="closeRecoveryModal(); clearPropertyData();">&#x1F5D1; Clear Data — reset tenants &amp; invoices (keep the property)</button>
      <button class="rc-action-btn" style="border-color:rgba(239,68,68,0.35);color:var(--c-fca5a5);margin-top:8px;" onclick="closeRecoveryModal(); openDeletePropertyModal();">&#x1F5D1; Delete Property — remove this property and all its data</button>
    </div>`;

  body.innerHTML = syncHtml + integrityHtml + cpHtml + exportHtml + lifecycleHtml + dangerHtml;
}

function restoreCheckpoint(index) {
  const cpList = _checkpoints[activePropId];
  if (!cpList || !cpList[index]) return;
  const cp = cpList[index];
  const d  = new Date(cp.ts);
  const ts = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' at ' + d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  if (!confirm(`Restore checkpoint "${cp.label}" from ${ts}?\n\nThis will overwrite current unsaved changes.`)) return;

  const snap = cp.snapshot;
  const propIdx = _props.findIndex(p => p.id === activePropId);
  if (propIdx === -1) return;

  Object.assign(_props[propIdx], snap);
  closeRecoveryModal();

  // Reload UI from restored snapshot
  renderProperty(_props[propIdx]);
  _setSyncStatus('pending');
  savePropertyData();

  const banner = document.createElement('div');
  banner.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:9999;background:var(--theme-accent);color:var(--c-93c5fd);padding:10px 20px;border-radius:10px;font-size:0.85rem;font-weight:600;box-shadow:0 4px 20px rgba(0,0,0,.5);pointer-events:none;white-space:nowrap;';
  banner.textContent = `↩ Checkpoint restored — ${cp.label}`;
  document.body.appendChild(banner);
  setTimeout(() => banner.remove(), 4000);
}

function exportPropertyBackup() {
  const prop = _props.find(p => p.id === activePropId);
  if (!prop) return;
  const backup = {
    exportedAt: new Date().toISOString(),
    appVersion: 'mainstreet-v1',
    property:   _stripBlobs({ ...prop, activityLog: [...activityLog] }),
    checkpoints: _checkpoints[activePropId] || [],
  };
  const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  const safeName = (prop.name || 'property').replace(/[^a-z0-9]/gi, '_').toLowerCase();
  a.href = url;
  a.download = `mainstreet_backup_${safeName}_${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function rebuildReconciliationState() {
  const prop = _props.find(p => p.id === activePropId);
  if (!prop) return;
  closeRecoveryModal();
  // Reload the property to re-hydrate all globals from canonical storage.
  //
  // renderProperty IS the restore path: it reads camReconciliation (or the
  // legacy results blob), re-hydrates the invoicesFull the save boundary
  // strips, and calls restoreResultsDisplay. What used to follow this line was
  // `if (snapshot exists) restoreResults(prop)` — a second name for that same
  // job, and a function that has never existed in this codebase. So the button
  // threw a ReferenceError on every property that HAD results to rebuild:
  // the modal closed, nothing rebuilt, and the confirmation below never ran, so
  // there was not even a failure to see. A recovery action that silently does
  // nothing is worse than no recovery action.
  renderProperty(prop);
  const banner = document.createElement('div');
  banner.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:9999;background:var(--bgc-134e4a);color:var(--c-99f6e4);padding:10px 20px;border-radius:10px;font-size:0.85rem;font-weight:600;box-shadow:0 4px 20px rgba(0,0,0,.5);pointer-events:none;white-space:nowrap;';
  banner.textContent = '↺ Reconciliation state rebuilt from saved data';
  document.body.appendChild(banner);
  setTimeout(() => banner.remove(), 4000);
}

// ─── Executive Review Mode ───────────────────────────────────────────────────
// _rvKey() defined near _lsUserKey() — returns uid-scoped localStorage key
let _reviewMode = false;

function _rvLoad() {
  try { return JSON.parse(localStorage.getItem(_rvKey()) || '{}'); } catch { return {}; }
}
function _rvSave(tokens) {
  try { localStorage.setItem(_rvKey(), JSON.stringify(tokens)); } catch {}
}
function _genUUID() {
  return ([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g, c =>
    (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16));
}

function generateReviewToken(expiresIn) { // expiresIn: 7, 30, or 0 = never
  try {
  const prop = _props.find(p => p.id === activePropId);
  if (!prop || !lastResults.length) return null;
  const token     = _genUUID();
  const now       = new Date();
  const expiresAt = expiresIn ? new Date(now.getTime() + expiresIn * 86400000).toISOString() : null;
  const payload   = {
    token, expiresAt,
    propId:    prop.id,
    propName:  lastPropName || prop.name,
    camYear:   getCamYear(),
    createdAt: now.toISOString(),
    snapshot:  _stripBlobs({
      propName:    lastPropName || prop.name,
      propId:      prop.id,
      totalSqft:   prop.totalSqft,
      camYear:     getCamYear(),
      results:     [...lastResults],
      total:       lastTotal,
      invoices:    [...lastInvoices],
      invoicesFull:[...lastInvoicesFull],
      tenants:     [...lastTenants],
      camRuns:     camRuns.map(r => ({ ...r, timestamp: r.timestamp instanceof Date ? r.timestamp.toISOString() : r.timestamp })),
      activityLog: [...activityLog],
      invoiceData: invoiceData.map(inv => ({ ...inv })),
      disputes:    [...disputes],
    }),
  };
  const tokens = _rvLoad();
  const cutoff = now;
  Object.keys(tokens).forEach(k => {
    if (tokens[k].expiresAt && new Date(tokens[k].expiresAt) < cutoff) delete tokens[k];
  });
  tokens[token] = payload;
  _rvSave(tokens);
  return payload;
  } catch (e) {
    logError('generateReviewToken', e, { propId: activePropId, expiresIn });
    return null;
  }
}

function validateReviewToken(token) {
  const payload = _rvLoad()[token];
  if (!payload) return null;
  if (payload.expiresAt && new Date(payload.expiresAt) < new Date()) return null;
  return payload;
}

// ─── Generate Review Link Modal ───────────────────────────────────────────────
function openReviewLinkModal() {
  if (!lastResults.length) {
    showToast('Run a CAM allocation first to generate a review link.', { color: '#92400e', textColor: '#fef3c7' });
    return;
  }
  const modal = document.getElementById('reviewLinkModal');
  if (!modal) return;
  document.getElementById('rvLinkOutput').value      = '';
  document.getElementById('rvLinkResult').style.display = 'none';
  modal.style.display = 'flex';
}

function closeReviewLinkModal() {
  const m = document.getElementById('reviewLinkModal');
  if (m) m.style.display = 'none';
}

function confirmGenerateReviewLink() {
  const sel  = document.querySelector('input[name="rvExpiry"]:checked');
  const days = sel ? parseInt(sel.value, 10) : 7;
  const payload = generateReviewToken(days);
  if (!payload) {
    showToast('Could not generate review link — no allocation results found.', { color: '#92400e', textColor: '#fef3c7' });
    return;
  }
  const url = window.location.origin + window.location.pathname + '#review/' + payload.token;
  document.getElementById('rvLinkOutput').value = url;
  document.getElementById('rvLinkResult').style.display = 'block';
  document.getElementById('rvLinkExpiry').textContent = days === 0 ? 'Never expires' : `Expires in ${days} day${days > 1 ? 's' : ''}`;
}

function copyReviewLink() {
  const input = document.getElementById('rvLinkOutput');
  input.select();
  try {
    navigator.clipboard.writeText(input.value).catch(() => document.execCommand('copy'));
  } catch { document.execCommand('copy'); }
  const btn  = document.getElementById('rvCopyBtn');
  const orig = btn.textContent;
  btn.textContent = '✓ Copied!';
  setTimeout(() => { btn.textContent = orig; }, 2000);
}

// ─── Review Mode: Entry & Rendering ──────────────────────────────────────────
function enterReviewMode(payload) {
  try {
  _reviewMode = true;
  const snap = payload.snapshot;

  // Populate all globals from the stored snapshot
  lastResults      = snap.results      || [];
  lastPropName     = snap.propName     || '';
  lastTotal        = snap.total        || 0;
  lastInvoices     = snap.invoices     || [];
  lastInvoicesFull = (snap.invoicesFull || []).map(inv =>
    (inv && !inv.vendor) ? { ...inv, vendor: inv.vendorName || '' } : inv
  );
  lastTenants = snap.tenants || [];
  if (snap.camYear) setCamYear(snap.camYear);
  if (Array.isArray(snap.camRuns) && snap.camRuns.length) {
    camRuns.splice(0, camRuns.length, ...snap.camRuns.map(r => ({
      ...r, timestamp: r.timestamp ? new Date(r.timestamp) : new Date(),
    })));
  }
  activityLog.splice(0, activityLog.length, ...(snap.activityLog || []));
  invoiceData.splice(0, invoiceData.length, ...canonicaliseInvoiceAmounts(snap.invoiceData || []));
  disputes.splice(0, disputes.length, ...(snap.disputes || []));

  // Apply body class — CSS hides all edit controls
  document.body.classList.add('review-mode');

  // Show the review banner
  _renderReviewBanner(payload);

  // Temporarily show mainWorkflow + #results so render functions can run
  document.getElementById('portfolioDashboard').style.display = 'none';
  document.getElementById('propertyBreadcrumb').style.display = 'none';
  const mw = document.getElementById('mainWorkflow');
  const rv = document.getElementById('results');
  mw.style.display = 'block';
  rv.style.display = 'block';

  // Render allocation table into review slot
  const rvBody = document.getElementById('reviewResultsBody');
  if (rvBody) {
    let html = `<div class="summary-bar">
      <strong>Total Expenses:</strong> ${fmt(lastTotal)}
      &nbsp;|&nbsp; <strong>Tenants:</strong> ${lastResults.length}
      &nbsp;|&nbsp; <strong>Invoices:</strong> ${lastInvoicesFull.length}
    </div>`;
    lastResults.forEach(r => {
      html += `<div class="result-card">
        <div class="r-name">${esc(r.name)}</div>
        <div class="result-grid">
          ${stat('Allocated Amount',  fmt(r.allocatedAmount))}
          ${stat('Pro-Rata Share',    (r.proRata * 100).toFixed(2) + '%')}
          ${stat('Included Expenses', r.eligibleCount + ' of ' + lastInvoicesFull.length)}
        </div>
        ${r.capApplied ? `<div class="cap-badge">Cap applied — ${fmt(r.capAdjustment)} reduced</div>` : ''}
      </div>`;
    });
    rvBody.innerHTML = html;
  }

  // Render each AI panel then move it from #results into its review slot
  const _movePanel = (panelId, renderFn, slotId) => {
    renderFn();
    const panel = document.getElementById(panelId);
    const slot  = document.getElementById(slotId);
    if (panel && slot) slot.appendChild(panel);
  };
  _movePanel('narrativePanel', renderNarrativePanel,        'rvNarrativeSlot');
  _movePanel('auditPanel',     renderAuditPanel,            'rvAuditSlot');
  _movePanel('trendsPanel',    renderHistoricalTrendsPanel, 'rvTrendsSlot');
  _movePanel('timelinePanel',  renderActivityTimeline,      'rvTimelineSlot');

  // Hide main workflow — review dashboard takes over
  mw.style.display = 'none';
  document.getElementById('reviewDashboard').style.display = 'block';

  window.scrollTo({ top: 0, behavior: 'instant' });
  } catch (e) {
    logError('enterReviewMode', e, { token: payload?.token, propName: payload?.propName });
    // Show the expired/error screen as a safe fallback
    document.getElementById('portfolioDashboard').style.display = 'none';
    document.getElementById('mainWorkflow').style.display       = 'none';
    const exp = document.getElementById('reviewExpiredMsg');
    if (exp) {
      exp.style.display = 'flex';
      const desc = exp.querySelector('.rv-expired-desc');
      if (desc) desc.textContent = 'An error occurred loading this review. Please request a new link.';
    }
  }
}

function _renderReviewBanner(payload) {
  const banner = document.getElementById('reviewBanner');
  if (!banner) return;
  const createdStr = new Date(payload.createdAt)
    .toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  const expiryStr = payload.expiresAt
    ? 'Expires ' + new Date(payload.expiresAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : 'No expiry';
  banner.innerHTML = `
    <div class="rv-banner-left">
      <span class="rv-ro-badge">READ ONLY</span>
      <span class="rv-prop">${esc(payload.propName)}</span>
      <span class="rv-sep">·</span>
      <span class="rv-year">${esc(String(payload.camYear))} CAM Year</span>
    </div>
    <div class="rv-banner-right">
      <span class="rv-meta">Generated ${createdStr}</span>
      <span class="rv-sep">·</span>
      <span class="rv-meta">${expiryStr}</span>
      <button class="rv-export-btn" onclick="exportReviewPackage()">&#x2B07; Download Package</button>
    </div>`;
  banner.style.display = 'flex';
}

function exportReviewPackage() {
  const now      = new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });
  const safeName = (lastPropName || 'property').replace(/[^a-z0-9]/gi, '_').toLowerCase();
  const year     = getCamYear();

  const gather = id => document.getElementById(id)?.outerHTML || '';
  const narrative = gather('narrativePanel');
  const audit     = gather('auditPanel');
  const trends    = gather('trendsPanel');
  const timeline  = gather('timelinePanel');
  const rvBodyEl  = document.getElementById('reviewResultsBody');
  const resultsHtml = rvBodyEl ? `<div class="card" style="margin-bottom:24px;padding:24px;">
    <h2 style="font-size:1.1rem;font-weight:700;color:var(--text-1);margin-bottom:16px;">${year} Allocation Results</h2>
    ${rvBodyEl.innerHTML}</div>` : '';

  const styles = Array.from(document.styleSheets).flatMap(ss => {
    try { return Array.from(ss.cssRules).map(r => r.cssText); } catch { return []; }
  }).join('\n');

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(lastPropName)} — ${year} CAM Audit Package</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{background:#0B1120;color:#E2E8F0;font-family:'Inter',system-ui,sans-serif;padding:32px 24px}
.rv-pkg-header{background:linear-gradient(135deg,#1a2535,#0B1120);border:1px solid rgba(201,151,58,.3);border-radius:12px;padding:24px;margin-bottom:28px}
.rv-pkg-title{font-size:1.5rem;font-weight:800;color:#C9973A;margin-bottom:4px}
.rv-pkg-meta{font-size:0.84rem;color:#64748B}
${styles}</style>
</head>
<body>
<div class="rv-pkg-header">
  <div class="rv-pkg-title">${esc(lastPropName)} — ${year} CAM Audit Package</div>
  <div class="rv-pkg-meta">Generated ${now} · Executive read-only review</div>
</div>
${narrative}${audit}${trends}${resultsHtml}${timeline}
</body></html>`;

  const blob = new Blob([html], { type: 'text/html' });
  const url  = URL.createObjectURL(blob);
  const a    = Object.assign(document.createElement('a'), { href: url, download: `mainstreet_audit_${safeName}_${year}.html` });
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

// ─── SHA-256 (Web Crypto — no library needed) ─────────────────────────────────
async function sha256(obj) {
  const text   = JSON.stringify(obj, Object.keys(obj).sort());
  const buf    = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(digest))
    .map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
}

